quests[27383] = { id = 27383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klein-Pamela", description = "Die Schlacht von Darroheim verfolgt mich immer noch, {race}. Ich wache in kaltem Schweiß auf, felsenfest davon überzeugt, dass ich noch dort bin. Diese Träume holen mich immer und immer wieder ein.\n\nMit dem Tod meiner Kameraden komme ich einigermaßen klar, aber der Tod meiner Familienmitglieder schmerzt immer noch gnadenlos. Eine meiner Verwandten, die ich bei dem Angriff verloren habe, war meine kleine Nichte Pamela.\n\nWenn Ihr mutig genug seid, Darroheim aufzusuchen, könnt Ihr nach einem Zeichen von meiner kleinen Pammy suchen? Die Ruinen von Darroheim sind südlich von hier.", sourceObjective = "Sucht in Darroheim nach Pamela Rotpfad.", completion = "Hallo. Ich bin Pamela und wie heißt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[27384] = { id = 27384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pamelas Puppe", description = "Meine Tante Marlene hat gesagt, ich soll in unserem Haus bleiben, weil mein Vater in den Kampf ziehen muss. Mein Vater ist der mutigste Mann auf der ganzen Welt!\n\nAber ich bin schon so lange hier und er ist nicht gekommen, um mich abzuholen. Manchmal kommen böse Leute und flüstern mir etwas zu und ich will, dass mein Vater sie wegjagt, aber er ist nicht hier!\n\nUnd manchmal, wenn es dunkel wird, möchte ich mit meiner Puppe spielen, aber das kann ich nicht, weil ich sie in der Stadt gelassen habe.\n\nKönnt Ihr vielleicht meine Puppe für mich suchen?", sourceObjective = "Sucht Pamelas Puppe.", progress = "Habt Ihr meine Puppe gefunden?", completion = "Ihr habt sie gefunden! Ihr habt meine Puppe gefunden! Oh, danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[27385] = { id = 27385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onkel Carlin", description = "Ich werde mit meiner Puppe spielen, aber mit Papas Schwert will ich doch nicht spielen. Ihr könnt es haben.\n\nOder könnt Ihr es vielleicht doch lieber Onkel Carlin geben? Ich weiß nicht, wo er ist, aber manchmal höre ich ihn weinen. Es klingt, als ob er in der Nähe ist, nördlich von hier. Ich hoffe, er weint nicht wegen mir! {name}, könnt Ihr meinen Onkel suchen und ihm sagen, dass es mir gut geht? Wenn Ihr ihn findet, sagt ihm, ich warte auf ihn und ich will die Geschichte hören, die er mir immer erzählt hat ... die von den Kaninchen und der Beerenmarmelade! Die Geschichte ist so witzig!", sourceObjective = "Kehrt zu Carlin Rotpfad am Turm der Kronenwache in den Östlichen Pestländern zurück.", progress = "Gibt es Neuigkeiten von meiner Pammy?", completion = "Ihr habt Pamela gesehen? Ist sie am Leben?\n\nSie ist tot? Nein! Oh, Pamela! Warum leidet dein Geist noch immer in dieser Welt? Warum musstest du sterben, wenn ich am Leben gelassen wurde? Ohne zu zögern würde ich mit dir tauschen und tot durch Darroheim wandern, als Geist und ganz allein! Ah, diese Nachrichten können mein Schicksal nicht ändern. Ich danke Euch, {name}. Jetzt ruft meine Pflicht, die Pflicht nach Rache, lauter als je zuvor.\n\nSagt, was ist das für ein Schwert, das Ihr da habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[27386] = { id = 27386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltsamer Historiker", description = "Dieses Schwert hat Joseph Rotpfad gehört, Pamelas Vater - aber das wisst Ihr wahrscheinlich schon. Ich wünschte, Joseph könnte wieder bei seiner Tochter sein, aber das ist unmöglich. Seine Seele wurde von der Geißel verdreht und er wurde zu einem Monster.\n\nPamelas Schicksal ist besiegelt, aber vielleicht können wir sein Schicksal ändern.\n\nEine komische Gnomin kam hier vor Kurzem am Turm an. Sie heißt Chromie. Bringt dieses Schwert zu ihr. Ich habe das Gefühl, dass sie uns helfen kann.", sourceObjective = "Bringt Josephs Jagdklinge zu Chromie.", progress = "Euer Besuch kommt gerade zur rechten Zeit. Ihr seid nicht aus der Zukunft, oder?", completion = "Was ist das? Ein Kriegsschwert? Ein Buttermesser? Ich habe keine Ahnung von Klingen. Lasst mich das genauer betrachten...\n\nAh! Dieses Schwert hat einst einem guten Mann gehört, aber in der Vergangenheit dieses Mannes ist viel Schlimmes passiert.\n\nSeid Ihr hier, um ihm zu helfen? Dafür ist es schon lange zu spät... aber vielleicht können wir ihm in der Vergangenheit helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27387] = { id = 27387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bösewichte von Darroheim", description = "Die 'Annalen von Darroheim' berichten von den Bösewichten dieser Schlacht. Sie berichten, wie der Ghulfürst Horgus der Verheerer von Allianztruppen während der Schlacht vernichtet wurde. Er wurde im Vorgebirge nördlich von hier getötet und dort liegt sein Schädel noch heute.\n\nMarduk der Schwarze wurde nie besiegt, aber sein sagenhaftes Schwert verrostet nun herrenlos... Man kann es in der Nähe der Straße südöstlich von uns finden.\n\nStellt diese Gegenstände sicher, {name}. Ich weiß nicht, warum, aber ich bin sicher, dass ihr Schicksal in Euren Händen liegt.", sourceObjective = "Bringt den Schädel von Horgus und das zertrümmerte Schwert von Marduk zu Chromie am Turm der Kronenwache in den Östlichen Pestländern.", progress = "Habt Ihr den Schädel und das Schwert gefunden, {name}?", completion = "Ihr habt sie gefunden! Gut gemacht, {name}! Diese Relikte enthalten die Erinnerungen der Streitkräfte der Geißel, die in Darroheim gefallen sind. Diese werden wir brauchen, wenn wir Euren Joseph Rotpfad retten wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27388] = { id = 27388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helden von Darroheim", description = "Die Helden von Darroheim hatten ebenfalls Relikte und darin sind weitere wertvolle Erinnerungen gefangen. Sprecht zunächst mit Carlin und erhaltet die erweiterten Annalen von Darroheim. In diesem Folianten findet sich die Geschichte, die Eure Reise durch die Zeit führen wird.\n\nDanach müsst Ihr westlich reisen, um zu Marris' Siedlung zu gelangen. Der ehemalige Besitzer von Marris' Siedlung sammelte Relikte aus der Schlacht um Darroheim. Warum er das tat, kann ich nicht mit Sicherheit sagen. Sammelt diese Relikte und kehrt zu mir zurück.", sourceObjective = "Erhaltet die Erweiterten Annalen von Darroheim von Carlin Rotpfad sowie Davils Buchband und Rotpfads Schild in Marris' Siedlung.", progress = "Habt Ihr die Relikte, {name}?", completion = "Ihr habt die Relikte? Gut. Ich werde mich darum kümmern, etwaige zeitliche Störstellen zu korrigieren.\n\nSorgt Euch nicht... darüber müsst Ihr Euch wirklich keine Sorgen machen. Ihr seid nur für das Auffinden der Reagenzien zuständig.", sourceObjectiveStatus = "unverified-source-field" }
quests[27389] = { id = 27389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marodeure von Darroheim", description = "Ich benötige ein seltenes Reagenz für den mächtigen Zauberspruch, den zu wirken ich vorhabe: Schädel der Geißelschergen, die an der Schlacht von Darroheim teilnahmen.\n\nNehmt diesen Kristall und jagt Champions der Geißel, um an ihre Schädel zu gelangen. Der Kristall ist verzaubert: Er wird widerhallen, wenn Ihr ihn über den Schädel eines Champions haltet, der an der Schlacht teilgenommen hat. Bringt mir die Schädel der Krieger, bei denen der Kristall widerhallt.\n\nGeht, {name}. Ihr werdet die Champions der Geißel im Fungustal nördlich von hier finden. Geht.", sourceObjective = "Bringt 5 widerhallende Schädel zu Chromie am Turm der Kronenwache in den Östlichen Pestländern.", progress = "Habt Ihr die Schädel? Sie sind für den Zauber unglaublich wichtig. Mit ihrer Hilfe werden wir Darroheim retten können. Möglicherweise.", completion = "Ausgezeichnete Arbeit, {name}. Ihr habt so was wirklich noch nie gemacht?", sourceObjectiveStatus = "unverified-source-field" }
quests[27390] = { id = 27390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Darroheim", description = "Nun, {name}, Ihr werdet an der Schlacht von Darroheim teilnehmen und Joseph Rotpfad retten.\n\nPlatziert dieses Reliktbündel auf dem Marktplatz von Darroheim und die Geister von Darroheim werden sich erheben. Nehmt an der Schlacht teil und sorgt dafür, dass die folgenden zwei Dinge eintreten: Davil muss den Tod von Horgus überleben und Rotpfad muss überleben, um erst verdorben und dann besiegt zu werden.\n\nNachdem Ihr den verderbten Rotpfad besiegt habt, wird seine Seele gerettet sein. Sprecht mit ihm und kehrt dann zu seiner Tochter Pamela zurück.", sourceObjective = "Legt das Reliktbündel auf den Marktplatz von Darroheim.\n\nVerhindert Davil Lichterscheins Tod, bis Horgus stirbt.\n\nVerhindert Hauptmann Rotpfads Tod, bis Rotpfad der Verderbte erscheint.\n\nBesiegt Rotpfad den Verderbten.\n\nSprecht mit dem Geist von Joseph Rotpfad, sobald er auf dem Marktplatz erscheint.", progress = "Ich glaube, ich habe da draußen Geister gehört. Sie flüstern mir schreckliche Dinge zu...", completion = "Der Kampf ist vorüber! Ich habe meinen Vater zu mir flüstern hören. Er hat alle Geister verjagt und sagt, dass er nach Hause kommt! Ich bin so froh!\n\nEr sagte außerdem, dass ich Euch willkommen heißen sollte, wenn Ihr zu uns nach Hause kommt, daher habe ich Euch etwas Tee zubereitet!\n\nIch hoffe, Ihr mögt ihn mit viel Zucker!", sourceObjectiveStatus = "unverified-source-field" }
quests[27391] = { id = 27391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versteckte Schätze", description = "Papa sagte, ich solle Euch diesen Schlüssel geben. Er sagte, er öffnet eine Truhe draußen hinter dem Haus.\n\nEr wollte außerdem, dass ich Euch danke. Habt Ihr ihm einen Gefallen getan? Habt Ihr ihm gesagt, dass Ihr meine Puppe gefunden habt?\n\nNun, hier ist jedenfalls der Schlüssel. Und habt Dank, {name}. Danke! Ihr seid <ein sehr netter Mann/eine sehr nette Dame>!", sourceObjective = "Bringt Josephs Schlüssel zu Josephs Truhe.", progress = "Diese Truhe ist alt und rußverschmiert.", completion = "Der Schlüssel passt in das Schloss und die Truhe öffnet sich...", sourceObjectiveStatus = "unverified-source-field" }
quests[27392] = { id = 27392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich soll Euch das eigentlich nicht verraten", description = "Mein Papa hat immer zwei Schwerter gehabt: eines für den Kampf und eines für die Jagd. Ich sollte eigentlich die Schwerter nicht anfassen, aber ich wusste, wo er sie versteckt.\n\nEines Tages hat er meiner Mama gesagt, dass er einen \"einsamen Jäger\" in den Hügeln östlich von hier bekämpfen würde, aber er hat sein Schwert für die Jagd von Tieren mitgenommen! Als er zurückkam, hatte er kein Schwert bei sich.\n\nWenn Papa zurückkommt, wird er sich so freuen, wenn ich sein Jagdschwert für ihn habe! Könnt Ihr es für mich finden?", sourceObjective = "Erhaltet Josephs Jagdklinge von dem Einsamen Jäger in den Östlichen Pestländern.", progress = "Papa liebte seine Jagdklinge. Er wirkte traurig, als sie weg war.", completion = "Das ist Papas Schwert! Wie habt Ihr es gefunden? Habt Ihr den bösen Jäger gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[27393] = { id = 27393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Klinge", description = "Ich spüre, wie eine starke Macht in den Ruinen nach mir ruft. Könntet Ihr noch einmal auf dem südlichen Schlachtfeld für mich nachsehen? Ich bin mir sicher, dass dort etwas sein muss.", sourceObjective = "Untersucht das Schlachtfeld am südlichen Ende der Ruinen von Vashj'ir.", completion = "Die Wellensprecherin hatte Recht. Da ist etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[27394] = { id = 27394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Klinge", description = "Ich spüre, wie eine starke Macht in den Ruinen nach mir ruft. Könntet Ihr noch einmal auf dem südlichen Schlachtfeld für mich nachsehen? Ich bin mir sicher, dass dort etwas sein muss.", sourceObjective = "Untersucht das Schlachtfeld am südlichen Ende der Ruinen von Vashj'ir.", completion = "Die Wellensprecherin hatte Recht. Da ist etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[27395] = { id = 27395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe eines Schützen", description = "Ihr habt die Wege der Jäger schnell erlernt, {name}. Eure Fähigkeiten sind für die Horde äußerst wertvoll und Ihr seid beispielhaft für den Nachwuchs.\n\nAls Belohnung für Eure Fortschritte und Eure harte Arbeit hat der Kriegshäuptling bei seinem Bogenmacher die Herstellung einer besonderen Waffe in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und erlangt das Zielfernrohr von Lord Godfreys Gewehr, eine Ladung mondbestrahltes Holz und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet Godfreys Kristallzielfernrohr, 5 Bündel mondbestrahltes Holz und 5 ewige Sehnen", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ich fühle mich geehrt, dass der Kriegshäuptling mich beauftragt hat, eine Waffe für Euch herzustellen, {name}. Mit diesen fremdartigen Materialien wird es ein feiner Bogen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27396] = { id = 27396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klinge der Zerschmetterten Hand", description = "Viele Mitglieder der Zerschmetterten Hand überleben ihre Ausbildung nicht, {name}. Ihr habt nicht nur überlebt, sondern werdet bald auch eine gefürchtete Klinge für die Horde darstellen.\n\nAls Belohnung für Euren Fortschritt hat der Kriegshäuptling bei seinem eigenen Schmied eine Waffe in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und beschafft Euch Kommandant Grüntals Wetzstein, eine Ladung Mondstahlbarren, und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet Grüntals Wetzstein von Kommandant Grüntal, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Gordul hat mir schon gesagt, dass Ihr eine Vielzahl ungewöhnlicher Materialien bringen würdet, aber mit so etwas habe ich nun wirklich nicht gerechnet. Mondstahl soll äußerst selten sein und es gibt nur einen Ort von dem ich weiß, an dem man es bekommen kann. Ihr habt für diese Waffe ein großes Risiko auf Euch genommen, {name}, und ich werde dafür sorgen, dass Ihr eine passende Belohnung bekommen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27397] = { id = 27397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aufgabe eines Traumsuchers", description = "Die Elemente und Geister sprechen in klaren Stimmen zu Euch, {name}. Ihr seid ein mächtiges Mitglied in den Rängen der Schamanen und ein Beispiel für alle, die der Horde dienen möchten.\n\nSelbst der Kriegshäuptling hat von Euch erfahren, und er hat bei seinem Schmied die Herstellung einer besonderen Waffe für Euch in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und erlangt Lord Waldens Talisman, das Buch der verlorenen Seelen und Essenzen der Geister, die das Schloss heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet den Talisman des Wolfmeisters von Wolfmeister Nandos, das Buch der verlorenen Seelen und 5 geisterhafte Essenzen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ah, Ihr müsst {name} sein. Kardris sagte, dass Ihr Euch nach Burg Schattenfang aufgemacht habt, um die Materialien zu finden, die für diese Waffe benötigt werden. Ich sehe, Ihr habt uns nicht enttäuscht. Ich werde eine mächtige Waffe herstellen, die der Materialien würdig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27398] = { id = 27398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht ist gewonnen, der Krieg geht weiter", description = "Wir haben die Truppen des Feindes hier besiegt, {name}. Aber der Hyjal ist nicht der einzige Ort, an dem unsere Feinde gegen uns vorrücken.\n\nMan hat mir berichtet, dass unsere Verbündeten des Irdenen Rings in einer Angelegenheit um Hilfe gebeten haben, die keinen Aufschub duldet.\n\nErdsprecher Naraat am Östlichen Erdschrein in Sturmwind wird Euch weitere Anweisungen erteilen.", sourceObjective = "Sprecht mit Erdsprecher Naraat am Östlichen Erdschrein in Sturmwind.", completion = "Eure Hilfe kommt genau zur rechten Zeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27399] = { id = 27399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht ist gewonnen, der Krieg geht weiter", description = "Wir haben die Truppen des Feindes hier besiegt, {name}. Aber der Hyjal ist nicht der einzige Ort, an dem unsere Feinde gegen uns vorrücken.\n\nMan hat mir berichtet, dass unsere Verbündeten des Irdenen Rings in einer Angelegenheit um Hilfe gebeten haben, die keinen Aufschub duldet.\n\nScharfseher Krogar am Westlichen Erdschrein in Orgrimmar wird Euch weitere Anweisungen erteilen.", sourceObjective = "Sprecht mit Scharfseher Krogar am Westlichen Erdschrein in Orgrimmar.", completion = "Eure Hilfe kommt genau zur rechten Zeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27400] = { id = 27400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschung des Arkanen", description = "Alle Eure Lehrer sind sich einig, {name}, dass Ihr für einen Gesellen unglaubliches Talent zeigt. Selbst der Kriegshäuptling hat von Eurem schnellen Fortschritt gehört.\n\nAls Belohnung für Eurer Verständnis für das Erlernte hat der Kriegshäuptling bei seinem Verzauberkunstmeister die Herstellung eines besonderen Stabs in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das magische Erbe der Familie Silberlein, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erlangt Silberleins verzauberten Kristall von Baron Silberlein, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ah, Ihr müsst die {class} sein, die Uthel'nay erwähnte. Ich habe Geschichten über die Artefakte der Familie Silberlein gehört, aber sie bisher nie zu Gesicht bekommen. Das sollte einen ausgezeichneten Fokus bei Eurem Stab machen. Lasst uns anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27401] = { id = 27401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was uns morgen erwartet", description = "<Das K.d.V. summt.>\n\nSeht Euch im Kathedralenviertel um. Dort sollte irgendwo ein Teleskop sein, das die 7. Legion zur Beobachtung benutzt. Findet es und benutzt es, um den Hafen auszuspähen. Wir müssen herausfinden, wie die 7. Legion an unserer Flotte vorbeigekommen ist.\n\nBeeilt Euch, {name}. Wir können diese Bestien nicht sehr viel länger zurückhalten.\n\nWas uns morgen wohl erwartet?", sourceObjective = "Benutzt das Teleskop der 7. Legion, um den Hafen auszuspähen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27402] = { id = 27402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen der Macht", description = "Ihr erlernt unsere Wege in einem atemraubenden Tempo, {name}, und ich bin bei Weitem nicht der Einzige, der von Eurem Fortschritt beeindruckt ist. Der Kriegshäuptling selbst hat Eure Taten schon zur Kenntnis genommen.\n\nAls Belohnung für Eure Hingabe hat der Kriegshäuptling bei seinem eigenen Verzauberer die Herstellung eines Stabes in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und erlangt die finstere Kugel von Lord Godfrey, das Buch der verlorenen Seelen und Essenzen der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet die Finstere Kugel von Lord Godfrey, das Buch der verlorenen Seelen und 5 geisterhafte Essenzen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ihr seid also der Hexenmeister, für den dieser Stab ist. Es wird eine passende Belohnung für jemanden, der mit solcher Hingabe für den Machterlang und die Vorherrschaft der Horde kämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[27403] = { id = 27403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein echter Sonnenwandler", description = "Ich habe Eure Ausbildung beobachtet, {name}. Ihr habt den Weg eines beispielhaften Sonnenwandlers eingeschlagen und seid ein mutiger Verteidiger der Horde und ein Anhänger unserer Wege.\n\nAls Belohnung für Eure Hingabe hat der Kriegshäuptling bei seinem eigenen Schmied eine besondere Waffe in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das heilige Symbol von Kommandant Grüntal, eine Ladung Mondstahlbarren und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und findet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Kisten Mondstahlbarren, und 5 ewige Sehnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27404] = { id = 27404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft des Zirkels", description = "Der Zirkel des Cenarius ist zufrieden mit Eurem Fortschritt, {name}. Ihr seid von Wert für alle Druiden. Wir sehen in Euch und Euren Verbündeten die Zukunft unserer Bruderschaft.\n\nDer Zirkel hat entschieden, Euch mit der Herstellung eines einzigartigen Stabs zu ehren.\n\nDie seltenen und mächtigen Materialien für diesen Stab können nur in Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet Lord Waldens Elixiersammlung, eine Ladung mondbestrahltes Holz und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet Waldens Elixiere von Lord Walden, 5 Bündel mondbestrahltes Holz und 5 ewige Sehnen.", progress = "Habt Ihr die Materialien besorgt, die ich für Euren Stab benötige?", completion = "Ah, Ihr müsst der {class} sein, von dem Loganaar erzählt hat. Ich freue mich, Euch endlich zu treffen, {name}. Ich habe schon oft gehört, wie Mitglieder des Zirkels Euch als talentiert und vielversprechend für die Reihen der Druiden halten, und ich freue mich, dass ihre Einschätzungen auch der Wahrheit entsprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27405] = { id = 27405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückzug!", description = "<Das K.d.V. summt.>\n\n<Im Hintergrund ist Worgengeheul zu vernehmen.>\n\n{name}, hört Ihr mich? Kommen, {name}. Das ist wahrscheinlich meine letzte Übertragung. Die Worgen haben den Gefechtsstand der Verlassenen überrannt. Es ist nur eine Frage der Zeit, bis wir den Stützpunkt verlieren. Belmont und die Val'kyr Arthura sind weg. Belmont meinte, er wird Euch in Glutstein treffen, nordöstlich von hier. Findet Belmont, {name}. Unsere Mission - unsere Existenz - hängt davon ab.\n\nIhr seid unsere letzte Hoffnung.", sourceObjective = "Findet Todespirscherkommandant Belmont in Glutstein in den Ruinen von Gilneas.", completion = "Vorpostenkommandant Ansturm hat bis zum bitteren Ende gekämpft, {name}. Erst eine Meute blutdurstiger Worgen konnte ihn niederringen. Sein Tod und der Tod all unserer Soldaten in Gilneas darf nicht umsonst gewesen sein. Unsere Mission MUSS gelingen.\n\nJetzt werde ich Euch enthüllen, warum wir hier sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27406] = { id = 27406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mann namens Godfrey", description = "Lord Vincent Godfrey hat sein Leben mit der Verteidigung des Königreich Gilneas verbracht. Als der Fluch der Worgen sein Land verheerte, war Godfrey der Erste in Gilneas, der die Waffen gegen die Bestien erhob. Es wird gesagt, dass Godfrey sein Leben nahm, als er herausfand, dass sein König dem Fluch zum Opfer gefallen war. Lieber sei er tot, als dass er den Kreaturen diene, gegen die er sein Land verteidigt hatte.\n\nWir werden ihm eine zweite Chance geben, {name}. Zusammen werden wir die Schlacht nach Südosten vorantreiben, nach Witterfront, und dort seinen Leichnam einholen.", sourceObjective = "Findet die Leiche von Lord Vincent Godfrey.", completion = "Hier, {name}. Er ist ein wenig verfault, aber es könnte schlimmer sein. Wir müssen uns beeilen, bevor die Allianz uns findet!", sourceObjectiveStatus = "unverified-source-field" }
quests[27407] = { id = 27407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutsumpffedern", description = "Hat Euch Broggs Anwesenheit erschreckt, {race}? Sorgt Euch nicht. Die Goblins von Morastwinkel sind Broggs Freunde und Ihr könnt es auch werden.\n\nBrogg hat Brackenwall verlassen, nachdem der neue Oberanführer nicht Rache an den Drachkin geübt hatte, die für Zerstörung unserer alten Heimat und Tod vieler alter Freunde von Brogg verantwortlich sind. Brogg ist hierhergekommen, um Geister seiner Freunde zur letzten Ruhe zu betten und für sie Rache zu üben, doch Brogg braucht Hilfe bei Vorbereitungen. Für Ritual braucht Brogg Federn mit mächtiger Magie, Federn wie die der Raptoren aus Blutsumpfbau.", sourceObjective = "Sammelt 5 Blutsumpffedern von Blutsumpfraptoren.", progress = "<Brogg blickt Euch voller Hoffnung an.>\n\nIhr bringt Brogg Federn?", completion = "<Brogg nimmt die Federn an sich.>\n\nBrogg froh über die Federn. Sehr mächtige Magie. Brogg weiß nicht, wie Raptoren Federn Macht geben, aber Raptorenfedern immer am besten für Ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[27408] = { id = 27408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Banner der Steinbrecher", description = "Als die Drachen über Broggs alte Heimat herfielen, flohen die Steinbrecheroger und ließen alles zurück, sogar das Klanbanner.\n\nBrogg weiß, dass das Banner tief im Ogerhort aufbewahrt wurde. Jetzt heißt der Ort Flammenbau.\n\nBrogg braucht Klanbanner für seine Rache an den Drachen, die seine Freunde auf dem Gewissen haben. Der alte Hort von Broggs Klan, der Flammenbau, befindet sich nordwestlich von Morastwinkel und überall treiben sich Drachkin herum. Banner ist tief in der Höhle. Seid vorsichtig, {name}.", sourceObjective = "Beschafft das Banner der Steinbrecher aus Flammenbau.", progress = "Ihr bringt Banner der Steinbrecher?", completion = "Brogg dankt Euch, {name}. Brogg hat große Pläne für Klanbanner.", sourceObjectiveStatus = "unverified-source-field" }
quests[27409] = { id = 27409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz der Feindschaft", description = "Damit Brogg das Totem für sein Ritual herstellen kann, benötigt er die Essenzen der Kreaturen, die seine Freunde getötet haben. Der Hass und die Wut von Broggs Feinden wird die Magie seiner Rache verstärken.\n\nTötet Aschenschweife, Späher oder Bannschuppen der Feuermähnen und wendet Broggs Totem auf ihren Leichen an. Nur tote Drachkin geben ihre Essenzen frei.\n\nDie Kreaturen, die Ihr sucht, befinden sich im Flammenbau im Nordwesten und in den Ruinen der Steinbrecher im Norden.", sourceObjective = "Bringt 10 Essenzen eines schwarzen Drachkin zu Brogg in Morastwinkel.", progress = "Habt Ihr die Essenzen? Brogg braucht sie, um seine Freunde zu rächen!", completion = "Brogg dankt Euch, {name}. Sobald Brogg die Magie der Essenzen zu dem Totem hinzufügt, kann das Totem die Geister von Broggs gefallenen Freunden befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[27410] = { id = 27410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister der Festung der Steinbrecher", description = "Brogg hat das Totem fertig gestellt, mit dem den Geistern seiner Freunde Frieden gegeben werden kann. Als die Drachkin einfielen, töteten sie alle Steinbrecher, die nicht rechtzeitig fliehen konnten. Brogg entkam zusammen mit Oberanführer Mok'Morokk, in der Hoffnung auf einen gemeinsamen Gegenangriff mit den anderen überlebenden Steinbrechern.\n\nDoch der Gegenangriff fand nie statt und die Geister der Gefallenen verfolgen Brogg und die anderen noch immer. Nehmt das Totem und begebt Euch zu den Ruinen der Steinbrecher nördlich von hier; verwendet das Totem in der Nähe von Ogerskeletten, um die Geister anzulocken. Besiegt die Geister und ermöglicht ihnen und ihren Knochen die letzte Ruhe.", sourceObjective = "Gebt 10 Geistern der Steinbrecher bei den Ruinen der Steinbrecher ihre letzte Ruhe.", progress = "Brogg muss wissen, habt Ihr den brutalen Geistern der Steinbrecher Frieden geben können?", completion = "Brogg dankt Euch für Eure Hilfe, obwohl er weiß, dass Oberanführer Mok'Morokk nicht dankbar sein wird. Jetzt können Überlebende der Steinbrecher endlich Probleme der Lebenden lösen und die Toten hinter sich lassen. Brogg muss nur noch eine Sache machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27411] = { id = 27411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung für den schwarzen Drachenschwarm", description = "Brogg kann es kaum erwarten, endlich Rache an dem schwarzen Drachenschwarm der Marschen zu üben. {name}, Ihr habt bei den Vorbereitungen für diesen Augenblick sehr geholfen. Werdet Ihr mir auch weiterhin zur Seite stehen?\n\nNehmt Broggs Klanbanner und reist in Richtung Osten, bis Ihr eine Höhle seht, die wie das Maul eines Drachen aussieht. Stellt das Banner der Steinbrecher direkt vor dem Höhleneingang auf und überbringt Onyxia Broggs Herausforderung.\n\nBrogg und die Steinbrecher werden ihr Land zurückerlangen!", sourceObjective = "Platziert das Banner der Steinbrecher am Eingang zu Onyxias Hort und besiegt alle, die reagieren.", progress = "Brogg wird seine Rache üben können!", completion = "<Brogg hört Euch zu, als Ihr von den Erlebnissen am Eingang zu Onyxias Hort berichtet.>\n\nBrogg weiß Onyxia tot. Brogg weiß Onyxias Brut noch da. Brogg lässt sie Steinbrecher niemals vergessen.\n\nBrogg ist dankbar für Eure Hilfe, {name}, und wird nie vergessen, was Ihr für ihn getan habt. Brogg wird nicht ruhen, bis er die Steinbrecher wieder in ihre Heimat gebracht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27412] = { id = 27412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Schlächterklaue der Gefräßige", description = "Reisende und Mitarbeiter des Dampfdruckkartells werden aufgefordert, Blutsumpfbau westlich der Siedlung weiträumig zu umgehen.\n\nDas gesamte Areal wird von äußerst gefährlichen Raptoren bewohnt. Das Leittier, Schlächterklaue der Gefräßige, ist für den Tod von mindestens zwei Ingenieuren des Dampfdruckkartells verantwortlich.\n\nDrazzit Tropfhahn hat eine großzügige Belohnung ausgeschrieben, die ausgezahlt wird, wenn der Bedrohung durch Schlächterklaue in Morastwinkel ein Ende gesetzt wird.", sourceObjective = "Tötet Schlächterklaue den Gefräßigen und meldet Euch bei Drazzit Tropfhahn in Morastwinkel.", completion = "Zum Glück ist endlich jemand meiner Aufforderung nachgekommen. Ich dachte schon, dass ich die Belohnung verdreifachen müsste, bevor jemand diesen verdammten Raptor zur Strecke bringt, und das ließ unser Budget einfach nicht zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[27413] = { id = 27413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwindet den Drachen", description = "Durch den Absturz des Zeppelins mitsamt unseren Vorräten gehen uns langsam die Medikamente und Verbände aus.\n\nWir tun was wir können, aber inmitten all dieser Insekten, umgeben von Feinden bleiben Verletzungen nicht aus, und ich komme meiner Arbeit kaum nach! Ich habe kürzlich eine Pflanze entdeckt, welche die Wundheilung unterstützt und Schmerzen lindern kann, doch auch dieser Vorrat geht zur Neige.\n\nDie Pflanze heißt Drachenwinde und sie wächst in Drachendüster und in Drachensumpf östlich von unserer Siedlung. Die Pflanze besteht aus gewundenen Stängeln und wenn man sie ansieht, scheint sie zu pulsieren.", sourceObjective = "Sammelt 8 Stängel der Drachenwinde in Drachendüster oder in Drachensumpf.", progress = "Konntet Ihr die Drachenwinde finden?", completion = "Vielen Dank! Damit kann ich unsere Jungs versorgen, bis Moxie mit den Vorräten von der Zeppelinabsturzstelle zurückkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27414] = { id = 27414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut identifizieren", description = "Während der törichte Narr Mok'Morokk seine Macht genießt und Tharg mit den Dämonen des Kummers und der Rache ringt und um die Führerschaft des Klans buhlt, scheine ich der Einzige zu sein, der die Ursache der Aggression in unserer alten Heimat herausfinden möchte.\n\nWarum der verwirrte Blick, {name}? Habt Ihr erwartet, dass ich wie ein tumber Grobian spreche, nur weil ich ein Oger bin?\n\nWidmen wir uns wieder dem wichtigeren Thema: Bringt mir die Herzen und Zungen der Welpen und Jungtiere. Ich werde herausfinden, was es mit diesem Übel auf sich hat ...", sourceObjective = "Draz'Zilb in Brackenwall möchte, dass Ihr ihm 7 sengende Zungen und 7 sengende Herzen bringt.", progress = "An den Herzen und der Zungen der versengten Nachkommen der Armee der schwarzen Großdrachen kann ich erkennen, von welcher Bestie sie abstammen. Wenn wir mehr über unsere Angreifer wissen, können wir sie vielleicht besser bekämpfen und sie ein für alle Mal zerstören, und die Siedlung der Steinbrecher aus den Ruinen retten.\n\nAllerdings wird es schon eine wahrhaft epische Aufgabe, Mok'Morokk davon zu überzeugen, seinen lethargischen Hintern aus dem Schlammloch zu bewegen ...", completion = "Zweifellos war es eine gefährliche Sache, diese Herzen und Zungen zu sammeln. Ich werde nun in die Tiefen des Arkanen vorstoßen, um den Ursprung der schwarzen Bedrohung zu finden, die über unsere einstige Heimat kam.", sourceObjectiveStatus = "unverified-source-field" }
quests[27415] = { id = 27415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut von Onyxia", description = "Onyxias Brut wurde über ganz Drachendüster verstreut. Es dürfen auf keinen Fall weitere Welpen schlüpfen.\n\nEilt nach Drachensumpf im Süden von Düstermarschen. Gewiss hat sie dort ihren Hort angelegt. Sucht die Eier der bösen Großdrachen und vernichtet sie.\n\nWir werden das Dorf der Steinbrecher nie zurückerobern können, wenn das Umland eine Brutstätte bleibt.\n\nWas Mok'Morokk angeht ... für den Jammerlappen habe ich andere Pläne.", sourceObjective = "Zerstört 5 Eier von Onyxia.", completion = "Großartig! Es wird einige Zeit dauern, bis Onyxia wieder Eier legen kann.\n\nIm Namen meines Volkes danke ich Euch, {name}.\n\nIch habe bislang viel von Euch verlangt. Vielleicht könnt Ihr jedoch dem Steinbrecherklan einen letzten Dienst erweisen.\n\nMok'Morokk ist nicht in der Lage, uns anzuführen. Tharg wäre ein ausgezeichneter Anführer, sieht sich aber durch seine Verletzungen und sein Alter daran gehindert. Vertreibt Mok'Morokk mit Gewalt von hier. Erst dann können wir einen neuen Anführer bestimmen und in unsere angestammte Heimat im Süden zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27416] = { id = 27416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut von Onyxia", description = "Das Dorf der Steinbrecher wurde von Onyxias Brut überfallen. Aber warum sollte die Tochter des schwarzen Drachenlords Todesschwinge über unser Land herfallen?\n\nEs ist äußerst beunruhigend. Sicherlich wurde Onyxia aus einem anderen Grund hergeschickt, als nur eine kleine Schar von Ogern zu belagern.\n\nVerständigt Mok'Morokk auf der Stelle! Es muss etwas getan werden.", sourceObjective = "Sprecht mit Oberanführer Mok'Morokk in Brackenwall.", completion = "Warum erzählt Ihr mir von Drachen? Ich mag Drachen nicht. Ich mag es hier. Hier keine Drachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27417] = { id = 27417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut von Onyxia", description = "Lasst mich jetzt allein. Sagt Draz'Zilb, dass ich hier bleibe. Hier keine schwarzen Großdrachen.", sourceObjective = "Sprecht mit Draz'Zilb in Brackenwall.", completion = "Dieser träge Feigling!\n\nMok'Morokk hat Stärke gezeigt, als Rexxar noch unser Anführer war. Doch kurz nach Rexxars Abschied erlag Mok'Morokk den Verlockungen der Macht. Er führte nicht, sondern forderte. Er dient seinem Volk nicht, sondern erwartet, dass wir ihm dienen.\n\nEs muss etwas geschehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27418] = { id = 27418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fordert Oberanführer Mok'Morokk heraus", description = "Ihr wagt es, Oberanführer Mok'Morokk herauszufordern?\n\nHa!\n\nIch zerschmettern Winzling von {race}!\n\nIhr sagt mir, wenn bereit für ordentliche Tracht Prügel.", sourceObjective = "Besiegt Mok'Morokk und erstattet Draz'Zilb in Brackenwall Bericht.", completion = "Dieser feige Fettwanst Mok'Morokk ist geflohen wie ein ängstliches Kind. Ihr habt uns einen großen Dienst erwiesen, {name}.\n\nJetzt kann mein Volk einen neuen Anführer bestimmen, mit dem wir unsere angestammte Heimat ein für alle Mal zurückerobern werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27419] = { id = 27419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armee des schwarzen Großdrachen", description = "Mok'Morokk wurde von Rexxar zum Oberanführer gemacht. Ihm liegt mehr an Macht als an den Ogern.\n\nSchwarze Großdrachen töten viele Oger. Töten Thargs Frau. Mok'Morokk sagt uns, wir müssen fliehen. Lässt uns hierher kommen.\n\nOger sollten kämpfen. Oger nicht gut im Weglaufen. Mok'Morokk schert sich nur um Mok'Morokk.\n\nFür mich die Ruinen der Steinbrecher Heimat. Mir gefallen im Süden. Dieser Ort nicht Heimat.\n\nHelft Ogern, Armee der schwarzen Großdrachen zu bekämpfen. Ich wollen Rache. Ich wollen nach Hause.", sourceObjective = "Tharg in Brackenwall möchte, dass Ihr 10 Späher der Feuermähnen, 10 Aschenschweife der Feuermähnen und 5 Bannschuppen der Feuermähnen tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27420] = { id = 27420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Unvermeidliche hinauszögern", description = "Ihr habt ein gutes Auge, wenn Ihr mich hier in meinem Versteck im Gras sehen konntet.\n\nDas Fungustal liegt vor uns, eine Gegend, an die sich die Geißel noch immer klammert. Sie benutzen schwebende Konstrukte, um das Land ständig neu zu verseuchen, damit es so abstoßend bleibt, wie es jetzt ist.\n\nDie Konstrukte werden von Runen der dunklen Adepten und der Schattenmagier gesteuert. Nehmt die Kontrollrunen der Kultisten an Euch, zielt damit auf die Seuchenverbreiter und erzeugt mit diesem Partikel eine Überlast. Das Ergebnis sollte recht amüsant sein.", sourceObjective = "Erhaltet Kontrollrunen von den dunklen Kultisten und Schattenmagiern und benutzt das überladene Partikel, um 3 Seuchenverbeiter zu zerstören.", completion = "Je eher die Geißel aus dem Fungustal vertrieben ist, desto eher können wir es heilen.\n\nVielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27421] = { id = 27421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitten im Tod ist Leben", description = "Die Streitmächte der Geißel haben es geschafft, jeglichem Leben im Fungustal ein Ende zu bereiten. Das Einzige, was noch zu finden ist, sind die Überreste verfaulter Pilze und versengte Gräser. In den drei Ecken des Tals sind drei große Ziggurats zu finden, in denen die Geißel ihre Toten reanimiert und neue Soldaten für das Schlachtfeld einberuft.\n\nDoch selbst an diesem bösen, leblosen Ort kann Leben gedeihen. Nehmt diese Samen und planzt sie in die Zentren der Ziggurats. Beweist ihnen, dass sich das Leben durchsetzen wird.", sourceObjective = "Pflanzt Raynes Samenkörner in den Zentren der drei Ziggurats im Fungustal.", completion = "Selbst wenn die Blumen verwelkt sind, kurz nachdem sie geblüht haben, wird das der Geißel eines klarmachen: sie verlieren und wir gewinnen.\n\nVielen Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27422] = { id = 27422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Stadt unter Belagerung", description = "Wir werden die Östlichen Pestländer nie unter Kontrolle bekommen, wenn wir Stratholme nicht im Besitz haben. Stratholme ist nicht nur ein strategisch unglaublich wichtiger Ort, sondern auch die Heimat der Anführer unserer Feinde - Balnazzar und Baron Aurius Totenschwur. Ihre Armeen der Auferstandenen und der Geißel drohen jedoch, alle unsere Fortschritte nichtig zu machen.\n\nDer Argentumkreuzzug ist wie geschaffen, sich dieser Aufgabe anzunehmen. Reist nach Westen, betretet Stratholme durch das Haupttor, und sprecht mit Rottenkommandant Steinberster. Er wird Euch weitere Anweisungen geben.", sourceObjective = "Sprecht mit Rottenkommandant Steinberster.", completion = "Welch eine Erleichterung einen tauglichen Soldaten an unserer Seite zu haben. Hier gibt es genug für Euch zu tun, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27423] = { id = 27423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerstand ist zwecklos", description = "<Das K.d.V. summt.>\n\nHier spricht Kommandantin Lorna Crowley von der Gilnearischen Befreiungsfront. Wenn Ihr diese Nachricht hört, bedeutet das, dass die Allianz Gilneas wieder eingenommen hat. Legt Eure Waffen nieder und kapituliert. Wenn Ihr dieser Aufforderung nicht nachkommt, steht Euch der sichere Tod bevor.\n\nUnsere Streitmächte sind über Euren Standort informiert und werden in Kürze eintreffen. Widerstand ist zwecklos.", sourceObjective = "Tötet 20 Kämpfer der Worgen.", completion = "Wir haben keine Zeit, um uns am Ruhm der Schlacht zu laben, {name}. Es gibt Arbeit. Ich bin mir sicher, dass noch mehr von diesen Biestern unterwegs sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27424] = { id = 27424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberanführer Mok'Morokks Sorgen", description = "Verbeugen Euch vor Oberanführer Mok'Morokk!\n\nRexxar mich machen zu mächtigem Anführer von Steinbrecherklan!\n\nIch guter Anführer. Ich auf Klan aufpasse.\n\nGroße Drachen machen Feuer in alte Heimat. Ich schlauer Oger. Finden neue Heimat für Klan hier.\n\nAber alte Heimat so schnell verlassen, ich Sachen vergessen. Winzig {race}, gehen mein Sachen holen. Gehen nach Süden und suchen mein lecker Grog, Schnupftabak und Geldkassette. Ich Euch dann mögen. Ihr in Flammenbau und Ruinen der Steinbrecher schauen ... alles dort sein, ich sicher!", sourceObjective = "Holt Oberanführer Mok'Morokks Grog, Mok'Morokks Schnupftabak und Mok'Morokks Geldkassette aus Düstermarschen.", progress = "Ich Durst auf Grog. Und Lust auf Schnupftabak. Wo ist Geldkassette? Ihr geht holen für Oberanführer Mok'Morokk.\n\nGeht holen in Süden in alter Heimat. Ich mit Anführen von Ogern beschäftigt.", completion = "Gut, {race}. Ich haben Sachen arg vermisst. Ich Euch jetzt mag.", sourceObjectiveStatus = "unverified-source-field" }
quests[27425] = { id = 27425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der entscheidende Grimmweis", description = "Ich habe mich mit Inspektor Tarem über die Beweise, die Ihr bei den Ruinen des Gasthauses \"Zur Süßen Ruh\" gefunden habt, unterhalten. Er ist sich sicher, dass die Hufabdrücke und der Schild auf den Taurenklan der Grimmtotem hindeuten.\n\nBedenkt man die jüngsten Berichte über die zunehmenden Aktivitäten der Grimmtotem in den Marschen, so handelt es sich sicherlich nicht um einen bloßen Zufall. Ich bitte Euch, mit Hauptmann Darill zu sprechen. Er ist so eine Art Experte in Sachen Grimmtotem. Folgt der Straße aus dem Dorf in Richtung Norden nach Nordwacht. Es ist der zweite Außenposten entlang der Straße.", sourceObjective = "Berichtet Hauptmann Darill in Nordwacht.", completion = "Hauptmann Mumm meint, die Grimmtotem stecken hinter dem Angriff auf das Gasthaus \"Zur Süßen Ruh\"? Auf meiner Verdächtigenliste wären sie jetzt nicht weit oben, aber wenn Hauptmann Mumm Euch schickt, um einem Hinweis zu folgen, hat er sicherlich gute Gründe. Davon aber abgesehen, die Grimmtotem sind uns schon seit einiger Zeit ein Dorn im Auge und wir sind immer über zusätzliche Hilfe dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27426] = { id = 27426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestätigung des Verdachts", description = "Die Grimmtotem mögen der kriegerischste Klan der Tauren sein, aber sie sind keineswegs unorganisiert. Wenn sie das Gasthaus \"Zur Süßen Ruh\" wirklich in Brand gesteckt haben, dann nur auf Befehl von einem der Klanältesten.\n\nNordwestlich von hier liegt eine große Siedlung der Grimmtotem, das Dorf der Schwarzhufe. Sie haben das Dorf als Ausgangsbasis für ihre Angriffe auf den Turm genutzt, aber ich bin mir ganz sicher, dass Ihr dort auch die Befehle finden könnt. Sucht bei den Ältesten im Dorf nach den Befehlen, die Ihr für Eure Ermittlungen benötigt.", sourceObjective = "Erlangt 4 Notizen der Grimmtotem von den Ältesten der Grimmtotem. Setzt die Teile zusammen, um die Schlachtpläne der Grimmtotem zu sehen.", progress = "Konntet Ihr die Befehle ausfindig machen?", completion = "<Hauptmann Darill überfliegt die Schlachtpläne.>\n\nIch glaube, deutlicher kann es kaum werden. Sie haben es sich zur Aufgabe gemacht, die Menschen aus den Siedlungen in der Gegend zu vertreiben. Ich bezweifle nicht, dass Theramore ihr nächstes Ziel sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[27427] = { id = 27427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen der Grimmtotem", description = "Wenn die Ausrüstung, die Ihr bei den Ruinen des Gasthauses gefunden habt, zu einem Angriffstrupp der Grimmtotem gehörte, dann gibt es vermutlich noch mehr davon in ihrem Lager nordwestlich von hier.\n\nBis jetzt konnten wir noch nicht viel über das Dorf der Schwarzhufe in Erfahrung bringen, aber ausgehend von der Größe ihrer Angriffstrupps schätzen wir, dass sich dort eine größere Streitmacht aufhält.\n\nTut, was auch immer Ihr tun müsst, um einige ihrer Ausrüstungsgegenstände zu erbeuten, damit wir sie mit Eurem Fund beim Gasthaus vergleichen können.", sourceObjective = "Hauptmann Darill in Nordwacht möchte, dass Ihr ihm 7 Waffen der Schwarzhufe bringt.", progress = "Habt Ihr diese Waffen aus dem Dorf der Schwarzhufe?", completion = "<Hauptmann Darill betrachtet die Waffen, die Ihr aus dem Dorf der Schwarzhufe mitgebracht habt.>\n\nEs gibt keine Zweifel mehr. Diese Waffen stimmen genau mit der Beschreibung überein. Es gibt nur ein Problem - mit diesen Waffen wurde noch nie gekämpft. Das Dorf der Schwarzhufe ist wohl nicht der einzige Posten der Grimmtotem in den Marschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27428] = { id = 27428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabethas Unterstützung", description = "Ich kann keine Männer mehr entbehren, um Euch bei der Suche nach einem zweiten Außenposten der Grimmtotem zu helfen. Ich kenne aber jemanden, der Euch behilflich sein könnte.\n\nTief im Morast, südlich von hier, liegt ein kleiner Hof, der Tabetha gehört. Sie mag zwar wie eine alte Einsiedlerin erscheinen, aber in Wirklichkeit ist sie eine Magierin und recht angesehene Wahrsagerin. Folgt der Straße in Richtung Süden bis zu ihrem Hof und bittet sie um Hilfe bei der Suche nach den Übeltätern, die für das Massaker beim Gasthaus \"Zur Süßen Ruh\" verantwortlich sind.", sourceObjective = "Sprecht mit Tabetha auf ihrem Hof.", completion = "Ihr möchtet also, dass ich die Grimmtotem durch meine Weissagungen ausfindig mache, ja? Was würdet Ihr sagen, wenn ich Euch verrate, dass es keinerlei Weissagung dafür bedarf?", sourceObjectiveStatus = "unverified-source-field" }
quests[27429] = { id = 27429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennt den Grollhornposten nieder!", description = "Man muss nicht Hellsehen können, um zu wissen, welche Schwierigkeiten meine neuen \"Nachbarn\" hier heraufbeschwören. Falls es sich bei ihnen wirklich um diejenigen handelt, die das Gasthaus \"Zur Süßen Ruh\" niedergebrannt haben, dann gibt es keinen Grund mehr, sie hier noch länger zu dulden.\n\nNehmt diese Fackel und brennt ihr Lager nieder! Der Grollhornposten liegt nördlich von meinem Hof, in der Nähe der Straße. Ihr könnt ihn nicht verfehlen, wirklich. Die Grimmtotem haben ganze Arbeit geleistet und ihre Anwesenheit durch das Aufstellen ihrer Totem förmlich angekündigt.", sourceObjective = "Benutzt Tabethas Fackel, um das nördliche Zelt, das östliche Zelt und das nordöstliche Zelt am Grollhornposten in Flammen zu setzen.", progress = "Hat die Fackel ihren Zweck erfüllt?", completion = "Ich hoffe, die Grimmtotem haben unsere Nachricht verstanden. Jeder Rückkehrversuch wird mit schlimmeren Mitteln als einer Fackel beantwortet werden. Meine Lehrlinge und ich werden uns der Sache annehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27430] = { id = 27430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit im Namen der Familie Hyal", description = "Für mich waren die Grimmtotem zwar lediglich eine Belästigung, aber dennoch sollte Hauptmann Mumm von Euren Taten erfahren. Berichtet ihm, dass Ihr diejenigen, die für den Anschlag auf das Gasthaus \"Zur Süßen Ruh\" verantwortlich sind, gefunden und bestraft habt.\n\nEs ist zwar zu spät, um die Familie von Jim Hyal zu retten, aber vielleicht denken die Grimmtotem das nächste Mal zweimal nach, bevor sie jemanden aus Theramore angreifen.", sourceObjective = "Sprecht mit Hauptmann Garran Mumm bei der Wehrzitadelle in Theramore.", completion = "<Der Hauptmann hört sich Euren Bericht sorgfältig an.>\n\nWir haben James und seine Familie zwar gerächt, aber nicht einmal das kann wieder gut machen, was zerstört wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27431] = { id = 27431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Gleichgewicht gebracht", description = "<Harrison grinst.>\n\nDas ist es, {name}. Die Teile, die wir brauchen, sind in diesen Statuen versteckt!\n\nSie sehen aus, als wären sie sowieso ein wenig aus dem Gleichgewicht... Ein kleiner Stupser vielleicht...\n\nEure Untersuchungen schreiten ordentlich voran, muss ich sagen. Wenn Ihr Euch bewerben würdet, könnte aus Euch eines Tages <ein feiner Archäologe/eine feine Archäologin> werden.", sourceObjective = "Sprecht mit Harrison Jones in der Kammer der Sterne.", progress = "Was habt Ihr gefunden, {name}?", completion = "Wo wir gerade bei \"Häuser einreißen\" sind...", sourceObjectiveStatus = "unverified-source-field" }
quests[27432] = { id = 27432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zaeldarr der Ausgestoßene", description = "Könnt Ihr Euch vorstellen, dass wir uns nach dem ganzen Ärger in den Pestländern... jetzt auch noch um Diebe sorgen müssen? Nicht einfach gewöhnliche Diebe, Trolldiebe.\n\nUnd nicht einfach gewöhnliche Trolldiebe. Tote Trolldiebe!\n\nSie werden von diesem großen toten Troll namens Zaeldarr dem Ausgestoßenen angeführt, kommen nachts hierher und stehlen Leichen von unseren Friedhöfen. Dann schaffen sie sie zu ihrem üblen Versteck für tote Trolle - dem Tiefgewölbe im Südwesten.\n\nGeht dorthin und schaltet Zaeldarr aus, {name}. Ich habe seine Schandtaten satt!", sourceObjective = "Besorgt Zaeldarrs Kopf von Zaeldarr dem Ausgestoßenen.", progress = "Habt Ihr das Versteck gefunden, {name}? Habt Ihr Zaeldarr ausgeschaltet?", completion = "Sehr schön, Ihr habt ihn! Und ich hoffe, Ihr habt auch seiner Bande eine Lektion erteilt!", sourceObjectiveStatus = "unverified-source-field" }
quests[27433] = { id = 27433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schredderektomie", description = "Unsere Panzer müssen zurückgezogen werden, und das bedeutet, dass wir Arbeiten auf dem Schlachtfeld verrichten müssen.\n\nZerstört ein paar von den Diamantklingenschreddern, die diese kleinen Monster benutzen, um die Bäume an der Küste zu fällen, und bringt mir einen Haufen der Schredderteile, die noch verwendbar sind. Wir basteln damit etwas, um die Panzer wieder einsatzbereit zu machen.", sourceObjective = "Zerstört Diamantenklingenschredder, um 5 misshandelte Schredderteile zu erlangen.", progress = "Was habt Ihr für mich, {name}?", completion = "Oha, das ist gutes Zeug! Ein guter Ingenieur kann alles machen, wenn er nur ein paar gute Sachen hat.\n\nDieses Dingens hier könnte an eine kaputte Zylinderhülse gekoppelt werden ... Oh! Und wer freut sich nicht über ein solches Dingsbums? ... Und aus diesem Gedöhns hier kann man auf jeden Fall ein ... Ding machen!\n\n<Flintlocke steckt eines der schmierigen Maschinenteile in den Mund.>\n\nJupp, perfekt!", sourceObjectiveStatus = "unverified-source-field" }
quests[27434] = { id = 27434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad der Adepten", description = "Eure Lehrlingszeit neigt sich dem Ende zu, {name}. Ihr seid bereit, den Rang Adept innezuhalten und ein richtiger Blutritter im Dienste Silbermonds zu werden.\n\nUm Eure Leistungen zu ehren, hat der Kriegshäuptling bei seinem Schmied die Herstellung einer Waffe für Euch in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, eine Ladung Mondstahlbarren und Sehnen der Ghule und Spuke dort.", sourceObjective = "Reist nach Burg Schattenfang und findet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Kisten Mondstahlbarren, und 5 ewige Sehnen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ich weiß nicht, wie Ihr solche Mengen Mondstahl auftreiben konntet, {name}. Ich habe schon seit Jahren nicht mehr damit gearbeitet. Es wird sowohl eine Herausforderung als auch eine Freude sein, diese Waffe für Euch zu schmieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27435] = { id = 27435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stab eines Sehers", description = "In den Augen der Erdmutter seid Ihr bereit, den Rang des Sehers zu erlangen. Ihr habt Eure Grundausbildung mit Können und Hingabe absolviert.\n\nZu diesem Anlass hat der Kriegshäuptling bei seinem Verzauberkunstmeister die Herstellung eines Stabs für Euch in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27436] = { id = 27436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aufgabe des Schattenläufers", description = "Dies ist ein besonderer Anlass, {name}. Ihr habt viel gelernt und seid an der Macht gewachsen. Im Stamm der Dunkelspeere und in der Horde steht Euch eine großartige Zukunft bevor.\n\nIch habe den Verzauberkunstmeister des Kriegshäuptlings gebeten, einen Stab zu erstellen, um Eure Leistungen anzuerkennen.\n\nUm die dafür benötigten Materialien zu erlangen, müsst Ihr zur verfluchten Burg Schattenfang im Silberwald reisen. Findet das heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz, und die Essenzen der Geister, die die Burg heimsuchen, und bringt alles zu Godan.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27437] = { id = 27437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aufforderung des dunklen Klerikers", description = "Ihr habt gewissenhaft gelernt und uns gedient. Wenn Ihr Eure Talente übereinstimmend mit den Wünschen von Fürstin Sylvanas benutzt, wird Euch der Schatten segnen.\n\nUnsere Königin hat beim Verzauberkunstmeister von Orgrimmar die Herstellung eines mächtigen Stabes zur Anerkennung Eurer Dienste in Auftrag gegeben.\n\nDie Materialien, die dafür benötigt werden, sind nur in Burg Schattenfang inmitten von Silberwald zu bekommen. Findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27438] = { id = 27438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Flucht", description = "Das Ziel unserer Mission ist erfüllt. Nun können wir unsere Flucht planen. Obwohl wir Gilneas verloren haben, werden wir es mit der Hilfe von Godfrey und seinen Leutnants schnell wieder zurückerobern können.\n\nGeht nun, {name}. Fliegt mit Arthura zurück zur Frontlinie der Verlassenen im Süden von Silberwald. Die Bansheekönigin erwartet Eure Ankunft.", sourceObjective = "Flieht aus den Ruinen von Gilneas mit Arthura und der Leiche von Lord Godfrey.", completion = "Ich hatte keinerlei Zweifel, dass es Euch gelingen würde, {name}. Ich hoffe Ihr könnt verstehen, warum ich den eigentlichen Grund Eurer Mission geheim gehalten habe. Falls Crowley und Blutfang von unserem Plan Wind bekommen hätten, hätten sie Godfrey sicher vor uns ausfindig gemacht und seine Leiche verschwinden lassen. Bleibt weiterhin verfügbar, {name}.\n\nDie Zeit der Wiedergeburt unseres Landes ist gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27439] = { id = 27439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stab des Lichts", description = "Ihr seid durch Euer Talent schnell zu einem guten Diener des Lichts und Silbermonds geworden, {name}. Eure Loyalität gegenüber unserem Volk und der Horde sind beispielhaft.\n\nIn Anerkennung Eurer Hingabe hat der Kriegshäuptling bei seinem Verzauberkunstmeister die Herstellung eines Stabs für Euch in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27440] = { id = 27440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolls, Oger und Orcs, oh weh!", description = "Dem großen Schwarzdrachen Oberanführer Wyrmthalak unterstehen die Streitmächte der unteren Schwarzfelsspitze, die schon bald bereit für ihren Angriff auf die Dunkeleisenzwerge sein werden. Wir können nicht zulassen, dass die schwarzen Großdrachen die Kontrolle über den Berg erlangen!\n\nIhr müsst Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak töten. Ihre Tode werden den Kampfgeist der Armee beeinträchtigen und uns so wertvolle Zeit verschaffen.", sourceObjective = "Tötet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak.", completion = "Es tut mir leid, wenn ich das so sage, aber ich bin erstaunt, dass Ihr diese Aufgabe lebendig abschließen konntet. Diese Monster waren für die Tode Tausender verantwortlich, darunter viele Helden, von denen bis zum heutigen Tag noch gut gesprochen wird.\n\nIhr habt Euch meinen Respekt verdient und sollt eine Belohnung für Euren Mut erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27441] = { id = 27441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stab eines Sehers", description = "Man sagt, dass sogar der Kriegshäuptling von Euren Taten für die Horde erfahren hat. Bestimmt wird er jetzt erkennen, dass er uns falsch eingeschätzt hat.\n\nEr hat sich bereiterklärt, dem Verzauberkunstmeister von Orgrimmar zu gestatten, einen Stab für Euch zu fertigen.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und besorgt Euch das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27442] = { id = 27442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Krieg hat viele Fronten", description = "Jetzt sieht unsere Lage dem Feind in Vashj'ir gegenüber viel besser aus als vor Eurer Ankunft. Versteht mich nicht falsch, wir brauchen immer noch Eure Hilfe, aber vielleicht sind unsere anderen Fronten in noch größerer Bedrängnis.\n\nMan hat mir berichtet, dass unsere Verbündeten des Irdenen Rings in einer Angelegenheit um Hilfe gebeten haben, die keinen Aufschub duldet.\n\nScharfseher Krogar am Westlichen Erdschrein in Orgrimmar wird Euch weitere Anweisungen erteilen.", sourceObjective = "Sprecht mit Scharfseher Krogar am Westlichen Erdschrein in Orgrimmar.", completion = "Eure Hilfe kommt genau zur rechten Zeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27443] = { id = 27443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Krieg hat viele Fronten", description = "Jetzt sieht unsere Lage dem Feind in Vashj'ir gegenüber viel besser aus als vor Eurer Ankunft. Versteht mich nicht falsch, wir brauchen immer noch Eure Hilfe, aber vielleicht sind unsere anderen Fronten in noch größerer Bedrängnis.\n\nMan hat mir berichtet, dass unsere Verbündeten des Irdenen Rings in einer Angelegenheit um Hilfe gebeten haben, die keinen Aufschub duldet.\n\nErdsprecher Naraat am Östlichen Erdschrein in Sturmwind wird Euch weitere Anweisungen erteilen.", sourceObjective = "Sprecht mit Erdsprecher Naraat am Östlichen Erdschrein in Sturmwind.", completion = "Eure Hilfe kommt genau zur rechten Zeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27444] = { id = 27444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der falsche Kriegshäuptling", description = "Rend Schwarzfaust war der Sohn eines Kriegshäuptlings der Orcs. Sein Vater wurde von Orgrim Schicksalshammer umgebracht, der daraufhin zum neuen Kriegshäuptling anstelle des jungen Rends wurde. Rend hat sich nun zum Anführer der Schwarzfelsorcs emporgeschwungen, einer Möchtegern\"horde\", und wird dabei von Nefarian und seiner Drachenarmee unterstützt.\n\nRend, der Narr, behauptet auch, dass er das Geburtsrecht auf die Horde innehält, und droht, dieses Recht mit Gewalt geltend zu machen. Wir können nicht zulassen, dass dies unter dem Einfluss seines Meisters geschieht. Findet ihn in der oberen Schwarzfelsspitze und bringt diesen falschen Kriegshäuptling zu Fall, {race}.", sourceObjective = "Tötet Kriegshäuptling Rend Schwarzfaust.", progress = "Rend wird nicht ohne Kampf gestürzt werden können.", completion = "Habt Ihr Nefarian gesehen, als Ihr mit Rend gekämpft habt?\n\n<Acride seufzt.>\n\nIch wünschte, ich hätte Euch begleitet. Ich hätte ihm gegenübertreten können, als er nicht damit gerechnet hat, außerhalb seines Horts. Nun, das ist egal. Nefarian wird unter meiner Klaue sterben.\n\nIhr habt gute Arbeit geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27445] = { id = 27445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Drakkisath, Nefarians rechte Hand", description = "Nefarian weitet seinen Herrschaftsbereich weiter oben im Pechschwingenhort aus. Obwohl man dort von der oberen Schwarzfelsspitze aus hinkommt, könnten wir dort mit weitaus mehr Streitmächten einfallen, wenn wir die Kugel der Teleportation in der Nähe benutzen. Wir können uns erst teleportieren, wenn wir durch eine andere Kugel gekennzeichnet sind.\n\nDie zweite Kugel wird von Drakkisath, dem General von Nefarians Armee, persönlich bewacht. Schaltet ihn aus und sichert die zweite Kugel, damit wir sie nutzen können. Ihr werdet ihn im Spitzenthron in der oberen Schwarzfelsspitze finden.", sourceObjective = "Tötet General Drakkisath.", completion = "Hervorragend! Es ist nur eine Frage der Zeit, bevor der Sohn von Todesschwinge meine Klauen zu spüren bekommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27446] = { id = 27446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaris ruft", description = "Hey, {name}! Kelsey Stahlfunken aus Tanaris hat eine Nachricht für Euch gebracht. Sie meint, die Gnome dort in Gadgetzan hätten von Euren Leistungen gehört.\n\nDer Kataklysmus hat sie auch dort unten nicht verschont. Uns hat er zwar härter getroffen, aber sicherlich können sie Eure Hilfe gebrauchen.", sourceObjective = "Sprecht mit Kelsey Stahlfunken in Gadgetzan in Tanaris.", completion = "Seid gegrüßt, mein Freund. Willkommen in Tanaris!", sourceObjectiveStatus = "unverified-source-field" }
quests[27447] = { id = 27447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaris ruft", description = "Hey, {name}! Megs Schredderschreck aus Tanaris hat eine Nachricht für Euch hinterlassen. Sie sagt, die Goblins dort in Gadgetzan haben von Euren Leistungen gehört.\n\nDer Kataklysmus hat sie auch dort unten nicht verschont. Uns hat er zwar härter getroffen, aber sicherlich können sie Eure Hilfe gebrauchen.\n\nAußerdem sieht diese Megs verdammt gut aus!", sourceObjective = "Sprecht mit Megs Schredderschreck in Gadgetzan in Tanaris.", completion = "Aber hallo, {class}. Willkommen in Tanaris!", sourceObjectiveStatus = "unverified-source-field" }
quests[27448] = { id = 27448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reise geht weiter", description = "Ich glaube, die Pferde sind startklar. Argus Leuchtfeuer, der Herr, der mit dem Argentumkreuzzug zusammenarbeitet, hat sich vorhin mit mir unterhalten. Wie ich höre, wird er uns wohl begleiten - großartig! Ich werde Platz für ihn machen.\n\nIch weiß, dass Ihr beschäftigt seid, also nur keine Hektik. Sobald Ihr soweit seid, springt einfach auf den Karawanenwagen auf und wir machen uns auf den Weg zum nächsten Turm.", sourceObjective = "Steigt auf Fionas Karawanenwagen, wenn Ihr bereit seid, um zum nächsten Turm aufzubrechen.", progress = "Sobald wir am Lichtschildturm eintreffen, können sich die Jungs auf den Weg zur Kapelle des Hoffnungsvollen Lichts machen. Diese kurze Strecke können sie laufen.", completion = "Es war sehr angenehm, mit Euch zu reisen, {name}. Hoffentlich können wir unsere Reise gemeinsam fortsetzen, sobald Gidwin und Tarenar dem Argentumkreuzzug beigetreten sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27449] = { id = 27449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre und Stärke", description = "Mein Name lautet Vex'tul und ich habe Euch im Kampf beobachtet, {race}. Ihr seid stark.\n\nIhr habt meinen Meister Zaeldarr getötet, aber das stört mich nicht. Stärke ist mir wichtiger als die Loyalität, die ich ihm gegenüber empfand. Stärke ist mir wichtiger als alles andere.\n\nBeweist mir Eure Stärke ein letztes Mal, {race}. Wenn Ihr sie beweisen könnt, werde ich Euch MEINE Stärke leihen und Ihr werdet sie für all die Zwecke einsetzen können, die Euch vorschweben.", sourceObjective = "Besteht Vex'tuls Stärketest.", completion = "Ja, Ihr seid in der Tat stark ... ich unterwerfe mich Euch.\n\nIch werde Euch und Eure Freundin, den Worgen, begleiten. Meine Stärke ist Eure.", sourceObjectiveStatus = "unverified-source-field" }
quests[27450] = { id = 27450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fredericks Vorliebe für Fisch", description = "Ich liebe das Meer. Ich, Frederick Calston, war es, der die Meeresbewohner in den See im Südwesten gebracht hat. Ich hatte gehofft, den Kreuzzug so mit frischer Nahrung direkt aus den Pestländern versorgen zu können.\n\nAllerdings haben sich einige als Raubfische herausgestellt und jetzt versetzen sie alle anderen Tiere in Angst und Schrecken. Wenn wir nicht aufpassen, werden sie alle töten!\n\nSchwimmt zum Boden des Sees und rettet ein paar der Schnecken, Krabben und Kugelfische, bevor es zu spät ist.", sourceObjective = "Erhaltet 8 Pestkugelfische, 8 Infektkriecher und 8 Infektkrabbler aus der Infektnarbe.", progress = "Habt... habt Ihr die Fische besorgt?", completion = "Hmm ... sie haben den Ausflug an Land nicht so gut überstanden, wie ich gehofft hatte.\n\nNun gut. Dann gibt es für Frederick heute Abend Meeresfrüchtesalat!", sourceObjectiveStatus = "unverified-source-field" }
quests[27451] = { id = 27451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Töten zu einem bestimmten Zweck", description = "Seid gegrüßt, Fremdling! Ihr seid im Herzen der Pestländer angelangt. Ich hoffe, Ihr habt Eure Untote-Töten-Ausrüstung dabei.\n\nDieser Tage verbreitet sich die Seuche immer langsamer und daher hat der Kult der Verdammten die Herstellung hochgeschraubt, damit das Land braun und tot bleibt, so, wie es ihnen am liebsten ist. Ich habe einen Plan, sie aufzuhalten. Nehmt meinen Mörser und den Stößel; zerstoßt damit die lebendige Fäulnis der untoten Kreaturen in Corins Kreuzung südöstlich von hier. Wir werden für diese Kultisten ein kleines Geschenk vorbereiten.", sourceObjective = "Reist zu Corins Kreuzung im Süden und tötet die Geißelsoldaten, die dort hausen. Sammelt 7 Stück lebendige Fäulnis. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis.", progress = "Wie steht es an Corins Kreuzung?", completion = "Hallo! Ich bin's. Ich hoffe, Ihr habt nichts gegen ein wenig selbstgebraute Zauberkunst, damit ich während dieser Aufgabe mit Euch in Verbindung bleiben kann. So können wir beide Zeit sparen.\n\nWir werden diese lebendige Fäulnis in eine Mixtur einarbeiten, die die komplette Produktion der kommenden Seuche ruinieren wird. Das wird sie eine Lektion lehren!", sourceObjectiveStatus = "unverified-source-field" }
quests[27452] = { id = 27452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Gewänder", description = "Einige meiner Mitstreiter haben berichtet, dass das Land heilen möchte. Allerdings lassen das viele hochrangige Untote - und auch der Kult der Verdammten - nicht zu. Das bedeutet, dass wir sie aufhalten müssen! Ich habe einen Plan, aber zuerst brauche ich eine Kultistenverkleidung.\n\nBegebt Euch nach Südosten, zu Corins Kreuzung und nehmt einem der menschlichen Kultisten die Gewänder ab. Ihr werdet sie durch den Ort streifen sehen. Ich werde mich mit Euch in Verbindung setzen, wenn Ihr das Gewand erhalten habt.", sourceObjective = "Erhaltet die Kopfbedeckung eines Todeskultisten und die Roben eines Todeskultisten von Kultisten in Corins Kreuzung.", progress = "Soweit alles in Ordnung, {name}?", completion = "Ihr habt beide Teile! Gut. Sie werden mir dabei helfen, mich in ihr Todeslager zu schleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27453] = { id = 27453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katalysmus", description = "Geronnene Fäulnis ist allein schon sehr wirksam, aber wir brauchen etwas, um die versteckten Kräfte hervorzurufen ... einen Katalysator. Ein guter Katalysator findet sich südlich von hier, im Mereldarsee.\n\nWenn Ihr in Eure Taschen seht, werdet Ihr bemerken, dass ich ein paar Fläschchen hineingeschmuggelt habe, als Ihr nicht aufgepasst habt. Benutzt diese Fläschchen bei den Wasserelementaren im See. Das lebende, verderbte Wasser, aus dem ihre Körper bestehen, wird einen perfekten Katalysator abgeben!", sourceObjective = "Verwendet Betinas Fläschchen gegen lebende Elementare im Mereldarsee, um 8 flüssige Seuchenwirkstoffe zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27454] = { id = 27454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur ein Tropfen im Eimer", description = "Gebt nun eine kleine Menge Fäulnis zum Wasser und gut verrühren. So, das war es schon. Diese Lösung wird sehr aggressiv sein und wir brauchen nur ganz wenig davon.\n\nAm südöstlichen Ufer des Sees befindet sich ein Seuchenkessel, in dessen Nähe sich mehrere Kultisten aufhalten. Tragt die Kultistenverkleidung, geht zum Kessel und fügt nur EINEN TROPFEN dieser Lösung hinzu. Wenn Ihr mehr in den Kessel schüttet, ist Euer Leben in großer Gefahr!", sourceObjective = "Benutzt Eure Todeskultistenverkleidung, um das Basislager der Todeskultisten zu betreten und fügt Betinas Mischung dem Mereldar Seuchenkessel zu.", completion = "Es sollte Wochen dauern, bis sie ihr Vorhaben wieder in die Tat umsetzen können. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27455] = { id = 27455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jungs bleiben Jungs", description = "Direkt nach unserer Ankunft hier am Lichtschildturm sind die beiden Paladinschwachköpfe zur Kapelle des Hoffnungsvollen Lichts davongerannt. Sie ist noch recht weit entfernt, aber wenn wir Argus auf seiner Turmrundreise folgen wollen, dann ist das hier wohl noch am nächsten.\n\nSchaut einmal nach ihnen und stellt sicher, dass es ihnen gut geht. Ich weiß, dass sie auf sich selbst aufpassen können, aber dennoch... Mir wäre wohler, wenn ich wüsste, dass Ihr über sie wacht, während ich hier mit dem Wagen festsitze.", sourceObjective = "Findet Gidwin Goldzopf vor der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", completion = "Ich kann es kaum glauben. Wir stehen SO kurz davor, ordentliche Mitglieder des Argentumkreuzzugs zu werden.\n\nWir wären bereits aufgenommen, wenn Tarenar nicht so herumtrödeln würde. Wenn er nicht bald aufhört, mit den Einwohnern zu schwatzen, werde ich alleine dort hineingehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27456] = { id = 27456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht auf leeren Maden", description = "Wir haben Schwierigkeiten, unsere Nahrungsvorräte hier im tiefen Osten aufrechtzuerhalten.\n\nIn dieser Gegend gibt es nur eine Tierart, die nicht von der Seuche beeinträchtigt wird und das sind Aaswürmer. Sie schmecken zwar nach nichts, aber das Fleisch dieser Würmer kann über Monate hinweg aufbewahrt werden. Wir benötigen einige hundert Pfund, damit wir wieder ausreichend versorgt sind.\n\nMan findet Aaswürmer überall in den Pestländern, aber besonders häufig kommen sie südlich der Kapelle vor. Und denkt daran: Große Würmer liefern mehr Fleisch.", sourceObjective = "Sucht in der Umgebung nach Aaslarven und Aasverschlingern. Tötet sie und bringt 15 Scheiben Aaswurmfleisch an Euch.", progress = "Ihr werdet Euch an den Geschmack gewöhnen, {race}. Ging mir auch so.", completion = "Möge die Erdenmutter über Euch wachen. Seid gesegnet, Jüngling.", sourceObjectiveStatus = "unverified-source-field" }
quests[27457] = { id = 27457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Gelegenheitsallianz", description = "Durch Euren Beitrag zu den Nahrungslagern ist meine Aufgabe erledigt.\n\nIch werde mich als Nächstes nach Norden in den Pestwald begeben. Wie ich höre, geht Ihr in die gleiche Richtung?\n\nWürde es Euch etwas ausmachen, wenn ich mich Euch anschließe? \n\nIch bin unterwegs nach Nordwesten zum Ostwallturm. Wenn Ihr Interesse an einem Zusammenschluss habt, könnt Ihr mich dort treffen.", sourceObjective = "Meldet Euch bei Fiona am Ostwallturm in den Östlichen Pestländern.", completion = "Ihr habt einen Schamanen mitgebracht! Und dann auch noch vom Irdenen Ring!\n\nIch habe keine Ahnung, wie er in dem Wagen Platz finden soll, aber uns wird etwas einfallen. Willkommen an Bord, Rimblat Erdspalter!", sourceObjectiveStatus = "unverified-source-field" }
quests[27458] = { id = 27458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smokey und der Verband", description = "He, Ihr da! Interesse, leichtes Geld zu verdienen?\n\nIch muss an eine Bandage kommen. Also, um ehrlich zu sein, hab ich einen Freund, der an eine Bandage kommen muss. Also, um ehrlich zu sein... sagen wir einfach, es ist zu kompliziert, aber wenn Ihr diese Bandage holt, bekommt Ihr Geld. Genau wie ich. Und mein Freund. Möglicherweise auch andere Leute.\n\nDie Mühle im Norden gehörte früher einmal Stephan Braumann, aber jetzt ist er tot. Ein Zombie. Der Kerl ganz oben möchte die Wickel von Braumanns Körper.\n\nWas ist los - mögt Ihr kein Geld?", sourceObjective = "Besorgt Braumanns Wickel von Stephan Braumann in Braumanns Mühle.", progress = "Ihr habt gegen Untote gekämpft. Habt Ihr Braumann gefunden?", completion = "Kaum zu glauben! Jemand, der losgeht und Dinge tatsächlich erledigt! Hier ist Euer Anteil, Chef. Wir seh'n uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[27459] = { id = 27459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bruderschaft des Lichts", description = "Die Bruderschaft des Lichts ist für ihre unbesonnenen und gedankenlosen Entscheidungen bekannt. Sie haben eine Brücke zwischen dem Scharlachroten Kreuzzug und der Argentumdämmerung geschlagen. Sie waren unter den ersten, die sich in Nordend in den Kampf warfen, während wir anderen noch zögerten.\n\nDeshalb sind sie auch für ihre Ergebnisse bekannt und das respektiere ich. Jetzt kämpfen sie an zwei Fronten: Eine Schlacht in Stratholme und die andere - viel drängendere - Schlacht im Süden bei Tyrs Hand.\n\nIch schlage vor, Ihr sprecht mit Angela Dosantos in Tyrs Hand. Vielleicht hat sie Verwendung für Euch.", sourceObjective = "Meldet Euch bei Erzmagierin Angela Dosantos in Tyrs Hand in den Östlichen Pestländern.", completion = "Ein {class}! Genau das, was wir brauchen. Eure Ankunft hätte nicht zu einem besseren Zeitpunkt erfolgen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27460] = { id = 27460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanfte Landung", description = "Man hat uns nur einhundert Männer überlassen, um diese Mission zu erfüllen, und einer fehlt uns bereits. Unser Späher wurde in die Feste des Feindes entsandt, um einige Wachen auszuschalten, die in der Gegend patrouillieren. Außerdem sollte er ein Leuchtfeuer entfachen, damit wir einen koordinierten Angriff durchführen können. Unsere neunundneunzig verbliebenen Männer sind bereit und warten auf das Leuchtfeuer. <Ein talentierter/Eine talentierte:c> {class} wie Ihr muss sich nach Tyrs Hand schleichen, so viele Wachen wie möglich ausschalten und das Leuchtfeuer entfachen.\n\nFühlt Ihr Euch dem gewachsen?", sourceObjective = "Tötet 10 beliebige Anhänger des Scharlachroten Kreuzzugs in Tyrs Hand.", completion = "Das Leuchtfeuer ist aufgetürmt und die Streichhölzer liegen unbenutzt neben der Zündschnur.\n\nDer gefallene Argentumzenturio war näher dran, das Leuchtfeuer zu entzünden, als Ihr vermutet hattet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27461] = { id = 27461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Abtei einnehmen", description = "Der Scharlachrote Kreuzzug unterhält eine gut befestigte Abtei im unteren westlichen Teil von Tyrs Hand. Zunächst muss die Abtei gesichert werden, bevor man sich weiter in die Festung vorwagen kann.", sourceObjective = "Meldet Euch bei Kommandant Eligor Morgenbringer außerhalb der Abtei in Tyrs Hand in den Östlichen Pestländern.", completion = "Seid gegrüßt, {name}. Kann ich darauf vertrauen, dass Ihr mir helfen werdet, die Abtei diesen Monstrositäten zu entreißen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27462] = { id = 27462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kaserne einnehmen", description = "Eines der Schlüsselgebäude in Tyrs Hand ist die Kaserne, die sich ganz in der Nähe dieses Leuchtfeuers befindet. Die Bruderschaft des Lichts und ihre Zenturionen werden alle verfügbare Hilfe benötigen, um sie zu erobern.", sourceObjective = "Meldet Euch bei Kreuzzugskommandant Korfax vor der Kaserne in Tyrs Hand in den Östlichen Pestländern.", completion = "Ich werde ab jetzt die Leitung hier übernehmen, {class}.\n\nAlso gut, Ihr wollt eine Aufgabe? Ich denke, ich kann es mir leisten, Euch auf die ein oder andere Mission zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27463] = { id = 27463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Kindheitstraum", description = "Ich wollte mich schon immer dem Kreuzzug anschließen. Deshalb bin ich Paladin geworden. Jahrelange Übung und Verbesserung meiner Fertigkeiten. Endlich bin ich bereit.\n\nTarenar glaubt ebenfalls, dass er bereit ist, aber da bin ich mir nicht so sicher. Er ist ein Angeber und hat seine Lektionen nie ernstgenommen. Dennoch - wir haben versprochen, dass wir das hier zusammen machen und hier stehen wir nun.\n\nSollen wir uns in die Kapelle begeben?", sourceObjective = "Sprecht mit Lord Maxwell Tyrosus in der Kapelle des Hoffnungsvollen Lichts.", completion = "Willkommen in der Kapelle des Hoffnungsvollen Lichts.\n\nIhr wünscht, Euch dem Kreuzzug anzuschließen? Na schön. Wir haben ausreichend Aufgaben für neue Rekruten.\n\nAber zunächst ein Test...", sourceObjectiveStatus = "unverified-source-field" }
quests[27464] = { id = 27464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argentumruf: Die Prüfung der Gruft", description = "Hinter unserer Kapelle findet Ihr eine kleine Gruft. Darin sind die Leichen unserer gefallenen Helden bestattet, die ihr Leben im Krieg gegen die Geißel verloren haben.\n\nIhre Seelen ruhen friedlich. Dennoch kehren sie hin und wieder zurück, um neue Mitglieder des Ordens zu prüfen.\n\nIhr drei dürft die Prüfung zusammen absolvieren. Betretet die Gruft und lest dann diese Schriftrolle. Lord Raymond George - mein Vorgänger - wird den Vorsitz bei Eurer Prüfung übernehmen.", sourceObjective = "Betretet die Gruft hinter der Kapelle des Hoffnungsvollen Lichts, lest aus der Argentumschriftrolle und schließt die Prüfung ab.", progress = "Eure Prüfung ist noch nicht abgeschlossen.", completion = "Denkt daran, dass Eure Vorfahren stets über Euch wachen. Als Bruder des Argentumkreuzzugs werdet Ihr Teil einer Familie, die auf eine lange Reihe solcher Vorfahren zurückblickt. Ihre Wachsamkeit und Ihr Schutz werden Eure Stärke sein, wenn Ihr Euch gegen die Geißel stemmt.\n\nMeine Glückwünsche, Tarenar, Gidwin und {name}. Willkommen beim Argentumkreuzzug.", sourceObjectiveStatus = "unverified-source-field" }
quests[27465] = { id = 27465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argentumruf: Das Giftige Tal", description = "Braumanns Mühle im Norden wimmelt nur so von Untoten. Das Giftige Tal, noch weiter nördlich, ist noch schlimmer befallen. Trotz der Nähe zu unserer Kapelle sind wir nicht in der Lage gewesen, sie zu entfernen.\n\nWachsamkeit ist der Schlüssel. Reist in das Giftige Tal und tötet so viele Untote, wie Ihr finden könnt, sowie die Kultisten, die sich darunter befinden.\n\nWährend Ihr dort seid, weicht Garginox dem Fleischriesen aus, der durch das Tal wandelt. Ich vermute, dass Ihr nicht stark genug seid, um ihn zu besiegen.", sourceObjective = "Tötet 16 Angehörige der Geißel und 8 Kultisten in Braumanns Mühle und dem Giftigen Tal. Kehrt zur Kapelle des Hoffnungsvollen Lichts zurück, wenn Tarenar oder Gidwin getötet werden.", completion = "Ihr seid früher als erwartet zurückgekehrt. Ausgezeichnet.\n\nWir werden unseren Weg in den Norden fortsetzen. Als nächstes werdet Ihr eine ähnliche Aufgabe erfüllen, diesmal in Nordtal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27466] = { id = 27466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argentumruf: Nordtal", description = "Tyrosus hat uns unsere nächste Aufgabe gestellt: weitere Untote in Nordtal vernichten. Gidwin freut sich darauf, weiterzuziehen, aber ich glaube, wir sollten etwas vorsichtiger sein.\n\nLasst uns Fiona aufsuchen. Sie sollte jetzt den nächsten Turm erreicht haben... Ich glaube, er heißt Ostwallturm. Er ist in der Nähe, nordwestlich der Kapelle. Dort können wir uns ausruhen und unseren Angriff auf Nordtal planen.", sourceObjective = "Sprecht mit Fiona am Ostwallturm in den Östlichen Pestländern.", completion = "Hallo, {name}! Es freut mich, dass Ihr Euch uns wieder angeschlossen habt.\n\nTarenar und Gidwin sind bereits vor Euch eingetroffen. Tarenar ist gleich hier und Gidwin... nun... er ist gerade schlecht gelaunt. Ich glaube, er ist im Turm.", sourceObjectiveStatus = "unverified-source-field" }
quests[27467] = { id = 27467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergrabene Klingen", description = "Das Giftige Tal ist ein Morast, im wörtlichen und übertragenen Sinne. Es gibt dort oben genug Angehörige der Geißel, um uns beiden bis an unser Lebensende Schwierigkeiten zu bereiten.\n\nSie können die schwächeren wieder auferstehen lassen, wenn sie sterben, {name}. Sie werden nie aufhören, nachzurücken, wenn wir nicht etwas unternehmen.\n\nNehmt diese Klingen und durchstoßt damit die Leichen aller Reitersoldaten der Geißel, derer Ihr habhaft werden könnt. Die Klinge ist einfach, aber ihre Verzauberung wird verhindern, dass die toten Knochen wiederbelebt werden können. Für immer.", sourceObjective = "Stoßt die lichtberührten Klingen in die Leichen von 10 getöteten Reitersoldaten der Geißel.", completion = "Unsere Pflicht für heute ist getan.\n\nEs ist nur eine Frage der Zeit, bis wir die Geißel vernichtend schlagen. Heute haben wir Fortschritte gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27468] = { id = 27468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung des Belagerungspanzers", description = "Wir müssen unsere Belagerungspanzer einen nach dem anderen aus dem Schlamm ziehen. Nehmt die Ersatzteile, die Ihr gesammelt habt und gebt sie einem der Belagerungspanzerkommandanten, die auf den kaputten Fahrzeugen stehen.\n\nUnd dann verteidigt den Panzer, während die Ingenieure versuchen, ihn unzukaputten.\n\nGeht un' macht mich stolz, {class}!", sourceObjective = "Sprecht mit einem Belagerungspanzerkommandanten auf einem kaputten Belagerungspanzer von Hochstade. Verteidigt den Panzer, während die Ingenieure Reparaturen vornehmen.", progress = "Steine un' Stümpfe un' Berge un' Matsch ... Bäh.\n\nIch hasse die Natur.", completion = "Jupp, noch ein weiterer Panzer, der zur Reparatur kann.\n\nDurch all diese Bäume un' Baumstümpfe un' Matsch un' Steine könnte man nicht mal einen Golfball abschlagen und erst recht keinen Panzer fahren.\n\nWir müssen unsere Vorgehensweise ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27469] = { id = 27469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde auf der anderen Seite", description = "Ich bringe Neuigkeiten von der Schwarzfelsspitze. Wir haben einen neuen Besucher. Sein Name ist Acride.\n\nEr sucht Leute, die stark, intelligent und geschickt sind. Ihr solltet zur Schwarzfelsspitze gehen und mit ihm sprechen.", sourceObjective = "Findet Acride.", completion = "Hallo, was führt Euch hierher?\n\nEntschuldigung, wer hat Euch geschickt? Ich fürchte, von einem {race} dieses Namens habe ich noch nie gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[27470] = { id = 27470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein möglicher Verbündeter", description = "Es ist kein Geheimnis, dass wir die Orcs im Schwarzfels nicht mögen. Wir beobachten sie daher ganz genau. Hier in den Bergen passiert nichts, von dem ich nichts weiß, {class}.\n\nVor Kurzem kam ein ganz andersartiger Orc nach Schwarzfels. Er hat sich in der Schwarzfelsspitze niedergelassen, und ich weiß, dass er irgendwie vorhat, Nefarian und seine ganze Orcarmee zu stürzen. Normalerweise würde ich keinem dieser Orcs trauen, aber zur Zeit verfolgen wir ein gemeinsames Ziel. Findet ihn. Er heißt Acride.", sourceObjective = "Findet Acride.", completion = "Hallo, was führt Euch hierher?\n\nAlso Aufseher Schlickfaust hat Euch geschickt? Hört gut zu, wir haben viel zu besprechen und nur wenig Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27471] = { id = 27471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzfelsanomalie", description = "In der Schwarzfelsspitze gibt es einen Orc, der ganz anders ist als alle anderen Orcs. Seine Sprache zeugt von Intelligenz und Wissen, die seinem Aussehen Hohn spricht. Im Gegensatz zu den anderen Orcs bekämpft er auch unsere Soldaten nicht.\n\nIhr müsst zur Schwarzfelsspitze reisen, nordwestlich von hier, und diesen Orc finden, der uns nur als Acride bekannt ist. Vielleicht ist er der Schlüssel, um die Armee der Orcs aufzuhalten. Vielleicht können wir Nefarian aufhalten, bevor es zu spät ist ...", sourceObjective = "Findet Acride.", completion = "Hallo, was führt Euch hierher?\n\nAlso Ihr seid auf Bitten von Fräulein Wolkenglanz hier? Das ist ja höchst interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[27472] = { id = 27472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erwacht, Godfrey", description = "Eure Loyalität den Verlassenen gegenüber ist standhaft, {name}. Was Ihr bisher für uns getan habt - Eure Dienste für die Horde - werden nicht unbemerkt bleiben. Nun, da Lord Godfrey und seine Männer sich bald wieder erholt haben werden, werden wir einen großen Vorteil gegenüber der Gilnearischen Befreiungsfront und dem Rest der Hunde der Allianz haben.\n\nIch möchte Euch zum Anlass von Lord Godfreys Wiedergeburt als Einem von uns an meiner Seite haben. Wir werden ihn und seine Männer gemeinsam in unseren Kreis aufnehmen.", sourceObjective = "Bleibt bei Fürstin Sylvanas Windläufer, während sie Lord Godfrey und seine Männer aufnimmt.", completion = "Der heutige Tag stellt den Beginn einer neuen Ära für die Verlassenen und das Ende der Allianz in Lordaeron dar!", sourceObjectiveStatus = "unverified-source-field" }
quests[27474] = { id = 27474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Barriere durchbrechen", description = "Während Godfrey und ich unseren Angriff auf Gilneas vorbereiten, möchte ich, dass Ihr den Angriff auf Mühlenbern, direkt östlich von hier, leitet.\n\nDie früheren Magier von Dalaran in Mühlenbern haben eine magische Barriere errichtet, die sie unsichtbar macht. Sie befinden sich in einer Art Dimensionstasche und erwarten Befehle der Allianz, um ihren Angriff zu beginnen. Wir müssen diesen Angriff durch einen Präventivschlag verhindern. Begebt Euch nach Mühlenbern und sucht nach Informationen, die uns Zugang zu diesen Magiern verschaffen.", sourceObjective = "Findet den Kodex von Mühlenbern.", progress = "Habt Ihr schon etwas gefunden?", completion = "Die Magier sind schlau. Der Kodex ist mit einem magischen Schutzzauber versiegelt.\n\nSchade nur, dass sie nicht schlau genug waren, zu erkennen, dass die früheren Erzmagier von Dalaran jetzt Verlassene sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27475] = { id = 27475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unnachgiebige Diener", description = "Die Magier von Mühlenbern haben abscheuliche Magie benutzt, um uns fernzuhalten. Elementardiener, deren Immunitäten wir nicht überwinden können, beschützen ihr Territorium.\n\nGeht nach Osten nach Mühlenbern und tötet die unerschütterlichen Elementardiener, die die Stadt bewachen. Dann bergt ihre Kerne. Bringt die Kerne hierher zu mir, damit ich einen Weg finden kann, wie wir sie alle zerstören können.", sourceObjective = "Bergt 6 Dienerkerne.", progress = "Habt Ihr die Dienerkerne gefunden?", completion = "Gut gemacht, {name}. Das Lob, das die Bansheekönigin Euch zuteilwerden lässt, ist anscheinend nicht unbegründet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27476] = { id = 27476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalar Morgenweber", description = "Nehmt den Kodex und reist nach Norden zum Grabmal. Wenn Ihr dort eintrefft, sucht nach Dalar Morgenweber. Dalar ist ein früherer Erzmagier der Kirin Tor. Er wird sicherlich in der Lage sein, die Schutzzauber, die diesen Kodex umgeben, zu entfernen und ihm seine Geheimnisse zu entlocken.\n\nBeeilt Euch, {name}.", sourceObjective = "Liefert den Kodex von Mühlenbern bei Dalar Morgenweber am Grabmal im Silberwald ab.", progress = "Ja? Was wollt Ihr?", completion = "Die Dunkle Fürstin benötigt meine Expertenmeinung? Aber selbstverständlich! Gebt schon her mein Junge.", sourceObjectiveStatus = "unverified-source-field" }
quests[27477] = { id = 27477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Korpulente", description = "Nördlich von hier und westlich von Nordtal findet Ihr das fettleibige Madenungeheuer Blutschlinger.\n\nIch habe ganze Regimenter gegen dieses Monster eingebüßt. Seine Ausmaße sind gewaltig! Je mehr er frisst, desto größer wird sein Umfang...\n\nEs würde mir keine schlaflosen Nächte bereiten, sollte die Bestie Euch verschlingen, dennoch sähe ich es lieber, wenn Ihr als Sieger hervorgeht. Man weiß, dass Blutschlinger schon andere verschlungen hat, die versucht haben, ihn zu jagen.", sourceObjective = "Findet Blutschlinger im nördlichen Ödland der Östlichen Pestländer und vernichtet ihn.", completion = "Macht weiter so und es könnte passieren, dass ich Euch hier in Ostwall bei mir behalte, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27478] = { id = 27478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relios, Bewahrer der Relikte", description = "Die Dunkle Fürstin hat Recht, dass ich in der Lage bin, den Kodex zu entschlüsseln. Leider benötige ich dafür einen Siegelring von einem Erzmagier aus Dalaran. Mein eigener Ring wurde mir weggenommen, als ich vor vielen Jahren starb, aber es gibt vielleicht eine Möglichkeit.\n\nObwohl Dalaran fortgeschwebt ist, sind doch die Außenbezirke der Stadt erhalten geblieben. Weit im Osten liegen die Ruinen von Dalaran. Dort werdet Ihr einen Erzmagier mit Namen Relios finden. Nehmt seinen Siegelring an Euch und bringt ihn zu mir zurück.\n\nIhr dürft das Portal hinter mir benutzen, um zu dem Krater zu gelangen.", sourceObjective = "Findet einen Siegelring eines Erzmagiers aus Dalaran.", progress = "Habt Ihr einen Siegelring eines Erzmagiers aus Dalaran gefunden?", completion = "Perfekt. Ich hoffe, es war nicht zu schwierig, an ihn heranzukommen, {name}. Relios war einer meiner Schüler, als ich noch ein Sterblicher war. Deshalb dürfte er ein fähiger und ernstzunehmender Gegner sein. Ich hätte Euch wohl schon vorher warnen sollen.\n\nNun, lasst uns den Ring anschauen.\n\n\n\nNa also...", sourceObjectiveStatus = "unverified-source-field" }
quests[27479] = { id = 27479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rechtschaffene Empörung", description = "Die Moosschinder von Zul'Mashar spucken dem Licht ins Gesicht! Ihr Kannibalismus, ihr Atheismus, ihr Atavismus stellen die Mächte des Bösen über die des Guten. Ich verschreibe, Ihr rückt ihnen zu Leibe, damit ihr Getreibe ein Ende finde und jeder noch so Blinde empfinde, welche Strafe auf Torheit stünde!\n\nIhr werdet nach Norden reisen und mit all Eurer rechtschaffenen Empörung über sie kommen, {name}. Der Zorn, den sie im Angesicht des Lichts entflammt haben, wird Euch zueigen werden.", sourceObjective = "Erbeutet 30 Moosschinderaugen von Moosschindertrollen in Zul'Mashar.", progress = "<Diakon Andaal ist ins Gebet vertieft.>", completion = "Oh, Hallelujah, gelobt sei das Licht, Bruder!", sourceObjectiveStatus = "unverified-source-field" }
quests[27480] = { id = 27480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ley-Energien", description = "Das arkane Überbleibsel pulsiert mit seltsamer Energie. Vielleicht solltet Ihr nach weiteren Überbleibseln suchen. Dalar wäre an solchen Funden sicherlich interessiert.", sourceObjective = "Findet 8 arkane Überbleibsel.", progress = "Was habt Ihr denn da, {name}?", completion = "Cleveres Mädel. Ich kann diese arkanen Überbleibsel auf jeden Fall bei meinen Studien verwenden. Um genau zu sein wurde Dalaran auf einer riesigen Leylinie erbaut. Daher ist es kein Wunder, dass es diese Gegenstände im Krater gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27481] = { id = 27481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Ziggurat", description = "Die Zeit ist gekommen, Euch um einen Gefallen zu bitten, {name}.\n\nWeit nördlich des Ostwallturms, verborgen in den Hügeln, liegt die Moosschinderhauptstadt Zul'Mashar. Hier wurde ich geboren und hier bin ich gestorben.\n\nDer Verräter Thresh'jin sitzt auf Zul'Mashars Ziggurat. Eigentlich hätte mir der Sitz zugestanden, aber er erschlich ihn sich von mir durch Verrat und Lügen. Er ist nicht stark. Er ist schwach.\n\nIch werde in Zul'Mashar zu Euch stoßen. Dann werden wir ihn töten. Eure Stärke und die meine. Vereint.", sourceObjective = "Erbeutet den Leichnam von Kriegsherr Thresh'jin.", sourceObjectiveStatus = "unverified-source-field" }
quests[27482] = { id = 27482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinein in die Flammen", description = "Dies ist unsere letzte Begegnung, {name}. Ich verlasse die Karawane.\n\nBehaltet Thresh'jins Leiche, wenn Ihr weiter an meiner Seite kämpfen wollt. Ich kann noch ein wenig länger ausharren. Werft den Körper in das Feuer oben auf Zul'Mashars Ziggurat, wenn Ihr bereit zum Abschied seid.\n\nIch danke Euch für Eure Freundschaft, {name}. Ihr wart stark.", sourceObjective = "Werft den Leichnam des Kriegsherrn Thresh'jin in das Feuer oben auf Zul'Mashars Ziggurat, wenn Ihr bereit seid, Euch von Vex'tul zu trennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27483] = { id = 27483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Praktische Rache", description = "Eigentlich bin ich kein rachsüchtiger Mann. Um genau zu sein bin ich eher Pragmatiker. Wisst Ihr, Sachlichkeit ist im Grunde das Gegenteil zu Rache. Die meisten Rachepläne sind höchst unpraktisch.\n\nABER... in diesem Fall... Da Ihr Euch ohnehin schon zu den Ruinen von Dalaran begebt, könnt Ihr auch jeden Menschen, der mit Dalaran in Verbindung gebracht werden kann, töten. Die Gründe dafür, dass ich sie tot sehen will, reichen von Hass über Zorn bis zu Verrat, aber ich versichere Euch, der Groll ist durchweg berechtigt. Erledigt das für mich und ich werde Euch reich belohnen.", sourceObjective = "Tötet 12 beliebige Menschen aus Dalaran.", completion = "Ich hatte mit Sicherheit angenommen, dass der Tod eines Dutzends meiner meist gehassten Feinde mir eine große Last von den Schultern nimmt. Leider spüre ich gar nichts. Vielleicht bin ich ein Psychopath.", sourceObjectiveStatus = "unverified-source-field" }
quests[27484] = { id = 27484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es darf nur einer eintreten", description = "<Dalar blättert durch den Kodex.>\n\nHAHAH!\n\nOh... Das ist schlimm.\n\n<Dalar klappt den Kodex zu und schaut zu Euch hoch.>\n\nNur EINER darf mit Hilfe dieses Rings die Dimensionstasche in Mühlenbern betreten. Diese Person muss sich dann einen Weg durch eine Armee von Magiern freikämpfen und den Erzmagier töten, der die Verschiebung von der anderen Seite her erschafft. Erst dann wird die Dimension in sich zusammenbrechen und alle Magier auswerfen.\n\nDas Portal, durch das man hineingelangen kann, liegt versteckt hinten in einer Höhle in Berens List.\n\nMehr weiß ich nicht. Bringt den Ring zu Sylvanas zurück.", sourceObjective = "Bringt den Siegelring eines Erzmagiers aus Dalaran zu Fürstin Sylvanas Windläufer an der Frontlinie der Verlassenen im Silberwald zurück.", progress = "Was habt Ihr erfahren?", completion = "Nur einer darf eintreten? Ich kenne genau die richtige Person für diese Aufgabe.\n\n<Sylvanas nickt Euch zu.>\n\nIch werde unsere Streitkräfte vorbereiten und bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27485] = { id = 27485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein herzliches Willkommen", description = "Ich bin froh, dass Ihr zurück seid! Um die Welt zu retten oder dergleichen, da bin ich sicher.\n\nIch wurde ausgeschickt, um Beziehungen mit den roten Drachen in der Gegend aufzubauen, aber ich finde sie weniger zugänglich als diejenigen in Wyrmruh. Allerdings sagte man mir, dass Ihr jemand seid, der Probleme löst.\n\nEin Problemlöser sozusagen.\n\nHättet Ihr vielleicht Lust, ein wenig Vertrauen mit Lirastrasza im Zinnoberrefugium im Norden aufzubauen? Alles, das sie mir gegenüber ein wenig milder stimmt wäre wunderbar.", sourceObjective = "Trefft Euch mit Lirastrasza im Zinnoberrefugium.", completion = "Ich bin froh, dass Lira Euch nicht verschreckt hat. Ich will damit nicht sagen, dass ihre Bedenken nicht gerechtfertigt sind, aber wir haben einen gemeinsamen Feind. Vielleicht ist sie etwas übervorsichtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[27486] = { id = 27486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein herzliches Willkommen", description = "Gut. Ihr seid zurück. Rettet wohl wieder die Welt, was?\n\nIch wurde ausgeschickt, um Beziehungen zu den roten Drachen in der Gegend aufzunehmen, aber die hiesige Variante ist bei Weitem nicht so entgegenkommend, wie die Drachen im Wyrmruhtempel. Mir ist allerdings zu Ohren gekommen, dass Ihr jemand seid, der Probleme löst.\n\nEin Problemlöser sozusagen.\n\nIhr müsst das Vertrauen von Lirastrasza im Zinnoberrefugium südwestlich von hier gewinnen. Unsere Zusammenarbeit mit dem Drachenmalklan hat die Angelegenheit zugespitzt, aber ich bin zuversichtlich, dass Ihr die Wogen glätten könnt.", sourceObjective = "Trefft Euch mit Lirastrasza im Zinnoberrefugium.", completion = "Ich bin froh, dass Lira Euch nicht verschreckt hat. Ich will damit nicht sagen, dass ihre Bedenken nicht gerechtfertigt sind, aber wir haben einen gemeinsamen Feind. Vielleicht ist sie etwas übervorsichtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[27487] = { id = 27487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ix'lar der Unterfürst", description = "Ich weiß, dass wir eigentlich nach Nordtal aufbrechen sollten, aber das hat doch noch Zeit, oder? Dieser niedliche kleine Goblin hat mir übrigens erzählt, dass die Geißel in der Nähe weilt.\n\nAnscheinend gibt es einen nerubischen Unterfürsten namens Ix'lar, der seit der Vernichtung des Lichkönigs versucht, sich einen Namen zu machen. Er und seine Untoten haben nördlich von uns ein Lager errichtet.\n\nNatürlich will Tyrosus, dass wir Banshees in Nordtal töten. Das werden wir auch. Aber lasst uns zuerst diesen Neruber töten, solange wir in der Nähe sind!", sourceObjective = "Tötet Ix'lar den Unterfürsten und 10 seiner Diener.", completion = "Ich konnte ihn nicht aufhalten. Während Ihr und Tarenar unterwegs wart, ist Giddy ganz allein nach Norden gelaufen!\n\nTarenar, Ihr hättet es besser wissen sollen! Gidwin wird manchmal so ungeduldig und Ihr stachelt ihn noch an. Wenn Giddy in Schwierigkeiten gerät, gebe ich Euch die Schuld daran.", sourceObjectiveStatus = "unverified-source-field" }
quests[27488] = { id = 27488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeduld", description = "Dieser verdammte Zwerg. Immer kriege ich wegen ihm Ärger mit Fiona. Seht sie Euch doch an! Sie REDET nicht einmal mehr mit mir!\n\nIch werde hier bleiben und versuchen, meine Freundschaft mit unserer Worgenfreundin zu kitten. Würde es Euch etwas ausmachen, allein nach Gidwin zu suchen? Es geht ihm bestimmt gut. Er kann auf sich allein aufpassen. Er war auf dem Weg nach Norden. Weit kann er nicht gekommen sein.", sourceObjective = "Sucht nach Gidwin Goldzopf in Nordtal.", progress = "In Nordtal gibt es einige Geister und Banshees. Der alte Giddy kommt mit denen schon klar.", completion = "Ihr seid ihm nicht begegnet? Wo ist er denn nur?\n\nSein... sein Gebetsbuch? Warum hat er das zurückgelassen?\n\nOh...\n\nBeim Licht, was habe ich getan?", sourceObjectiveStatus = "unverified-source-field" }
quests[27489] = { id = 27489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich allein bin schuld", description = "Das ist meine Schuld. Ich... Ich habe seine Warnungen und Beschwerden ignoriert. Ich konnte nicht anders - Ich sah die Geißel so nahe hinter dem Turm, da... Ich MUSSTE sie töten.\n\nArgus sagt, Gidwin sei nach Nordwesten gebracht worden. Das ist unsere einzige Spur, also werden wir in diese Richtung aufbrechen.\n\nIch pfeife auf Nordtal und den Argentumkreuzzug! Wir werden Gidwin von diesen Geißelmistkerlen zurückholen.", sourceObjective = "Steigt in Fionas Karawanenwagen und fahrt zum Nordpassturm.", completion = "Die Zeit rennt uns davon, {name}. Mit jeder Minute, die wir verschwenden, steigt die Wahrscheinlichkeit, dass die Geißel Gidwin umbringt. Wenn er nicht schon tot ist.\n\nDoch das glaube ich nicht. Giddy ist zwar nicht der Hellste, aber wenn es sein muss, schwingt er das Licht wie ein Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[27490] = { id = 27490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den SI:7 absetzen", description = "Mathias Shaw und der SI:7 sind hier, um uns bei unserer Mission oben in der Schattenzitadelle zu unterstützen. Ihr müsst sie für mich dorthin geleiten.\n\nDie Wildhämmer sind so freundlich, uns dorthin zu fliegen. Die Agenten müssen jedoch zuerst etwas unten bei den Toren erledigen.\n\nSprecht mit Angus Stillberg und schnappt Euch eine Truppe, um sie sicher abzusetzen. Ihr werdet sie hereinfliegen. Die Stelle ist mit einem großen blauen X markiert.", sourceObjective = "Holt bei Angus Stillberg eine Truppe der Wildhammervandalen ab und begleitet sie zum Landepunkt am Schattentor.", completion = "Das muss schlimm gewesen sein.\n\nAuch wenn ich mit ihren Methoden nicht einverstanden bin, kann niemand die Effizienz von Mathias Shaw und seinem SI:7 anzweifeln. Und schließlich seid Ihr auch noch hier. Unser Sieg ist schon in trockenen Tüchern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27491] = { id = 27491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kor'kron absetzen", description = "Garona und ein Kommando der Kor'kron sind hier, um uns bei unserer Mission oben in der Schattenzitadelle zu unterstützen. Ihr müsst sie für mich dorthin geleiten.\n\nDer ansässige Trollstamm ist so freundlich, uns auf ihren Windreiten dorthin zu fliegen. Die Assassinen müssen jedoch zuerst etwas unten bei den Toren erledigen.\n\nSprecht mit dem Anführer der Trolle, Jon-Jon Glibberhals, und schnappt Euch ein Kommando der Kor'kron, um sie sicher abzusetzen. Ihr werdet sie hereinfliegen. Die Stelle ist mit einem großen roten X markiert.", sourceObjective = "Holt bei Jon-Jon Glibberhals eine Truppe der Schmetterschlagwindreiter ab und begleitet sie zum Landepunkt am Schattentor.", completion = "Das muss spannend gewesen sein.\n\nTrotz der Verluste, die die Kor'kron vielleicht unterwegs erlitten haben, wird niemand es wagen, Zweifel an ihrer Effizienz noch an der Garonas zu äußern. Und da Ihr auch mit von der Partie seid, ist es nur eine Frage der Zeit, bis der Sieg unser ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27492] = { id = 27492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oger und Ettins", description = "Wie bei jeder Offensive müsst Ihr erst ihre Reihen schwächen. Wir haben uns ganz schön angestrengt, um dort hinein zu gelangen. Aber jemand wie Ihr… Nun, sagen wir einfach, dass ich keinen Zweifel habe, dass Ihr die Tore der Zitadelle im Südwesten durchbrechen und den Ogern und Ettins des Blutaugenklans ein oder zwei Lektionen erteilen könnt.", sourceObjective = "Tötet 10 Oger oder Ettins am Schattentor.", progress = "Was ist los? Habt Ihr Jungs der Allianz nicht die Nerven, um den Auftrag zu erledigen?\n\n<Kurdran zwinkert Euch zu.>\n\nSoll ich da 'rüber fliegen und sie für Euch erledigen?", completion = "Genau das will ich sehen, Kumpel! Heute scheint ein guter Tag zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27493] = { id = 27493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oger und Ettins", description = "Ich möchte, dass Ihr Euch hinter diese Felsen schwingt und jeden Oger oder Ettin des Blutaugenklans tötet, der Euch über den Weg läuft. Könnt Ihr das für mich tun, {name}?", sourceObjective = "Tötet 10 Oger oder Ettins des Blutaugenklans am Schattentor.", completion = "Und ich dachte, es könnte heute nicht mehr besser kommen.\n\nNun, ich irre mich gerne, zumindest manchmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27494] = { id = 27494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berge versetzen", description = "Wenn die Tore fallen sollen, müssen wir Schädelberster den Berg dort weglocken!\n\nBevor sie gegangen sind, habe ich dafür gesorgt, dass Eure Agenten des SI:7 ein paar Sprengsätze mitnahmen, die in einer Kiste des Schattenhammers versteckt waren. Sie sollten sie bereits auf den Stufen zum oberen Bereich der Zitadelle platziert haben.\n\nIch möchte, dass Ihr die Sprengsätze zündet und uns dann Bescheid gebt, wenn das Monster aus dem Weg geräumt ist.\n\nDann werden wir angreifen und den Ogern den Rest geben!", sourceObjective = "Zündet die versteckten Sprengsätze, um Schädelberster den Berg vom Schattentor wegzulocken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27495] = { id = 27495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berge versetzen", description = "Wenn die Tore fallen sollen, müssen wir Schädelberster den Berg dort weglocken!\n\nBevor sie gegangen sind, habe ich dafür gesorgt, dass Eure Assassinen der Kor'kron ein paar Sprengsätze mitnahmen, die in einer Kiste des Schattenhammers versteckt waren. Sie sollten sie bereits auf den Stufen zum oberen Bereich der Zitadelle platziert haben.\n\nIch möchte, dass Ihr die Sprengsätze zündet und uns dann Bescheid gebt, wenn das Monster aus dem Weg geräumt ist.\n\nDann werden wir angreifen und den Ogern den Rest geben!", sourceObjective = "Zündet die versteckten Sprengsätze, um Schädelberster den Berg vom Schattentor wegzulocken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27496] = { id = 27496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt die Artillerie!", description = "Ich bevorzuge einen ehrenhaften Kampf Mann gegen Mann. Diese Monster verdienen es, durch die Waffen in unseren Händen den Tod zu finden. In diesem speziellen Fall müssen wir jedoch auf mächtigere Methoden zurückgreifen.\n\nNehmt diese Leuchtpistole und markiert die vier Gebäude innerhalb des Schattentors im Südwesten. Unsere Kanonen werden den Rest erledigen.", sourceObjective = "Benutzt die Artillerieleuchtpistole, um das nördliche, das nordöstliche, das südwestliche und das südliche Gebäude am Schattentor als Ziel zu markieren.", completion = "Dank Euch können unsere Kanoniere ihr Ziel nicht mehr verfehlen. Und nun berichtet mir von der Lage am Schattentor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27497] = { id = 27497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt die Artillerie!", description = "Wie schade, dass wir unsere Feinde nicht mehr mit der Seuche strafen dürfen. Gerade in dieser Lage wäre das sehr effektiv. Nun ja, zumindest haben wir Kriegsmaschinen, um ihre ach so geliebten Tore einzureißen.\n\nNehmt diese Leuchtpistole und markiert die vier Gebäude innerhalb des Schattentors im Nordwesten. Unsere Kanonen werden den Rest erledigen.", sourceObjective = "Benutzt die Artillerieleuchtpistole, um das nördliche, das nordöstliche, das südwestliche und das südliche Gebäude beim Schattentor als Ziel zu markieren.", completion = "Ich muss sagen, der Anblick der einschlagenden Bomben in ihre Gebäude hat mich gut unterhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27498] = { id = 27498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehlt den Angriff", description = "Jetzt, da Ihr Schädelbrecher den Berg vom Schattentor weggelockt habt, müsst Ihr den Truppen am Gipfel des Siegers signalisieren, dass sie angreifen können!", sourceObjective = "Benutzt das Angriffssignal auf einem der Türme beim Schattentor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27499] = { id = 27499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehlt den Angriff", description = "Jetzt, da Ihr Schädelbrecher den Berg vom Schattentor weggelockt habt, müsst Ihr den Truppen am Schmetterschlagposten signalisieren, dass sie angreifen können!", sourceObjective = "Benutzt das Angriffssignal auf einem der Türme beim Schattentor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27500] = { id = 27500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vier Köpfe sind besser als keiner", description = "Während der Angriff auf die Tore der Zitadelle in vollem Gange ist, gibt es noch eine Sache, um die Ihr Euch kümmern müsst: Za'brox und Beeble'phod, die Jünger Cho'galls.\n\nLaut den Geheiminformationen halten sie sich im Schlupfwinkel der Jünger auf, einer kleinen Ogerhöhle am südwestlichen Ende des Schattentors.\n\nIhr seid Euch ziemlich sicher, dass Cassius und Kurdran einen Beweis für ihren Tod sehen wollen.", sourceObjective = "Sammelt die vier Köpfe von Za'brox und Beeble'phod.", progress = "Tropft da etwa Blut aus Eurer Tasche?", completion = "<Der Paladin verzieht das Gesicht.>\n\nDa habt Ihr aber eine grausame Trophäensammlung. Ich hätte Euch auch geglaubt, wenn Ihr mir einfach gesagt hättet, dass sie tot sind. Dennoch danke, dass Ihr so vorausschauend wart, sie zu töten.\n\nDas Schattentor ist bald in unserer Hand. Es wird Zeit, uns der Schattenzitadelle selbst zuzuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27501] = { id = 27501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vier Köpfe sind besser als keiner", description = "Während der Angriff auf die Tore der Zitadelle in vollem Gange ist, gibt es noch eine Sache, um die Ihr Euch kümmern müsst: Za'brox und Beeble'phod, die Jünger Cho'galls.\n\nLaut den Geheiminformationen halten sie sich im Schlupfwinkel der Jünger auf, einer kleinen Ogerhöhle am südwestlichen Ende des Schattentors.\n\nIhr seid Euch ziemlich sicher, dass Lady Cozwyn und Zaela einen Beweis für ihren Tod sehen wollen.", sourceObjective = "Sammelt die vier Köpfe von Za'brox und Beeble'phod.", progress = "Tropft da etwa Blut aus Eurer Tasche? Ich hoffe, es ist nicht Euer eigenes.", completion = "<Die hohe Dame grinst boshaft.>\n\nDa habt Ihr aber eine grausame Trophäensammlung. Ich hätte Euch auch geglaubt, wenn Ihr mir einfach gesagt hättet, dass sie tot sind. Aber ich weiß Eure zusätzliche Mühe durchaus zu schätzen. Dennoch danke, dass Ihr so vorausschauend wart, sie zu töten.\n\nDas Schattentor ist bald in unserer Hand. Es wird Zeit, uns der Schattenzitadelle selbst zuzuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27502] = { id = 27502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinauf zur Zitadelle", description = "Jetzt, da der Angriff eingeleitet wurde, ist es Zeit, uns um die Schattenzitadelle zu kümmern. Wenn Ihr nichts dagegen habt, möchte ich Euch bitten, die Truppen des SI:7 zu Meister Mathias Shaw zu führen.\n\nEr hält sich irgendwo auf dem Gipfel versteckt. Der Truppenkommandant des SI:7 kann Euch den genauen Ort nennen.\n\nVielen Dank, {name}. Wir freuen uns schon darauf, Euch beim Angriff auf die Zitadelle zur Seite zu stehen!", sourceObjective = "Sprecht mit dem Truppenkommandanten des SI:7 und begleitet dann die Truppe des SI:7.", sourceObjectiveStatus = "unverified-source-field" }
quests[27503] = { id = 27503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinauf zur Zitadelle", description = "Jetzt, da der Angriff eingeleitet wurde, ist es Zeit, uns um die Schattenzitadelle zu kümmern. Wenn Ihr nichts dagegen habt, möchte ich Euch bitten, die Truppen der Kor'kron zu Garona zu führen.\n\nSie hält sich irgendwo auf dem Gipfel versteckt. Der Truppenkommandant der Kor'kron kann Euch den genauen Ort nennen.\n\nVielen Dank, {name}. Wir freuen uns schon darauf, Euch beim Angriff auf die Zitadelle zur Seite zu stehen!", sourceObjective = "Sprecht mit dem Truppenkommandanten der Kor'kron und begleitet dann die Truppe der Kor'kron.", sourceObjectiveStatus = "unverified-source-field" }
quests[27504] = { id = 27504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sogar Drachen bluten", description = "Ich werde nicht so unhöflich sein, Eure Hilfe abzulehnen, wenn Ihr sie mir schon anbietet.\n\nWir befinden uns im stetigen Kampf mit den Zwielichtdrachen im Süden. Zwar sind unsere Angriffe nicht ganz fruchtlos, aber die Drachen, die aus Grim Batol hinausströmen, haben eine Art Verderbnis auf uns herab beschworen, die es nun zu läutern gilt.\n\nVelastrasza und Unheilsflamme kümmern sich um unsere verletzten Brüder. Geht und schaut, ob Ihr ihnen helfen könnt.", sourceObjective = "Sprecht mit Velastrasza im Zinnoberrefugium.", completion = "Calen ist sehr vertrauensselig in letzter Zeit. Nicht viele Fremde dürfen das Refugium betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27505] = { id = 27505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilung auf Drachenart", description = "Wenn unsere Drachen aus der Schlacht zurückkehren, sind sie ganz in vom Zwielicht verderbte Flammen gehüllt und werden von den Zwielichtdrachen verfolgt.\n\nMeine Heiler können sich zwar um die Wunden unserer Drachen kümmern, aber sie müssen dabei geschützt werden. Haltet die Drachen von meinen Heilern fern. Wenn Ihr könnt, helft auch Ihr unseren Drachen mit Eurer Heilkraft.\n\nVielen Dank für Eure Unterstützung in dieser Angelegenheit. Unsere Schlachten um Grim Batol nehmen kein Ende. Wir müssen unsere mächtigsten Drachen so schnell wie möglich wieder in den Kampf schicken.", sourceObjective = "Beschützt 5 zinnoberrote Heiler, während sie verwundete Drachen heilen.", progress = "Schützt die Heiler, während sie unsere verwundeten Drachen heilen!", completion = "Wir werden Grim Batol vom Schattenhammer und seinen Verbündeten zurückerobern. Es wird vielleicht ein wenig dauern, aber bei dieser Aufgabe dürfen wir nicht scheitern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27506] = { id = 27506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leben aus dem Tod", description = "{race}, ich habe eine Aufgabe für Euch.\n\nNehmt diese Rubinsamen und pflanzt sie in die Leichname der Drachkin, denen Ihr begegnet. Zwielicht oder Zinnober, Welpling oder Drache, es ist ganz egal. Wir müssen dafür sorgen, dass ihre Körper wieder der Erde zurückgegeben werden, damit das Leben erneut erblühen kann.\n\nIm Tod sollte es immer neues Leben geben. Lasst Euch das einen Trost in Zeiten des Krieges und des Leids sein.", sourceObjective = "Pflanzt Rubinsamen in die Leichname von 6 Drachkin im Zinnoberrefugium.", completion = "Durch diese Tat verweigern wir Todesschwinge die Zerstörung, die er so leidenschaftlich anrichten möchte. Durch diese Tat geht das Leben weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[27507] = { id = 27507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbreitung des Zwielichts", description = "Im Refugium wimmelt es von Zwielichteindringlingen. Sie strömen von einem unbekannten Ort im Westen auf die Lichtung.\n\nAn diesem heiligen Ort kann es für sie kein Mitleid geben. Welchen Funken der Gewalt Ihr auch in Eurem rechtschaffenen Herzen finden mögt, lasst sie darin in Flammen aufgehen.", sourceObjective = "Tötet 12 Zwielichteindringlinge im Zinnoberrefugium.", completion = "Ihr habt ein Händchen fürs Töten, wie ich sehe. In Zeiten wie diesen hat auch dies eine Berechtigung.", sourceObjectiveStatus = "unverified-source-field" }
quests[27508] = { id = 27508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weit weg vom Nest", description = "Schaut… Ich weiß, dass Ihr keinen Grund habt, mich zu mögen, genauso wie auch ich Euch nicht besonders mag, aber ich brauche jede Hilfe, die ich bekommen kann.\n\nDiese Zwielichteindringlinge stehlen unsere Eier. Ohne Zweifel haben sie vor, sie zurück nach Grim Batol zu bringen, um damit zu experimentieren und sie zu pervertieren. Das werde ich einfach nicht zulassen.\n\nWenn Ihr uns wirklich helfen wollt, dann haltet sie auf! Holt die Eier zurück und bringt sie mir.", sourceObjective = "Holt 6 Zinnobereier zurück.", progress = "Die Zwielichtdrachen entstehen aus ihren abscheulichen Experimenten. Der Schattenhammer ist zu weit gegangen. Todesschwinge ist zu weit gegangen.", completion = "Ich weiß nicht, ob Ihr das für mich oder die Jungen im Inneren getan habt, aber das spielt auch keine Rolle. Es zeigt deutlich, dass Ihr ein Freund unseres Schwarms sein wollt. Ich weiß das zu schätzen.\n\nIch kann Euren Verbündeten die Angriffe auf meine Brut nicht verzeihen, aber bis jetzt scheint es zumindest so, als hättet Ihr Euch für die richtige Seite entschieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27509] = { id = 27509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigungslücke", description = "Jeder Millimeter der Luft um das Refugium herum wird permanent von Liras Drachen bewacht. Sie müssen sich von unten einen Weg in den Schrein gebahnt haben.\n\nNehmt diese Blitzwuchspartikel. Sie sollten sich gut dafür eignen, sämtliche Löcher, Tunnel oder Portale zu schließen, über die sie unsere Verteidigung durchbrochen haben könnten.\n\nFindet die Lücke in unserer Verteidigung, Schließt sie.", sourceObjective = "Findet die Quelle des Schattenhammers im Zinnoberrefugium und vernichtet sie.", completion = "Gut gemacht. Vielen Dank, {race}.\n\nIch werde dafür sorgen, dass wir so einen dummen Fehler nicht mehr begehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27510] = { id = 27510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Wolf im Bärenpelz", description = "Diese Worgen verkaufen uns für dumm! Man sollte meinen, dass nur ein Schwachkopf einen ihrer Druiden in Bärengestalt für einen echten Bären halten würde. Leider gibt es hier an der Frontlinie der Verlassenen viele Schwachköpfe. Wir haben bereits mehrere Bataillone bei organisierten Bärenangriffen der Worgen verloren. Ja, es ist in der Tat noch schwachsinniger, als es klingt.\n\nDirekt östlich von hier Richtung Hügelland findet Ihr Druiden der Worgen in den Wäldern. Sie sind als Bären getarnt. Tötet sie und sichert unsere südliche Versorgungslinie.", sourceObjective = "Tötet 10 unauffällige Bären.", completion = "Ich hoffe nur, dass wir demnächst nicht auch noch von unverdächtigen Vögeln, Katzen und Bäumen dezimiert werden… oder Seelöwen! Könnt Ihr Euch das vorstellen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27511] = { id = 27511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spannende Entdeckungen", description = "Welch ein Fund! Und irgendwie ist alles von Plünderern verschont geblieben...\n\nHört zu, {name}. Ich muss diesen Ort aufzeichnen, bevor wir etwas verändern. Warum seht Ihr Euch nicht ein wenig um, während ich das mache - Ihr wisst schon, ein wenig auf Entdeckungsreise gehen. Ihr habt es Euch verdient.\n\nHaltet Eure Augen offen und achtet auf Ungewöhnliches.\n\nOh! Und bitte... macht nichts kaputt, ja?", sourceObjective = "Erforscht die Kammer der Sterne.", completion = "Eure Erforschung der Kammer der Sterne hat mehr Fragen aufgeworfen als Antworten gebracht...", sourceObjectiveStatus = "unverified-source-field" }
quests[27512] = { id = 27512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dimensionsübergreifender Krieg: Kapitel I", description = "<Sylvanas gibt Euch den Siegelring.>\n\nNehmt den Ring und macht Euch auf nach Berens List im Südosten von hier in einer Höhle in den Hügeln. Sobald Ihr dort seid, durchsucht die Höhle nach dem Portal zu der Dimensionstasche, die die Magier von Mühlenbern verbirgt.\n\nIch werde mit Euch über Eure Gedanken kommunizieren, {name}. Wenn Ihr das Portal erreicht habt, werde ich Euch Eure Befehle geben.", sourceObjective = "Findet das Dimensionsportal von Mühlenbern.", progress = "<Das Portal summt.>", completion = "<Die Stimme der Bansheekönigin erfüllt Eure Gedanken.>\n\nJa, das ist es. Jetzt streicht mit dem Ring über die Runen auf dem Portal und Ihr solltet für die dimensionsübergreifende Reise vorbereitet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27513] = { id = 27513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dimensionsübergreifender Krieg: Kapitel II", description = "<Die Worte der Bansheekönigin ertönen im Inneren Eures Kopfes.>\n\nIhr seid jetzt bereit, das Portal zu benutzen. Seid gewarnt, {name}, sobald Ihr das Portal durchschreitet, erscheint Ihr in einer anderen Dimension von Mühlenbern. Dort werden Hunderte oder sogar Tausende Magier darauf warten, Euch zu töten.\n\nIhr müsst durchhalten und alle töten, die sich Euch in den Weg stellen.", sourceObjective = "Tötet 20 Magier von Mühlenbern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27514] = { id = 27514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vogel am Boden! Vogel am Boden!", description = "Während Ihr an der Küste gekämpft habt, habe ich gesehen, wie fast genau westlich von hier ein Greif aus den Wolken gestürzt ist.\n\nEs war keiner von unseren.\n\nWahrscheinlich gehörte er zu einem der Wildhämmer. Ich weiß, dass Kuran als eine der obersten Prioritäten nach der Einnahme des Strandes Kontakt zu den verschollenen Wildhammerklans aufnehmen wollte.\n\nIch kann keinen meiner Männer entbehren, um dort nachzusehen, aber Euch schon. Findet den abgestürzten Wildhammer!", sourceObjective = "Findet den abgestürzten Greifenreiter der Wildhämmer Thordun Hammerschlag am Zwielichtufer im Schattenhochland.", completion = "Ach, so ein Mist. Ihr seid nur ein {class} der Allianz. Ich hatte auf Rettung gehofft.", sourceObjectiveStatus = "unverified-source-field" }
quests[27515] = { id = 27515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wurzel alles Guten", description = "Schaut doch, Kumpel. Sie liegt in den letzten Zügen! Wenn mein Vogel stirbt, bin ich so gut wie wertlos.\n\nAlso macht Euch nützlich. Hier auf der Halbinsel wächst dorniger Stinkwurz im Boden. Der Geruch zieht Euch die Socken aus, aber in Wasser eingeweicht wird daraus ein echtes Allheilmittel.\n\nSammelt ein paar Wurzeln, während ich meinen Vogel verteidige. Und beeilt Euch! Ihr Flachzangen von der Allianz habt ja nicht gerade den Ruf, rechtzeitig einzuschreiten, oder?", sourceObjective = "Sammelt 8 Stück dorniger Stinkwurz am Zwielichtufer.", progress = "Habt Ihr meine Wurzeln, {class}? Na?", completion = "Oh, gutes Zeug! Ich hoffe, Ihr habt nichts davon gegessen. Es verursacht schlimme Krämpfe, aber bei Vögeln wirkt es Wunder!", sourceObjectiveStatus = "unverified-source-field" }
quests[27516] = { id = 27516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Schwingen nach Hochstade", description = "He, schaut nur! Sie ist schon viel munterer.\n\nGut, <Herr/Fräulein> Etepetete von der Allianz. Ist das Euer Lager da an der Küste? \"Hochstade\" sagt Ihr? Meint Ihr, mein Vogel und ich könnten dort eine Weile Unterschlupf finden, bis es ihr besser geht?\n\nSpringt auf! Wir fliegen gemeinsam nach Hochstade!", sourceObjective = "Sprecht mit Thordun Hammerschlag und fliegt gemeinsam nach Hochstade!", completion = "Gut gemacht, {name}! Durch Eure Rettung des abgestürzten Greifenreiters konnten wir einen ersten Kontakt mit den alten Wildhammerklans herstellen. Wir werden herausfinden, wer noch übrig ist und wie viele es sind.\n\nWir bekommen Auftrieb!", sourceObjectiveStatus = "unverified-source-field" }
quests[27517] = { id = 27517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seid vorbereitet", description = "Jeder Abenteurer, der etwas auf sich hält, weiß, dass man niemals einen Fuß in eine Höhle, ein Verlies, eine Krypta oder eine Grabstätte setzt ohne ausreichend Seil dabeizuhaben... nicht wahr?\n\nDavon kann man nie genug haben!\n\nMan geht sogar so weit, jedes Stück, das man finden kann, von den Skeletten hier aufzusammeln.", sourceObjective = "Sammelt 6 Stücke Seil.", progress = "Was habt Ihr gefunden, {name}??", completion = "Ahh, Seil! Danke, mein Junge!\n\nIrgendwie habe ich das Gefühl, ich werde es brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27518] = { id = 27518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dimensionsübergreifender Krieg: Kapitel III", description = "<Sylvanas spricht direkt durch Euch.>\n\nIhr müsst das Wesen, das diese Dimensionstasche aufrechterhält, finden. Wahrscheinlich ist es dieser Narr, Ataeric... Sucht das Gelände nach ihm ab. Solltet Ihr ihn finden, müsst Ihr alles Notwendige tun, um ihn davon abzuhalten, seine Magie zu kanalisieren. Er wird zweifellos durch einen mächtigen, arkanen Schild geschützt und wird Handlanger aus arkaner Energie auf Euch loslassen. Besiegt die Handlanger in seiner Nähe, um ihre Energien freizusetzen. Kein Magier kann mit so viel Kraft umgehen!", sourceObjective = "Überladet Erzmagier Ataeric mit arkaner Macht, um den transdimensionalen Schild auszuschalten.", completion = "Hätte ich nicht mit eigenen Augen Eure Taten gesehen, ich hätte es nicht geglaubt, {name}. Jetzt, da die Magier von Mühlenbern sich auf unserer Seite befinden, gibt es nur noch eins für uns zu tun, bevor wir Gilneas zurückerobern und diese Hunde der Allianz nach Sturmwind zurückrennen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27519] = { id = 27519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter dem erstickenden Sand", description = "Nein... Das kann nicht sein.\n\nOrsis ist fast vollkommen unter dem Wüstensand begraben.\n\nDer Feind wird dafür bezahlen.\n\nDoch zunächst müssen wir meinem Volk helfen. Schnell, {name}. Wir haben nicht viel Zeit, bevor auch der letzte meiner Brüder lebendig begraben wird!", sourceObjective = "Rettet 8 Überlebende von Orsis.", completion = "Ich danke Euch, {name}. Orsis wurde dafür bestraft, sich nicht den Truppen von Todesschwinge angeschlossen zu haben.\n\nPrinz Nadun hat meinem Volk Zuflucht in seiner Stadt angeboten. Ich muss dort hingehen und mich um die Überlebenden kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27520] = { id = 27520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Al'Akirs Diener", description = "Al'Akir hat seine Diener ausgesandt, um Todesschwinges Befehle zu befolgen.\n\nDie Botschaft ist deutlich. Wir schließen uns ihnen an oder sie vernichten uns.\n\nIch weiß nicht viel über Euch, {race}. Aber eins weiß ich. Wenn Ihr Euch als Feind Al'Akirs erweist, wird Eure Hilfe nicht unbemerkt bleiben.\n\nWas sagt Ihr dazu, {class}?", sourceObjective = "Tötet 6 Abkömmlinge von Al'Akir.", completion = "Ihr erweist Euch weiterhin als wertvoller Verbündeter, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27521] = { id = 27521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elender Hort des Abschaums und der Boshaftigkeit", description = "{race}... bitte, ich brauche Eure Hilfe.\n\nEtwas ist mit meinen Leuten geschehen. Unser Kommandant, Waldläuferlord Falkenspeer, hat einen Gegenstand aus magischer Energie gefunden. Meine Freunde, meine Familie... sie alle sind seiner verführerischen Macht erlegen. \n\nSie sind verdorben, {race}. Sie alle.\n\nMeine Ellaria würde so nicht leben wollen, auch meine Brüder nicht. Bitte erlöst sie von ihrem Leid. Die Jagdhütte von Quel'Lithien ist nicht weit weg. Nur den Hügel hinauf im Nordwesten.", sourceObjective = "Tötet 9 Getriebene nahe der Jagdhütte von Quel'Lithien in den Östlichen Pestländern.", completion = "Bemitleidet mich nicht. Es waren zwar meine Freunde, die Ihr an der Jagdhütte von Quel'Lithien gesehen habt, aber sie waren schon so gut wie tot.", sourceObjectiveStatus = "unverified-source-field" }
quests[27522] = { id = 27522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prügelstrafe", description = "Uns Paladinen bringt man bei, unseren Feinden gerecht und ruhig entgegenzutreten, aber dies ist ein Notfall. Außerdem habe ich noch nie auf meine Lehrer gehört.\n\nIch werde versuchen, im Pestwald mehr über Giddy herauszufinden. Kümmert Ihr Euch um die Geißel nordöstlich von hier, auf der anderen Seite dieses Turms. Die Untoten fürchten den Tod nicht, aber schlagt sie lang genug, dann verplappern sie sich vielleicht und geben uns Hinweise auf Gidwins Aufenthaltsort.", sourceObjective = "Schlagt mindestens 6 Belagerungsingenieure der Geißel nieder, um an Informationen über Gidwins Verbleib und seinen Entführer zu gelangen.", completion = "Hört sich so an, als hättet Ihr Erfolg gehabt. Hoffentlich reichen diese Informationen, um Gidwin zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27523] = { id = 27523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämmerschwinge, oh, wie ich Euch hasse...", description = "Ich habe zu meiner Zeit viel gesehen, {race}. Die Gipfel des Hyjal... die Seltsamkeiten der Scherbenwelt... einen Wall aus Geißelsoldaten auf dem Weg in die Schlacht. Aber noch nie zuvor habe ich eine so große und schockierend weiße Fledermaus wie Dämmerschwinge gesehen.\n\nWie er mich aus seinem Nest verspottet!\n\nDiese dämonische Albinofledermaus kreist südwestlich von hier, nördlich vom Faulholzsee. Findet und vernichtet ihn. Sollte er zu hoch fliegen, könnt Ihr ihn mit meinem Leuchtfeuer anlocken.", sourceObjective = "Beschafft einen Fellflicken von Dämmerschwinge.", progress = "Ich hoffe, Ihr habt diese Kreatur beseitigt.", completion = "Hervorragende Arbeit. Nun kann ich meine Arbeit fortsetzen, ohne von dieser großen, weißen Bestie abgelenkt zu werden.\n\nIch werde dieses Fell zu etwas verarbeiten, dass Ihr nutzen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27524] = { id = 27524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinde Wut", description = "Tarenar hat nicht gescherzt, als er sagte, Vernunft und Vorsicht interessieren ihn nicht. Er hätte diesem Hochelfen beinahe den Kopf abgeschlagen, als er auf der Suche nach Gidwin in den Pestwald lief. Ihr solltet ihm folgen.\n\nDer Pestwald ist ziemlich groß, {name}. Viel Glück. Ich hoffe, ihr <Jungs/Drei> kommt heil aus dem Wald heraus.", sourceObjective = "Findet Tarenar Sonnenhieb im Pestwald in den Östlichen Pestländern.", completion = "Ich habe nichts außer hirnlosen Untoten gefunden, aber davon jede Menge. Ich wollte mich gerade nach Stratholme durchtöten, als Ihr kamt. Hattet Ihr mehr Erfolg?", sourceObjectiveStatus = "unverified-source-field" }
quests[27525] = { id = 27525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wächter von Stratholme", description = "Baroness Anastari hält ihn gefangen? Hier im Pestwald?\n\nDer Pestwald ist groß... aber wir werden ihn finden. Wir WERDEN Gidwin finden.\n\nUnmittelbar in unserem Osten und Westen befinden sich zwei Nekropolen neben dem Weg nach Stratholme. Im Inneren werdet Ihr zwei Todesrittern begegnen - Totenschwurs Leutnants. Ich bezweifle, dass einer von ihnen Verwendung für eine Paladingeisel hätte, aber vielleicht wissen sie ja, wo Gidwin ist.", sourceObjective = "Tötet Omasum Pesthuf und Karthis Dunkelrune.", completion = "Wir müssen weiter! Wir sind schon ganz nahe!", sourceObjectiveStatus = "unverified-source-field" }
quests[27526] = { id = 27526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwins Schicksal enthüllt", description = "Rasch - findet einen Eingang zum Schlachthaus südlich von uns. Ich treffe Euch im Inneren.\n\nBereitet Euch auf einen Kampf vor!", sourceObjective = "Sucht nach Gidwin Goldzopf im Schlachthaus im Zentrum des Pestwalds.", completion = "Ihr glaubt ja nicht, wie froh ich bin, Euch beide zu sehen! Mir steigen gleich die Tränen in die Augen... Augen, die zu lange durch eine Banshee blicken mussten.\n\nTut mir leid, dass ich Euch so viel Ärger bereitet habe. Bringt Ihr mich zurück zur Karawane?", sourceObjectiveStatus = "unverified-source-field" }
quests[27527] = { id = 27527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ende der Reise", description = "Ich halte die Luft an diesem Ort nicht mehr aus. Der Gestank der Untoten ist schon schlimm genug, aber wenn man dem noch Pilze hinzufügt? Ich hasse Pilze!!\n\nIch werde zur Kapelle des Hoffnungsvollen Lichts zurückkehren, {name}... und ich nehme Tarenar und Fiona mit. Wir alle haben eine Pause verdient. \n\nHier, nehmt das. Das ist mein Ruhestein - mit ihm könnt Ihr Euch zur Kapelle versetzen lassen. Ich brauche ihn nicht - ich reise auf dem Wagen.\n\nUnd zwar auf dem VORDERSITZ.", sourceObjective = "Sprecht mit Fiona an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt mit Eurer Hilfe alle Erwartungen übertroffen, {name}. Die Türen meines Wagens stehen Euch stets offen.\n\nDie Jungs und ich haben sogar etwas Besonderes für Euch vorbereitet. Hier, trefft Eure Wahl!", sourceObjectiveStatus = "unverified-source-field" }
quests[27528] = { id = 27528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelmasse", description = "Man kann die Geißel nicht einfach töten. Sie kommt zurück. Man muss die verdorbene Masse zerstören, aus denen sie besteht... und selbst dann kehren diese Unholde manchmal als Schreckgespenster zurück.\n\nNur wenige Untote bringen so viel Masse mit wie die schwerfälligen Monstrositäten. Tötet sie und verbrennt ihre Leichen. Ihr findet sie überall im Pestwald.\n\nLasst Euren Zorn nicht erkalten, {race}. Vergesst nicht, dass diese Monstrositäten aus den Körpern guter Leute zusammengenäht wurden. Ihre Existenz ist ein Verbrechen.", sourceObjective = "Tötet 8 überladene Golems und steckt ihre Kadaver mit der Fackel des Kreuzfahrers in Brand.", completion = "Ein gesegnetes Feuer reinigt sogar das verdorbenste Fleisch.\n\nIm Angesicht des Lichts hatten sie keine Chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27529] = { id = 27529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidiger von Darroheim", description = "Die Schlacht von Darroheim war eine der großen Tragödien, die wir Menschen durch die Geißel erleiden mussten. Bis heute hallt sie nach.\n\nViele der mutigen Verteidiger der Stadt ziehen nun als schreckliche Diener der Geißel umher. Wir werden ihr Leid beenden.\n\nJagt Menschenfresserghule hier im Pestwald. Viele dieser Abscheulichkeiten waren einst rechtschaffene Menschen in Darroheim. Die Zerstörung ihrer Körper wird ihre Seele befreien.", sourceObjective = "Befreit 8 Darroheimgeister aus den Körpern der Menschenfresserghule und sprecht mit ihnen.", completion = "Es ist gut zu hören, dass Ihr die gequälten Seelen meiner Brüder gefunden und befreit habt. Meine Kraft ist erneuert, nun da ich weiß, dass zumindest einige der Verteidiger von Darroheim nicht mehr länger in der widerlichen Dienerschaft der Geißel gefangen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27530] = { id = 27530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kadaverbestien", description = "Feige Kultisten widmen sich im Süden einer düsteren Aufgabe: Sie reanimieren gewaltige Fleischberge, um aus ihnen Riesen zu erschaffen, die Kadaverbestien genannt werden. Zum Glück für uns sind diese Riesen noch leblos und schwach.\n\nNehmt dieses Amulett - benutzt es, um einen Brunnen heiliger Energie zu erschaffen. Versucht, drei dieser Quellen in der Nähe einer der Kadaverbestien zu platzieren, die von den Kultisten reanimiert werden. Die heilige Energie sollte ausreichen, um sie zu überladen und ihren Körper für immer zu zerstören.", sourceObjective = "Zerstört die Hüllen dreier Kadaverbestien, indem Ihr drei oder mehr Argentumlichtbrunnen neben ihnen platziert. Ihr könnt die Argentumlichtbrunnen nicht im Kampf platzieren und nicht weniger als zehn Meter voneinander entfernt.", completion = "Ihr seid ein wahrer Champion des Lichts, {name}. Ich wünsche Euch Glück für all Eure zukünftigen Unterfangen, wo auch immer sie Euch hinführen mögen.\n\nSolltet Ihr in Zukunft etwas benötigen, werdet Ihr mich hier finden - bis zu den Knien in den Leichen der Getöteten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27531] = { id = 27531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seuchenabwehrforschung", description = "Einst habe ich als Apotheker für die sogenannte \"Bansheekönigin\" Sylvanas gearbeitet. Ich habe sie einmal bewundert, aber etwas in ihr hat sich verändert. Sie ist nicht mehr sie selbst.\n\nIch habe den Schwur, der mich an die Verlassenen band, gebrochen und trat dem Kreuzzug bei. Nun benutze ich meine Kenntnisse der Alchemie, um nach einem Wirkstoff gegen die Seuche zu suchen. Der Pestwald ist der geeignete Ort dafür.\n\nIch brauche Nachschub für einige Reagenzien, die man im Pestwald findet. Ich werde Euch für jeden Gegenstand, den Ihr findet, bezahlen.", sourceObjective = "Beschafft 20 Faulbeeren, 5 abgetrennte Arme und 1 Stapel Fußabschabung eines Fleischgiganten.", progress = "Habt Ihr alles?", completion = "Ich liebe den Geruch von frischer Fußhornhaut, Ihr nicht auch?\n\nWenn wir ein Heilmittel für die Seuche finden wollen, müssen wir kreativ bei unseren Zutaten sein. Entschuldigt mich bitte, ich muss wieder an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27532] = { id = 27532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pestwaldturm", description = "Nach den ungünstigen Entwicklungen im Fall Gidwin denke ich, ein Mann meines Alters sollte die gefährliche Reise durch den Pestwald nicht antreten. Das ist nicht schlimm - ich werde den Pestwaldturm bei meiner nächsten Rundreise besuchen.\n\nAllerdings habe ich eine Lieferung für Judkins. Ihr seid jünger als ich und kampferprobt. Würdet Ihr ihm diese Lieferung bringen?", sourceObjective = "Bringt Leuchtfeuers Paket zu Erzapotheker Judkins beim Pestwaldturm in den Östlichen Pestländern.", progress = "Leuchtfeuers Paket... geht es Argus gut? Ist etwas passiert?", completion = "Puh. Jedes Mal, wenn ich Argus durch den Pestwald trotten sehe, befürchte ich, es wird das letzte Mal sein. Gut, dass er weise genug ist, ein Jungblut wie Euch zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27533] = { id = 27533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schicksal schlimmer als der Schlachter", description = "Die Bewohner des Schreckenstals wurden zuerst krank, dann böse. Das sind wirklich keine guten Zeiten.\n\nUnd die Schweine... sie wurden ebenfalls krank! Womit haben Schweine eine solche Krankheit verdient? Hah hah hah! Nichts!\n\nDie Leute interessieren mich nicht, aber die bösen Schweine machen mich immer noch traurig. Solltet Ihr sie jedoch töten... Wäre ich vielleicht glücklich.", sourceObjective = "Tötet 9 verseuchte Schweine.", completion = "Ich sehe sie! Ihr auch? Die kleinen Schweinegeister auf dem Weg zum großen Stall im Himmel...", sourceObjectiveStatus = "unverified-source-field" }
quests[27534] = { id = 27534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augustus' Quittungsbuch", description = "Ich bin jetzt bereit fürs Geschäftliche! Was wollt Ihr?\n\nOh, Moment mal... ohne mein Quittungsbuch kann ich kein Geschäft eröffnen. Wie soll ich ohne mein Quittungsbuch den Überblick behalten?\n\nIch muss es irgendwo in der Stadt gelassen haben. Ich hatte ein Zimmer im Gasthaus... dort muss das Buch sein.\n\nBringt mir mein Buch. Bitte, bringt es mir! Bringt mir mein Buch und Ihr werdet sehen! Ich eröffne mein Geschäft und Ihr werdet sehen, dass meine Preise der WAHNSINN sind!", sourceObjective = "Beschafft Euch Augustus' Quittungsbuch aus dem Gasthaus im Schreckenstal.", progress = "Habt Ihr mein Quittungsbuch? Ich will endlich wieder an die Arbeit gehen!", completion = "Da ist es! Oh meine Güte! Ich hatte vergessen, wie voll es war!\n\nDies ist ein glorreicher Tag, {name}! Toll! Wahnsinnig gut, sage ich Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[27535] = { id = 27535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bisschen meschugge", description = "Ich sehe gelegentlich nach Augustus im Schreckenstal, nur um sicherzustellen, dass es ihm gut geht. Manche von uns Untoten kommen wohl mit der Seuche besser klar als andere.\n\nDas Schreckenstal liegt westlich von hier. Würdet Ihr für mich nach ihm sehen?", sourceObjective = "Sprecht mit Augustus dem Meschuggenen im Schreckenstal.", completion = "Ihr seid am richtigen Ort, mein Herr! Jawoll, es gibt keinen besseren Ort als das Schreckenstal! Das Juwel von Lordaeron!", sourceObjectiveStatus = "unverified-source-field" }
quests[27536] = { id = 27536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Größtenteils harmlos", description = "Hier ist noch ein Gefallen, den Ihr mir tun könnt, <alter Freund/alte Freundin>.\n\nKürzlich ist eine ganze Ladung Landminen aus Beutebucht angekommen. Aber jemand hat sie alle über Nacht gestohlen!\n\nWer immer es war, er war nicht besonders sorgfältig, denn er hat sie überall im Sumpf östlich von hier fallengelassen. Kein Goblin, der mir bekannt ist, würde so unvorsichtig sein.\n\nIch möchte, dass Ihr da rausgeht und diese Landminen für mich einsammelt. Ich bin sicher, dass sie vollkommen sicher und entschärft sind. Jede einzelne. Jawohl.", sourceObjective = "Sammelt 8 entschärfte Landminen im Sorgendunkel östlich von Kraulsumpf.", progress = "He, habt Ihr die Dinge beschaffen können, um die ich gebeten hatte?", completion = "Was hab' ich Euch gesagt, hm? Völlig harmlos!\n\nIch sorge dafür, dass ein paar dieser Dinger zu Euren Freunden geschafft werden, {name}. Mit Rabatt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27537] = { id = 27537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer Elementare sät, wird Sturm ernten", description = "Unsere Freunde des Irdenen Rings haben versucht, Portale zurück nach Sturmwind zu öffnen, aber sie hatten kein Glück. Thordun hier sagt mir jedoch, dass er vielleicht die Lösung für unser Problem hat.\n\nDie wahnsinnigen Wasserelementare im nahegelegenen Fluss Verrall sind in Raserei verfallen. Thordun sagt, dass wir ihre Energie kanalisieren können, um ein Portal zu schaffen.\n\nIch habe ja keine Ahnung von diesem Elementar-Schnickschnack, aber eines verstehe ich ganz deutlich: Elementare töten und ihren Strudelkern nehmen. Bringt sie zu Talaa im Hof!", sourceObjective = "Tötet matschige Wasserelementare, um 5 Strudelkerne zu sammeln.", progress = "Hallo {class}. Kurdran hat mir gesagt, dass Ihr eine Lösung für unser Portalproblem habt?", completion = "Eines könnt Ihr mir glauben, {name}. Diese Elementarenergien sind so mächtig, so chaotisch! Kein Wunder, dass der Schattenhammer seine Festung hier errichtet hat.\n\nIch sollte diese Energien in etwas Gutartigeres und Produktiveres umwandeln können. Probieren wir es...", sourceObjectiveStatus = "unverified-source-field" }
quests[27538] = { id = 27538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der perfekte Verband", description = "Geht Ihr zufällig zur Mündung des Verrall? Dann habe ich einen Rat für Euch, der Euren Männern hier sehr helfen kann… und meinem Vogel!\n\nWenn Wasserelementare sich ihren Weg durch Gestein bahnen, entsteht ein seltsamer Schlamm. Getrocknet ist er hart wie Stein, aber er enthält die erfrischende Macht des Wassers. Wenn Ihr einen Gipsverband aus diesem Schlamm herstellt, wachsen gebrochene Knochen wieder zusammen, fest wie Eisen.\n\nBringt ein wenig von diesem Schlamm zu Talaa, der Schamanin da unten. Sie wird wissen, was damit zu tun ist!", sourceObjective = "Sammelt 10 Haufen Verrallschlamm.", progress = "Was höre ich da immer über diesen Verrallschlamm?", completion = "Oh… Schlamm. Ihr habt mir Schlamm gebracht?\n\nOh, dieses Zeug pulsiert ja regelrecht vor Macht! Jetzt verstehe ich, was Thordun meint. Ich werde ihn an all unsere Heiler verteilen. Unsere Verwundeten werden im Handumdrehen wieder auf den Beinen sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[27539] = { id = 27539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werft sie auf den Haufen", description = "Ich sammle die Köpfe der Skelette, die ich besiege. Ich habe schon einen kleinen Haufen zusammen.\n\nSolltet Ihr zufällig Schädel finden, könnt Ihr sie gern dazu legen. Der Schädelhaufen scheint die Wellen der Untoten zurückzuhalten und... na ja... ich betrachte ihn auch sehr gern.", sourceObjective = "Beschafft 16 stinkende Schädel von verfluchten Magiern und Soldaten der Geißel im Pestwald.", progress = "Ihr seid ja ziemlich beladen. Sind das etwa Schädel?", completion = "Möge mein Haufen immer weiter wachsen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27541] = { id = 27541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektionen der Vergangenheit", description = "Dieser unglückliche Forscher hat offensichtlich in letzter Zeit ziemliches Pech gehabt.\n\nDie Vernunft gebietet, dass Ihr die Leiche auf Hinweise durchsucht. Darum wird Euch niemand beneiden, aber wir brauchen Hinweise, die Licht in unsere Umgebung bringen...", sourceObjective = "Erhaltet die zerbrochene Brille.", progress = "Gibt es Neuigkeiten, {name}?", completion = "Seltsam...\n\nSieht so aus, als ob jemand Edelsteine als Linsen benutzt hat.\n\nIch sollte sie ohne großen Aufwand reparieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27542] = { id = 27542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An die Front", sourceObjective = "Die Stunde des Sieges rückt näher, {name}. Godfrey hat einen Plan geschmiedet, um unsere Feinde zu dezimieren. Ich schicke Euch mit ihm und seinen Männern ins Feld, um die rebellischen Aufrührer in die Knie zu zwingen und das Schicksal des Allianzabschaums zu besiegeln, der unsere Ländereien bedroht.\n\nUnser letzter Marsch beginnt, sobald Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[27543] = { id = 27543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wir getan haben" }
quests[27544] = { id = 27544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarische Hartnäckigkeit", description = "Ich glaube, diese Druiden geben nie auf. Ich habe die Pestländer schon vor Jahren aufgegeben, aber diese Optimisten vom Zirkel des Cenarius behaupten, es gäbe noch Hoffnung für dieses Land.\n\nDie letzte Besucherin war eine Nachtelfe, die auf dem Weg nach Norden, ins Fungustal, war. Sie sagte, diese Länder würden sich vollständig erholen, wenn wir uns nur Mühe geben. Ich weiß nicht, ob ich das glauben soll.\n\nGlaubt Ihr diesen Unsinn?! Vielleicht solltet Ihr einmal mit ihr reden. Sie müsste immer noch dort oben sein.", sourceObjective = "Sprecht mit Rayne nahe des Eingangs zum Fungustal.", completion = "Wenn Ihr mich finden konntet, sollte ich wohl an meiner Verstohlenheit arbeiten.\n\nWollt Ihr mir bei der Heilung der Pestländer helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27545] = { id = 27545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg ist geöffnet", description = "Mein Schamanenfreund und ich werden hier bleiben, um das Portal aufrechtzuerhalten.\n\nIhr solltet nach oben gehen und Kurdran benachrichtigen, dass unsere Arbeit hier erledigt ist. Es wird ihn freuen, zur Abwechslung mal gute Nachrichten zu hören.", sourceObjective = "Sprecht mit Kurdran Wildhammer in Hochstade im Schattenhochland.", completion = "Ha! Ich wusste, dass Ihr ein {class} seid, auf den ich mich verlassen kann, {name}. Ihr könnt das Portal jederzeit benutzen, um von Sturmwind zurück ins Schattenhochland zu gelangen.\n\nUnd jetzt zum Geschäft. Wir müssen die verschollenen Wildhammerklans, die überall im Schattenhochland verstreut sind, finden und vereinen. Am besten sprecht Ihr zunächst mit Thordun hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[27547] = { id = 27547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folgenlos", description = "Unsere Streitkräfte in Lohenscheit wurden vor Kurzem durch einen Schleichangriff überrascht. Die 7. Legion hat es geschafft, ihre Späher in die Stadt einzuschleusen und schließlich unsere Truppen zu dezimieren.\n\nDie Dunkle Fürstin hat uns mit einer Rettungsmission beauftragt. Wir sollen Überlebende finden und sie sicher aus Lohenscheit herausbringen. Wenn noch Soldaten am Leben sind, so sind sie wahrscheinlich nutzlos, aber wir werden das tun, was die Dunkle Fürstin befiehlt.\n\nLasst uns diesen Unsinn hinter uns bringen, {name}. Lohenscheit ist direkt im Südwesten der Frontlinie der Verlassenen.", sourceObjective = "Rettet 8 kauernde Soldaten.", completion = "Was heute hier geschehen ist, bleibt unter uns. Nur ein Wort zu irgendjemandem und Ihr findet Euch in einer Leichengrube neben diesen armen Narren wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[27548] = { id = 27548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrstunden in Angst", description = "Unsere Feinde werden immer schlauer und passen sich an unsere Strategien an. Erst vor Kurzem wurde Lohenscheit im Südwesten von hier angegriffen. Unsere Streitkräfte, die die Stadt besetzt halten, wurden natürlich dezimiert, aber was den Angriff besonders interessant macht, war die Völkerzusammensetzung der angreifenden Truppe. Es gab keine Menschen.\n\n<Walden lacht.>\n\nSie fürchten sich zu Recht davor, als Verlassene wiedererweckt zu werden.\n\nLasst uns den Nicht-Menschen eine Lektion in Angst erteilen. Zusammen werden wir ihnen zeigen, was mit Leichen geschieht, für die wir keine Verwendung haben.", sourceObjective = "Tötet 12 Späher der 7. Legion.", completion = "Ich nehme an, dass wir jetzt weniger Menschen an der Schlachtenfront sehen werden. Das Risiko für diese Feiglinge ist zu groß.", sourceObjectiveStatus = "unverified-source-field" }
quests[27549] = { id = 27549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bei Sternenlicht", description = "Schaut Euch das an, {name}.\n\n<Harrison hält die Brille des toten Spähers hoch.>\n\nIch habe die Klammer in der Mitte angezogen und die Drähte an den Kanten etwas gezwirbelt. Sie mag nicht bequem sein, aber sie sollte halten.\n\nWenn ich Eure Schrifttafeln richtig übersetzt habe, ist hier etwas versteckt - ein letztes Teil für unser Puzzle.\n\nIch hoffe, Eure Brille birgt den Schlüssel.\n\nLasst mich wissen, was Ihr findet!", sourceObjective = "Sammelt 7 schwebende Sternenlichter.", progress = "Und?\n\nHabt Ihr etwas Interessantes gefunden?", completion = "Nun, mein Junge, es sieht so aus, als ob Ihr es wieder geschafft habt.\n\n<Harrison zeigt auf ein Bild auf den Schrifttafeln.>\n\nDieses Sternenlicht ist genau das, was gefehlt hat.\n\nJetzt können wir an die Arbeit gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27550] = { id = 27550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lohenscheits Fall", description = "Die Angriffe gegen unsere Front sind ein Ablenkungsmanöver. Da unsere Aufmerksamkeit dem Ansturm der Worgen galt, hat die Allianz es geschafft, Lohenscheit von unseren Besatzungstruppen zurückzuerobern.\n\n<Godfrey übergibt Euch ein Bündel Fackeln.>\n\nEs muss ausgelöscht werden.\n\nMit diesen Fackeln werden wir Lohenscheit bis auf die Grundmauern niederbrennen und nur Asche für den Feind hinterlassen, hinter der er sich verstecken kann.\n\nLasst uns keine weitere Minute vergeuden. Lohenscheit liegt südwestlich der Frontlinie der Verlassenen. Führt uns dorthin, {name}.", sourceObjective = "Benutzt das Bündel Fackeln, um das Rathaus von Lohenscheit, das Gasthaus von Lohenscheit und die Kapelle von Lohenscheit niederzubrennen.", progress = "Ich spüre keine Reue.", completion = "Der Teil von mir, der aus Gilneas stammte, starb an der Witterfront. Es bleibt nur Rache, {name}. Und in der Hinsicht haben wir noch einiges zu tun. Erspart mir Eure sinnlosen Fragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27551] = { id = 27551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schreiben der Baroness", description = "Die Notiz stammt von Baroness Anastari. Darin beschreibt sie ein Ritual, das sehr bald auf dem mittleren Schlachthaus im Pestwald abgehalten werden soll - etwas südlich von Tarenars Aufenthaltsort. Vielleicht halten sie dort Gidwin fest!\n\nTarenar muss davon erfahren... und zwar rasch, bevor es zu spät ist!", sourceObjective = "Bringt Tarenar das Schreiben der Baroness.", progress = "Was? Habt Ihr etwas gefunden?", completion = "Das ist es! Wenn das, was in dem Schreiben steht, stimmt, dann ist er auf der anderen Seite des Hügels!\n\nWorauf warten wir noch, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27555] = { id = 27555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fionas Glücksbringer", sourceObjective = "Fiona hat ein paar ihrer Glücksbringer im Karawanenwagen gelassen.\n\nAls Händlerin kann sie ziemlich gut mit Geld umgehen. Vielleicht könnt Ihr Eure Finanzen verbessern, wenn Ihr einen ihrer Glücksbringer tragt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27556] = { id = 27556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwins Waffenöl", sourceObjective = "Gidwin hat einige Flaschen Waffenöl im Karawanenwagen zurückgelassen.\n\nEr scheint im Nahkampf ein recht wilder Gegner zu sein. Vielleicht wird Euch sein Waffenöl ebenfalls gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27557] = { id = 27557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarenars Talisman", sourceObjective = "Tarenar hat einige heilige Talismane im Karawanenwagen ausgelegt. Sie wirken unbenutzt.\n\nSie scheinen magischer Natur zu sein. Wenn Tarenar sie nicht benutzt, könnte es doch nicht schaden, sich einen für eine Weile auszuleihen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[27558] = { id = 27558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pamelas Puppe", sourceObjective = "Ihr findet eine kleine Puppe in der hinteren Ecke des Karawanenwagens.\n\nTarenar sagt, sie gehöre Gidwin und Gidwin sagt, es wäre wahrscheinlich Tarenars.", sourceObjectiveStatus = "unverified-source-field" }
quests[27559] = { id = 27559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vex'tuls Armbinden", sourceObjective = "Vex'tul hat einige Armbinden im Karawanenwagen zurückgelassen. Er war sogar so freundlich, sie zu falten und separat von den Habseligkeiten aller anderen aufzubewahren.\n\nVex'tul schätzt Stärke mehr als alles andere. Als Ihr Euch vorbeugt, spürt Ihr Überreste seiner Kraft, die aus den Armbinden strömt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27560] = { id = 27560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argus' Tagebuch", sourceObjective = "Ihr entdeckt ein verwittertes Tagebuch im Karawanenwagen. Das Emblem des Argentumkreuzzugs auf dem Buchrücken weist darauf hin, dass es Argus gehört.\n\nIn dem Tagebuch hat Argus einige seiner Erfahrungen während seiner Zeit beim Kreuzzug niedergeschrieben. Es sollte Euch interessanten Lesestoff auf der Reise bieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27561] = { id = 27561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rimblats Stein", sourceObjective = "Euch fällt ein kleiner Steinhaufen im Karawanenwagen auf.\n\nDie Steine wirken nicht ungewöhnlich, doch einer erregt Eure Aufmerksamkeit. Ihr spürt die Wärme, die von ihm ausgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27562] = { id = 27562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beezils Zahnrad", sourceObjective = "Beezil fühlt sich anscheinend schon wie zuhause. Er hat mehrere seltsame Apparate in den Karawanenwagen gestopft.\n\nDie meisten erscheinen Euch zu unpraktisch oder gefährlich, um sie mitzunehmen. Ein kleines Zahnrad sieht jedoch recht gut verarbeitet aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[27564] = { id = 27564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt das Refugium", description = "Calen hat uns benachrichtigt. Der Schattenhammer ist in das Refugium eingedrungen!\n\nWenn Ihr nach einer Gelegenheit sucht, um seine Gunst zu erlangen, dann ist dies der rechte Zeitpunkt!", sourceObjective = "Sprecht mit Calen im Zinnoberrefugium.", completion = "Ich hoffe, dass Ihr so hart im Nehmen seid, wie Eure Ausrüstung es verspricht. Der Schattenhammer hat irgendwie einen Weg in das Refugium gefunden. Ich brauche jemanden, der sie zur Strecke bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27565] = { id = 27565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Gefängnis", description = "Es ist uns gelungen, jemand in das Gefängnis der Dunkeleisenzwerge einzuschleusen.\n\nAlso... es ist uns möglicherweise gelungen.\n\nKevin Dawson hatte die... Ehre... nachzusehen, was dort drüben vor sich geht. Doch seitdem haben wir nichts mehr von ihm gehört. Ihr seht so aus, als ob Ihr nicht gerne sterbt. Ihr solltet nachschauen gehen, ob er in Ordnung ist!\n\nEr sollte eigentlich in der Halle am südlichen Ende der Höhle vor uns sein... Doch etwas sagt mir, dass er es vielleicht nicht bis dahin geschafft hat.", sourceObjective = "Findet Kevin Dawson.", completion = "Ich habe keine Ahnung, wieso ich noch am Leben bin. Die Patrouillen laufen an mir vorbei, als ob ich gar nicht hier wäre.\n\n...Bin ich tot, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27567] = { id = 27567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenhammer?! Nein!", description = "Es ist zwar schwer zu glauben, aber es gibt Mitglieder des Schattenhammers hier in den Schwarzfelstiefen! Ich weiß nicht, wie viele von ihnen durch diesen Ort kriechen, aber ich habe gehört, dass Ihre Verhörmeisterin Gerstahn in dieser Halle ist.\n\nIch weiß nicht, warum sie hier foltern, aber vielleicht könnt Ihr es herausfiniden, indem Ihr Gerstahn entgegentretet?", sourceObjective = "\"Verhört\" Verhörmeisterin Gerstahn.", completion = "Hmm... wie ich sehe, war sie nicht hilfsbereit. Hoffentlich können wir sie noch aufhalten, bevor etwas Furchtbares geschieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27568] = { id = 27568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenschmiede unterwandern", description = "Könnt Ihr ein Geheimnis für Euch behalten? Ich hab' ein Geheimnis, das ich mit Euch teilen will.\n\nHier sind alle VERRÜCKT!!!\n\nDa drüben sind Goblins, dort sind Dunkeleisenzwerge und ein riesiges lebendes Feuer hinter dem Tor da! Und das ist nur das, was ich in dieser kleinen Höhle sehe!\n\nUnd Euch! Was macht Ihr hier?\n\nAh, ich verstehe. Winky hat Euch geschickt, nicht wahr? Hat Euch geschickt, um mit Ausgrabungsleiter Seymour zu sprechen, der hinter diesem Tor gleich rechts ist, nicht wahr? Dann geht! Oralius kümmert das nicht!\n\n...DAS WERDE ICH DIR HEIMZAHLEN WINKY!!!\n\n<Oralius fängt an zu schluchzen.>", sourceObjective = "Sprecht mit Ausgrabungsleiter Seymour.", completion = "Ich würde mich von Oralius fern halten. Sehr, sehr weit fern halten. Er ist nicht ganz richtig im Kopf.\n\nAber zurück zum Geschäft.", sourceObjectiveStatus = "unverified-source-field" }
quests[27569] = { id = 27569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategen der Dunkeleisenzwerge", description = "General Zornesschmied und Golemlord Argelmach führen die Armeen der Dunkeleisenzwerge und ihre Golems gegen uns. Wenn wir sie überwinden wollen, müssen die beiden getötet werden.\n\nGeht durch diese Tür und schließt das Schloss der Schattenschmiede auf, die die Ost- und Westgarnisonen trennt. Dann folgt der Treppe und haltet Euch oben links, bis Ihr die Westgarnison erreicht. Dort findet Ihr den General und den Golemlord.\n\nBleibt immer wachsam, da beide äußerst erfahrene Kämpfer sind. Wenn Ihr erfolgreich seid, sucht Mayara Wolkenglanz.", sourceObjective = "Tötet General Zornesschmied und Golemlord Argelmach.", completion = "Ich bin sicher, dass Ihr der Aufgabe gewachsen seid, die ich für Euch habe, wenn Ihr es unversehrt bis hierher geschafft habt.\n\n<Mayara Wolkenglanz flüstert ganz leise.>\n\nUnter uns gesagt - Ihr solltet Euch während Eures Aufenthaltes hier ein wenig im \"Grimmigen Säufer\" vergnügen. Es könnte Euer letztes Getränk sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27571] = { id = 27571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Grimmige Säufer", description = "Es gibt Stimmen, die behaupten, dass der \"Grimmige Säufer\" das Geheimnis der Kriegsanstrengungen der Dunkeleisenzwerge ist. Ihre Krieger erholen sich dort und kommen durstig nach einer weiteren unschuldigen Seele wieder heraus. Ich glaube, wir können sie erheblich behindern, indem wir dort ein wenig Chaos anrichten.\n\nIhr müsst einen Streit mit drei der berüchtigten Stammkunden anfangen. Beschädigt die Fässer und Hurley Pestatem wird herbeieilen. Stehlt die Gegenstände vom Tisch in der Nähe von Stöpsel Zapfring und er wird kämpfen. Was Ribbly Schraubstutz angeht - mit dem Hitzkopf müsst Ihr nur reden. Meldet Euch bei Orfus, wenn Ihr fertig seid.", sourceObjective = "Kämpft gegen Hurley Pestatem, Stöpsel Zapfring und Ribbly Schraubstutz.", progress = "Beeilt Euch bitte. Zeit ist ein Luxus, den wir nicht haben.", completion = "Die Dunkeleisenzwerge haben unser Donnerbräu gestohlen. Nach dieser Tat kann ich sie nicht am Leben lassen. Wenn ich könnte, würde ich sie alle höchstpersönlich töten!\n\nWenn Ihr allerdings nach vorne schaut, werdet Ihr sehen, dass wir uns im Moment um dringendere Dinge zu kümmern haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27573] = { id = 27573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pakt mit den Dunkeleisenzwergen", description = "Vor uns befindet sich die Kreatur, die nur als Botschafter Flammenschlag bekannt ist. Er ist der Botschafter von Ragnaros dem Feuerlord und vertritt ihn beim Volk der Dunkeleisenzwerge. Jenseits dieser Kammer befindet sich die Gruft der Beschwörer. Dort sind die Geister der sieben Patriarchen der Dunkeleisenzwerge zu Hause, die Ragnaros in unsere Welt gerufen haben.\n\nMöglicherweise habt Ihr noch nichts von dem großen Feuer gehört, aber er bedeutet das Ende für Azeroth, wenn er nicht aufgehalten wird. Diese Individuen stehen in direkter Verbindung zu der Macht, die er über die Dunkeleisenzwerge hat. Tötet sie, damit dieses Volk eines Tages vielleicht rehabilitiert werden kann.", sourceObjective = "Tötet Botschafter Flammenschlag und Un'rel.", completion = "Ich kann alleine nicht weitermachen, egal, wie viel Kampferfahrung ich habe. Das Lyzeum hat sich als zu schwer für mich erwiesen. Doch da Ihr hier seid... Ihr könntet der Schlüssel zu all dem hier sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27574] = { id = 27574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich vergesse nie ein Gesicht", description = "Ihr habt einen teilweise verdauten Kopf gefunden. Lord Godfrey wird aufmerksam, als er ihn sieht. Vielleicht solltet Ihr ihm den Kopf geben.", sourceObjective = "Übergebt den teilweise verdauten Kopf an Lord Godfrey im Silberwald.", progress = "Ich vergesse nie ein Gesicht!", completion = "Das Gesicht kenne ich, {name}. Dieser Kopf gehört einem ehemaligen Bewohner von Gilneas mit Namen Sean Dempsey. Er wurde vor dem großen Ausbruch von Crowley gefangen genommen.\n\n\n\nIch frage mich, ob es möglich wäre, ihn wieder zusammenzusetzen. Der Rest von ihm muss sich in den Bäuchen dieser Krokilisken befinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27575] = { id = 27575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Bauch der Bestie", description = "Ich glaube, dass wir ihn wiederherstellen können. Wenn es uns gelingt, ihn wieder zusammenzusetzen, kann er uns vielleicht Informationen über Crowley geben.\n\nWir müssen jeden Krokilisken im Sumpf töten, bis wir den Rest von Sean Dempseys Leiche gefunden haben. Aus dem Bauch des Ungeheuers wird dieser Mensch wiedergeboren!", sourceObjective = "Findet Dempseys Torso, Dempseys Gliedmaßen und Dempseys Eingeweide.", progress = "Wenigstens werden wir einige Krokiliskenbälge bekommen, um hübsche Schuhe daraus zu fertigen.", completion = "Sehen wir mal, ob ich das schaffe.\n\n<Godfrey murmelt leise etwas vor sich hin.>\n\n...Schienbein gehört an den Oberschenkelknochen...\n\n...Oberarm an den Torso...\n\n...mit ein wenig Nekromantie der Verlassenen garnieren...\n\nTA-TAAA!", sourceObjectiveStatus = "unverified-source-field" }
quests[27576] = { id = 27576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flickwerkbefehle", description = "Die kürzlichen Ereignisse machen mehr als deutlich, dass sich hier zu verkriechen und ab und zu einmal Grim Batol anzugreifen weder ausreicht, um Unsereins zu beschützen, noch um Grim Batol zurückzuerobern. Wir müssen aggressiver vorgehen und sie direkt ins Herz treffen.\n\nIch habe mich bereit erklärt, ein paar Drachen zur Unterstützung Eurer Kommandanten zu schicken. Sie waren bereits dabei, einen Angriffsplan für Grim Batol zu schmieden, also solltet Ihr Euch zunächst darauf konzentrieren.\n\nSucht nach Flick am Drachenmalpass, südlich in der Schlucht unter uns.", sourceObjective = "Sprecht mit Flick im Drachenmalpass.", completion = "Ihr habt die Drachen mit ins Spiel gebracht! Gut gemacht.\n\nUnsere Pläne waren bereits geschmiedet, als wir von den Drachen gehört haben. Sie helfen uns, indem sie die Rückzugrouten des Feindes abschneiden.\n\nEs ist noch nicht zu spät für Euch, an dem Spaß teilzuhaben. Wir haben ein Bisschen für Euch aufgehoben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27577] = { id = 27577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtpläne der 7. Legion", description = "Lohenscheit zu vernichten verschafft uns auf dem Schlachtfeld sicher einen Vorteil gegenüber der Allianz, doch unser wahres Ziel hier ist es, sie geschlagen zurückzulassen.\n\nSüdwestlich von hier, in der Nähe des Graumähnenwalls, liegt das Basislager der 7. Legion. Wir müssen dieses Basislager nach Schlachtplänen durchsuchen. Mit den Schlachtplänen der 7. Legion können wir die Truppenbewegung der Allianz im Silberwald genau nachverfolgen.", sourceObjective = "Besorgt Euch den Schlachtplan der 7. Legion.", progress = "Durchsucht jeden ranzigen Zwergenleichnam.", completion = "<Walden überfliegt den Schlachtplan.>\n\nSieht aus, als setzte die Verstärkung von den Schiffen in Gilneas sich bald in Bewegung. Crowley und Blutfang haben im Südosten ein Lager der Gilnearischen Befreiungsfront eingerichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27578] = { id = 27578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgans Verwirklichung", description = "Imperator Dagran Thaurissan übt von seinem Thron vor uns die absolute Kontrolle über die Stadt aus.. Wenn wir seine Armeen aufhalten wollen, müssen wir die Herrschaft des Imperators beenden.\n\nIhr müsst an seiner Leibwache - einschließlich des riesigen Magmus - vorbei, um an ihn heranzukommen. Bewegt Euch so schnell wie möglich. Wenn sich die Nachricht verbreitet, bevor Ihr fertig seid, wird die ganze Stadt zu seinem Thron eilen.\n\nDenkt daran, die Türen im Lyzeum öffnen sich nur, wenn Ihr die Kohlenpfannen mit Fackeln der Flammenbewahrer angezündet habt. Viel Glück.", sourceObjective = "Tötet Imperator Dagran Thaurissan.", completion = "Ihr habt es geschafft! Ihr habt es wirklich geschafft! All die Jahre, die Morgan Pläne geschmiedet und gewartet hat, haben endlich Früchte getragen.\n\nSie hat zwar ihr Land und ihre Familie verloren, als Ragnaros das Land entzwei riss, aber jetzt, da die Dunkeleisenzwerge angeschlagen sind, werden wir gefahrlos ein neues Königreich in der Brennenden Steppe aufbauen können. Nicht einmal der Feuerlord selbst wird in der Lage sein, die Mauern der Hauptstadt zu durchbrechen!\n\nIhr müsst unbedingt eines Tages, wenn wir fertig sind, zurückkommen. Ihr werdet unser höchster Ehrengast sein. Ich danke Euch von ganzem Herzen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27579] = { id = 27579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Gefängnis", description = "Der Schattenhammer wird 'nen Grund für seine Anwesenheit hier haben. Wir ha'm keine Ahnung, wieso, aber Thal'trak verrät Euch eins unserer kleinen Geheimnisse: Der Schurke Lexlort wartet vor der Halle von Verhörmeisterin Gerstahn, um sie abzumurksen, wenn er 'ne Chance dazu bekommt.\n\nSie is' aber zu clever dafür, als müsst Ihr da reingehen un' das erledigen, ya? Geht und sprecht mit Lexlort und sagt ihm Bescheid. Ich bin sicher, er wird damit einverstanden sein.", sourceObjective = "Findet Lexlort.", completion = "Kommt hier rüber. Wenn Ihr meine Tarnung auffliegen lasst, dann schwöre ich beim Kriegshäuptling, dass ich Euch auf der Stelle töten werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27580] = { id = 27580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfrieden säen", description = "Die Verstärkung der Allianz hat eine Stellung in der südwestlichen Region des Silberwalds etabliert - das Basislager der 7. Legion. Für uns hat es oberste Priorität, in diesem Basislager Unfrieden unter den Truppen zu säen. Die Mission ist ein blitzschnelles Attentat auf ihren Feldkommandanten, General Marstein. Sein Tod wird den Vormarsch der Allianz nicht aufhalten, aber er wird ihre Ränge aufweichen.", sourceObjective = "Ermordet General Marstein.", completion = "Der Rest der Allianzflotte wird bald eintreffen und ihr Basislager dezimiert vorfinden. Und jetzt kommen wir zum zweiten und wichtigsten Teil unseres Schlachtplans.", sourceObjectiveStatus = "unverified-source-field" }
quests[27581] = { id = 27581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenhammer?! Nein!", description = "Gerstahn ist viel zu schwer bewacht. Außerdem ist sie viel zu schlau, um ihren Posten zu verlassen. Also werde ich sie nicht töten.\n\nIhr werdet es tun.\n\nIch werfe auch noch etwas, das ich einer Wache abgenommen habe, mit in die Waagschale, damit es die Mühe für Euch wert ist.", sourceObjective = "Tötet Verhörmeisterin Gerstahn.", completion = "Die Anwesenheit des Schattenhammers macht unsere Aufgabe hier nur noch komplizierter. Doch Ihr habt Euren Teil für den Moment getan. Ihr habt eine Belohnung für Eure Bemühungen verdient... und ein wenig Ruhe. Lasst uns hier verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27582] = { id = 27582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenschmiede unterwandern", description = "Ich fürchte, wir kämpfen momentan auf verlorenem Posten. Es wäre schon schwierig genug, die Dunkeleisenzwerge allein zu besiegen, aber ihre Elementarverbündeten haben ihnen nagelneue Krieger verschafft, mit denen wir nicht mithalten können.\n\nIhr müsst uns helfen, ihren Bereich zu infiltrieren und so viele ihrer wichtigen Anführer wie möglich zu töten. Das wird hoffentlich ihren Streitkräften einen Schock versetzen und das Blatt zu unseren Gunsten wenden. Meldet Euch bei Razal'hieb für weitere Anweisungen. Er ist jenseits dieses Tors auf der rechten Seite stationiert.", sourceObjective = "Sprecht mit Razal'hieb.", completion = "Hinter dieser Tür liegt der Kommandant der Armee der Dunkeleisenzwerge, umgeben von ausgebildeten Soldaten. Fühlt Ihr Euch gerüstet für ein kleines Gemetzel?", sourceObjectiveStatus = "unverified-source-field" }
quests[27583] = { id = 27583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die nördliche Flanke", description = "Ich habe befohlen, dass ein Verteidigungsring an unserer nördlichen Küste bei der Wuchernden Bucht eingerichtet wird. Unsere Späher berichten, dass die Naga versucht haben, dort an Land zu gehen.\n\nGralok hat das Kommando über diese Operation. Meldet Euch bei ihm und sichert den Strand!", sourceObjective = "Meldet Euch bei Gralok in der Wuchernden Bucht im Schattenhochland.", completion = "Kriegsfürstin Zaela hat Euch geschickt? Gut.\n\nWenn Ihr von der Horde so stark seid, wie Eurer Kriegshäuptling behauptet, erwarte ich Unmengen vergossenen Blutes auf diesen Ufern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27584] = { id = 27584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutrote Brandung", description = "Dieser Nagaabschaum hat vor, den Fluss nach oben zu ziehen, um die Bastion des Zwielichts zu verstärken. Wir werden ihnen die Fischköpfe ABREISSEN und ihnen die GRÄTEN ZIEHEN.\n\n<Gralok rammt sein Breitschwert in den Boden.>\n\nVernichtet die Schwarzschuppen!", sourceObjective = "Tötet eine beliebige Kombination aus 15 Plünderern der Schwarzschuppen oder Herrinnen der Schwarzschuppen.", completion = "<Garlok mustert Euch.>\n\nIhr seid eine echte Kämpfernatur, {name}. Ich habe es genossen, Euch bei der Arbeit zu beobachten. Vielleicht gehört das Drachenmal ja doch zu Eurer Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27585] = { id = 27585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die 109te Division", description = "General Zornesschmied und Golemlord Argelmach sind direkt verantwortlich für das grässliche Abschlachten der 109ten Division des Kargath Expeditionskorps. In dieser Division waren eine Menge guter Trolle und Orcs - viele davon waren enge Freunde von mir.\n\nNun <junger/junge:r> {race}, es ist an der Zeit, unsere gefallenen Brüder endlich zu rächen.\n\nSchließt das Schloss der Schattenschmiede auf, dann folgt der Treppe und haltet Euch oben links, bis Ihr die Westgarnison erreicht. Tötet Zornesschmied und Argelmach und wagt es ja nicht, einem von ihnen Gnade zu erweisen.", sourceObjective = "Tötet General Zornesschmied und Golemlord Argelmach.", completion = "Genau vor uns liegt der \"Grimimge Säufer\". Eine schäbige Bar gefüllt mit unseren Feinden, die volltrunken und daher unfähig sind, zu kämpfen.\n\n<Hierophantin Theodora Mulvadania grinst.>\n\nReif zum Schlachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27586] = { id = 27586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombiger Badestrand", description = "Ich konnte diese Mörser aus unserem Luftschiff retten, als es über dem Hafen des Drachenmals explodierte. Doch Munition ist knapp.\n\nWährend Ihr am Strand entlang lauft, tut mir den Gefallen und sammelt alle Mörserblindgänger ein, die Ihr finden könnt.\n\nBlindgänger mag ich am allerliebsten. Man weiß nie, WANN sie losgehen. Die perfekte Überraschung für einen Feind.", sourceObjective = "Sammelt 8 Mörserblindgänger am Strand bei der Wuchernden Bucht.", progress = "Habt Ihr die Blindgänger? Gebt sie mir!\n\n… Vorsichtig!", completion = "Oh ja. JA! Damit können wir ganz sicher jemanden erledigen.\n\nWahrscheinlich ein paar Naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[27587] = { id = 27587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unverschämt lecker", description = "Wisst Ihr, ich habe hier ein Problem, bei dem Ihr mir vielleicht helfen könntet.\n\nNun, zusätzlich zu meinen Waffengeschäften, die ich hier verfolge, versuche ich, hier in Kraulsumpf ein wenig Unterhaltung aufleben zu lassen. Anscheinend gibt es ein paar dieser Makruradinger in den nördlichen Gewässern, denen unsere wilden Strandpartys nicht in den Kram passen.\n\nJetzt sind sie die Angeschmierten. Ich lasse mich doch nicht von riesigen Hummern herumschubsen - sie werden meine nächste Einkommensquelle sein! Bringt mir einige ihrer Schwänze und wir schlagen aus dem Problem unseren Profit.", sourceObjective = "Besorgt 6 intakte Makruraschwänze von Sumpfstrandmakruras.", progress = "Habt Ihr die Schwänze? Versucht nicht, mir kaputte anzudrehen!", completion = "Ich sehe es schon vor mir: unsere eigenen, berühmten Kraulsumpfer Hummercracker! Frisch aus dem Meer! Oh, es ist, als ob sich das von ganz alleine schreibt...\n\nIch weiß Eure Hilfe sehr zu schätzen, mein Freund. Ich werde sehen, ob ich für Eure Leute besonders günstige Konditionen machen kann, ok?", sourceObjectiveStatus = "unverified-source-field" }
quests[27588] = { id = 27588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehlt den Angriff", description = "Jetzt, da Ihr Schädelbrecher den Berg vom Schattentor weggelockt habt, müsst Ihr unseren Truppen signalisieren, dass sie angreifen können!", sourceObjective = "Benutzt das Angriffssignal auf einem der Türme beim Schattentor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27589] = { id = 27589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Grimmige Säufer", description = "Jeder im \"Grimmigen Säufer\" ist vollkommen betrunken und deshalb leicht zu verärgern. Ich glaube, wir können die Dunkeleisenzwerge ernsthaft behindern, indem wir hier ein wenig Chaos stiften.\n\nIhr müsst einen Streit mit drei der berüchtigten Stammkunden vom Zaun brechen. Beschädigt die Fässer und Hurley Pestatem wird herbeieilen. Stehlt die Gegenstände vom Tisch in der Nähe von Stöpsel Zapfring und er wird kämpfen. Was Ribbly Schraubstutz angeht - mit dem Hitzkopf müsst Ihr nur reden. Meldet Euch bei Donnerherz, wenn Ihr fertig seid.", sourceObjective = "Findet Hurley Pestatem, Stöpsel Zapfring und Ribbly Schraubstutz.", completion = "Ich höre ziemlichen Tumult im \"Grimimgen Säufer\". Wie ich sehe, habt Ihr schwer gearbeitet.\n\nWenn Ihr jetzt Eure Aufmerksamkeit auf die mir gegenüberliegende Seite richtet, werdet Ihr bemerken, dass wir uns um wichtigere Dinge sorgen müssen, als mit Betrunkenen Spielchen zu spielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27590] = { id = 27590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehlt den Angriff", description = "Jetzt, da Ihr Schädelbrecher den Berg vom Schattentor weggelockt habt, müsst Ihr unseren Truppen signalisieren, dass sie angreifen können!", sourceObjective = "Benutzt das Angriffssignal auf einem der Türme beim Schattentor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27591] = { id = 27591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pakt mit den Dunkeleisenzwergen", description = "In dieser Kammer liegt Botschafter Flammenschlag. Er ist der Botschafter von Ragnaros dem Feuerlord und vertritt ihn beim Volk der Dunkeleisenzwerge. Jenseits dieser Kammer befindet sich die Gruft der Beschwörer, Heimat der Geister der sieben Patriarchen der Dunkeleisenzwerge, die Ragnaros in unsere Welt gerufen haben.\n\nMöglicherweise habt Ihr noch nichts von dem großen Feuer gehört, aber er bedeutet das Ende für Azeroth, wenn er nicht aufgehalten wird. Diese Individuen stehen in direkter Verbindung zu der Macht, die er über die Dunkeleisenzwerge hat. Tötet sie alle und möge die unheilige Vereinigung enden.", sourceObjective = "Tötet Botschafter Flammenschlag und Un'rel.", completion = "Ich kann alleine nicht weitermachen, egal, wie viel Kampferfahrung ich habe. Das Lyzeum hat sich als zu schwer für mich erwiesen. Doch da Ihr hier seid... Ihr könntet der Schlüssel zu all dem hier sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27592] = { id = 27592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getränke \"on the rocks\"", description = "Was geht, \"Bruder\"? Wir waren grad mitten in einer krass-spontanen Strandparty, als etwas Furchtbares passierte, \"Alter\"!\n\nIch hatte eine ganze Kiste Silberschnappirinha, das bevorzugte Getränk des Barons, bis die Schlickkriecher ihn gestohlen haben! Ich habe noch nie gesehen, dass Kriecher trinken, aber sie haben alles mit ins Wasser am Strand genommen! Wir brauchen irgendeinen großartigen Helden, der uns helfen kann, unser mit Schutzmarke versehenes Lieblingsgetränk wiederzubeschaffen.\n\n<Brono starrt Euch einen Moment lang an.>\n\nDamit meine ich Euch, \"Kumpel\"!", sourceObjective = "Sammelt 10 Flaschen gestohlenen Silberschnappirinha von Schlickkriechern ein.", progress = "Habt Ihr die Ware, \"Bruder\"?", completion = "Unser eiskalter, erfrischender Silberschnappirinha! Ich kann Euch für diese vollkommen spontane Heldentat gar nicht genug danken, \"Kumpel\"! \n\nHier habt Ihr Eure eigene Flasche als total aufrichtiges Zeichen unserer Dankbarkeit! Jetzt müsst Ihr nur noch ALL EUREN FREUNDEN sagen, wie gut er schmeckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27593] = { id = 27593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wiedergeburt des KEK", description = "Imperator Dagran Thaurissan hat die volle Kontrolle über die Stadt von seinem Thron aus, der vor uns liegt. Wenn wir seine Armeen aufhalten wollen, müssen wir die Herrschaft ihres Gebieters beenden.\n\nUm zu ihm vorzudringen, werdet Ihr seine persönliche Leibgarde überwinden müssen, einschließlich des Riesen Magmus. Bewegt Euch so schnell wie möglich - sollte jemand Alarm schlagen, bevor Ihr fertig seid, wird die gesamte Stadt zu seinem Thron strömen.\n\nDenkt auch daran, dass die Tore am anderen Ende des Lyzeums sich nur öffnen werden, wenn Ihr die Kohlenpfannen mit Fackeln von den Flammenbewahrern entzündet habt. Viel Glück.", sourceObjective = "Tötet Imperator Dagran Thaurissan.", completion = "Ihr seid ein {class}, wie er im Buche steht! Ihr habt das Unmögliche vollbracht! Ich wusste, dass wir uns auf Euch verlassen können.\n\n\n\nUnd damit möchte ich Euch als Erstem bekanntgeben, dass das Expeditionskorps von Kargath offiziell wieder im Geschäft ist!\n\nIch entbiete Euch meine persönliche Dankbarkeit für Eure Bemühungen hier. Denkt immer an unser Motto: \"Die ersten drin, die letzten draußen und immer siegreich. Vergesst niemals Kargath.\"\n\nIhr dürft wegtreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27594] = { id = 27594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Geheimdienst Ihrer Majestät", description = "Lorna Crowley, Tochter von Lord Darius Crowley, befindet sich momentan im vorderen Basislager der Gilnearischen Befreiungsfront, in der Nähe des Graumähnenwalls im Südosten.\n\nUnsere oberste Priorität ist es, jemanden in das Lager einzuschleusen und sie lebend zu fangen. Die Dunkle Fürstin glaubt, dass sie Lorna als Druckmittel gegen Crowley einsetzen kann. Ich sage, wir töten sie einfach und bringen sie als eine Verlassene zurück, doch wir müssen uns den Befehlen der Dunklen Fürstin beugen.\n\nWir müssen uns beeilen, bevor der Rest der Allianzstreitkräfte eintrifft.", sourceObjective = "Nehmt Kommandantin Lorna Crowley gefangen und bringt sie zu Fürstin Sylvanas Windläufer an der Frontlinie der Verlassenen im Silberwald.", completion = "Ihr habt es geschafft! Endlich fügt sich alles zusammen. Wenn Crowley unsere Bedingungen nicht akzeptiert, wird seine Tochter umgewandelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27595] = { id = 27595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Prophet Hadassi", description = "Prophet Hadassi ist das weiseste und älteste Mitglied des Orsisstammes.\n\nWir wissen nicht, wo er sich aufhält, und sein Wohlergehen ist von immenser Bedeutung.\n\nGeht nach Orsis und findet ihn. Sollte er verletzt worden sein, wird ein großer Tag der Abrechnung über die Lakaien von Al'Akir kommen.", sourceObjective = "Findet den Propheten Hadassi in Orsis.", completion = "Wer... wer seid Ihr? Hierher geschickt... um mein Volk zu retten und unsere Feinde zu bekämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27596] = { id = 27596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Berges", description = "Schon seit Jahren suche ich einen ganz bestimmten Edelstein. Er wird das 'Herz des Berges' genannt und ist so groß wie Eure Faust! Die Dunkeleisenzwerge haben den Stein in ihrem Gewölbe weggeschlossen und ich kann machen, was ich will, sie wollen ihn mir einfach nicht verkaufen!\n\nAlso muss ich Gewalt anwenden.\n\nKämpft Euch zum Schwarzen Gewölbe in der Nähe der Halle des Handwerks durch, brecht in den geheimen Safe dort ein und holt Euch das Herz. Dazu müsst Ihr den Wachmann Stahlgriff besiegen, aber der taucht erst auf, wenn Ihr jeden Reliktkasten im Gewölbe geöffnet habt!\n\nViel Glück.", sourceObjective = "Besorgt Euch das Herz des Berges.", progress = "Habt Ihr das 'Herz des Berges'? Für mich ist der Edelstein unendlich wertvoll.", completion = "Ihr habt das Herz! Erstaunlich! Es ist sogar noch schöner, als ich es mir vorgestellt hatte!\n\nBitte, {name}, nehmt dies als Bezahlung an!", sourceObjectiveStatus = "unverified-source-field" }
quests[27597] = { id = 27597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verrückte Larry", description = "Ihr habt es begriffen, {name}. Eine Hand wäscht die andere. Um genau zu sein, wasche ich die Hände Eurer ganzen Armee, und zwar ein bisschen besser als die Hand der anderen Seite! War das zu kompliziert?\n\nIch meine damit, dass das eine Menge Hände sind. Deshalb muss ich Euch bitten, meine Hand noch ein paar Mal zu waschen. Der Dieb dieser Landminen hat wahrscheinlich gerade unsere Jungs am Ostufer erwischt.\n\nMacht Euch zu unserem Lager im Südosten auf und sprecht mit dem verrückten Larry. Er wird Euch alles erklären.", sourceObjective = "Findet den verrückten Larry südöstlich von Kraulsumpf.", completion = "Silberschnapp schickt Euch?! Ich bin ERLEDIGT!\n\nOh... er hat Euch geschickt, um mir zu helfen! Das ist was anderes, haha!", sourceObjectiveStatus = "unverified-source-field" }
quests[27598] = { id = 27598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Gil", description = "Gilblins!\n\n<Larry starrt Euch eine Weile schweigend an.>\n\nIhr habt noch nie einen Gilblin gesehen? Sie sind verrückt! Noch verrückter als ich! Ich jage Dinge für meinen Lebensunterhalt in die Luft, aber diese Dinger sind DURCHGEKNALLT!\n\nIch habe keine Ahnung, wo sie hergekommen sind, aber sie sind wie schreckliche Fischgoblins! Mit Kiemen und allem Drum und Dran! Sie haben all meine Leute unten am Strand getötet und dann haben sie unseren Schiffsfrachter ausgeschaltet.\n\nIhr müsst helfen! Sie sind genau im Osten. Geht und schafft mir diese Gilblins vom Hals!", sourceObjective = "Tötet 7 Pirscher der Gilblins.", completion = "Das wird diesen fischgesichtigen Missgeburten eine Lehre sein! Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27599] = { id = 27599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Hemd hat keine Taschen", description = "Alle Besatzungsmitglieder, die Ihr nicht in diesem Lager seht, sind TOT! Das waren wirklich gute Goblins, aber das Schlimmste ist, dass sie immer noch dort draußen sind! Das ist eine TRAGÖDIE!\n\nIch meine, es ist eine Tragödie, dass sie immer noch ihren ganzen Besitz haben! Schrecklich, wenn man an all die guten Materialien und Münzen denkt, die dort draußen im Wasser liegen.\n\nHey! Ihr könntet mir einen Gefallen erweisen! Wenn Ihr dort draußen Gilblins tötet, könntet Ihr die Kulturbeutel meiner ehemaligen Besatzungsmitglieder mitbringen!\n\nKommt schon, die brauchen sie doch nicht mehr! Mal ehrlich!", sourceObjective = "Beschafft 6 Kulturbeutel von toten Freibeutern von Kraulsumpf.", progress = "Habt Ihr die Kulturbeutel? Hoffentlich habt Ihr die Goblins da gelassen!", completion = "Wow!\n\nIch weiß nicht, warum ich das gesagt habe. Ich bin leicht zu begeistern! Aber seht nur, wie viel Zeug diese Jungs bei sich hatten!\n\nHier, wollt Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[27600] = { id = 27600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knall auf Fall", description = "Unsere Handelsfregatte ist immer noch ziemlich weit draußen auf dem Wasser umschwärmt von Gilblins! AHH!\n\nTut mir leid. Aber mal im Ernst! Wir müssen einen Weg finden, wie wir Euch dorthin befördern und unsere Sachen wiederbekommen. Auf dem Schiff befinden sich Qualitätswaren! QUALITÄT! SO WIE MEIN ZWEITER VORNAME!\n\nZu Eurem Glück habe ich eine Idee! Geht aus dem Camp hinaus und an der Nordwand entlang... Mein Sohn Jerry wird Euch mit unserer Kanone dorthinbefördern. Vorausgesetzt, er hat geübt!", sourceObjective = "Sprecht mit dem verrückte Jerrylein, um das Schiff zu entern. Besorgt danach die drei wertvollen Waren des verrückten Larry.", progress = "Habt Ihr sie? Habt Ihr sie bekommen? Habt Ihr die Kanone ausprobiert? Ihr seid nicht explodiert!", completion = "Meine hochwertige Lunte! Mein importiertes Sprengpulver!\n\nUnd mein... ja, hallo erstmal! Ich brauche nur das!\n\nDas alles ist mehr wert, als alles Gold, das Ihr bei Euch tragt! Danke für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[27601] = { id = 27601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Städte im Staub", description = "Unsere Armeen treffen überall auf dem Schlachtfeld aufeinander. Crowley und seine Streitkräfte verlieren an Boden und wissen bisher noch nichts über das Schicksal von Lorna Crowley. Wir treffen uns mit Crowley und seinen Landsleuten in der Mitte des Feldes und ich werde ihnen die Bedingungen für ihre Kapitulation unterbreiten. Entweder, sie akzeptieren diese, oder wir werden sie alle töten und ihre Städte im Staub hinterlassen.\n\nDa Ihr mein vertrautester Soldat seid, möchte ich, dass Ihr während des Austauschs an meiner Seite steht. Sagt mir, wenn Ihr bereit seid, aufzubrechen.", sourceObjective = "Begleitet Fürstin Sylvanas Windläufer auf das Schlachtfeld und besiegt die Allianz!", completion = "<Fürstin Sylvanas Windläufer verzerrt schmerzerfüllt das Gesicht.>\n\nEs... ist noch nicht vorbei. Godfrey und seine verräterischen Verbündeten werden dafür bezahlen, was sie hier getan haben, genau wie die verbleibenden Streitkräfte der Allianz, die Lordaeron besetzt halten.\n\nUnsere Arbeit hat gerade erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27602] = { id = 27602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Worte eines sterbenden Propheten", description = "Wir... sind... durch einen Eid... verpflichtet, das Zepter von Orsis zu beschützen.\n\nHört zu, {class}, ich habe nicht mehr... viel Zeit.\n\nFindet das heilige Gefäß... am südlichen Ende der Stadt.\n\nLasst es... nicht in... ihre Hände fallen.", sourceObjective = "Findet das heilige Gefäß.", completion = "Die Kiste selbst ist verschlossen, aber darüber befindet sich eine Plakette mit interessanten Hieroglyphen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27603] = { id = 27603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das versiegelte Tor", description = "Am einen Ende der Dunkeleisenstraße findet Ihr ein massives Tor, ähnlich dem, das auf der gegenüberliegenden Seite die Schattenschmiede schützt. Wir haben jedoch keine Ahnung, was sich dahinter befindet!\n\nWir wissen nur, dass es von Patrouillen der Zorneshämmer und dem geschmolzenen Riesen Bael'gar schwer bewacht wird. Ihr müsst sie einfach nur beseitigen und schauen, ob Ihr das Tor öffnen könnt.\n\nStellt Euch nur vor, was dahinter liegen mag... Es könnte eine komplette zweite Hälfte der Stadt geben, von der wir bis jetzt noch keine Ahnung hatten! Oder nichts! Wer weiß das schon?\n\nAber da ist sicher etwas...", sourceObjective = "Tötet Bael'gar.", completion = "Verdammt! Ich MUSS einfach wissen, was hinter diesem Tor liegt! Das könnte die Entdeckung sein, die meine Karriere ins Rollen bringt. Versteht Ihr?\n\nHmm… Vielleicht können ein paar strategisch platzierte Explosionen das Problem ja lösen…", sourceObjectiveStatus = "unverified-source-field" }
quests[27604] = { id = 27604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jammal'an der Prophet", description = "Jammal'an der Prophet, Anführer der Atal'ai- und Hakkaritrolle, hat eine kleine Menge Blut von Hakkar dem Seelenschinder an sich gebracht. Jetzt verabreichen sie es grünen Drachen, damit deren Körper riesige Mengen des Bluts produzieren, das notwendig ist, um Hakkar in unsere Welt zu rufen.\n\nDas können wir nicht zulassen Tötet Jammal'an und seine Priester, bevor sie noch weitere Fortschritte machen.", sourceObjective = "Erbeutet den Kopf von Jammal'an dem Propheten.", progress = "Habt Ihr Jammal'an getötet? Ich brauche einen Beweis, dass die Tat vollbracht ist.", completion = "Ausgezeichnet! Ich nehme an, dass die Trolle sich ohne Jammal'ans Führung gegenseitig bekämpfen werden. Hakkar wird diese Welt nie erblicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27605] = { id = 27605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eranikus", description = "Das Hakkarblut, das die Atal'ai den grünen Drachen verabreicht haben, hatte verheerende Auswirkungen auf die Drachen. Offenbar hat seine Anwesenheit in ihren Körpern die Drachen, die früher Gefangenenwärter der Atal'ai waren, verdorben und in Alptraumkreaturen verwandelt.\n\nEranikus, Yseras erstem Berater und Oberaufseher über den Tempel, wurden die größten Mengen des Blutes verabreicht. Das hat ihn jenseits aller Vorstellungskraft verändert. Wenn Jammal'an tot ist, sucht Eranikus und bereitet ihm ein Ende.", sourceObjective = "Tötet Eranikus.", completion = "Ihr habt nur Eranikus' Schemen besiegt? Das ist äußerst beunruhigend...\n\nHoffen wir, dass seine wahre Gestalt nicht noch außerhalb des Tempels existiert. Nur Ysera persönlich ist stärker als er.", sourceObjectiveStatus = "unverified-source-field" }
quests[27606] = { id = 27606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt ihn in die Luft!", description = "Lasst uns ein paar Fische fangen, {name}! Jetzt, da die Mörser bereit sind, können wir den Anführer dieser Invasion vernichten.\n\nTiefenlord Heth'Jatar ist der Kopf der Kriegerkaste der Schwarzschuppen. Geht zu den Bannern der Heth'Jatari nordöstlich von hier und blast in dieses Muschelhorn. Es funktioniert wie eine Hundepfeife, nur für Fische.\n\nWenn Heth'Jatar sich zeigt, werde ich den Mörserschützen befehlen, das Feuer zu eröffnen. Ihr werdet sehen, wo die Granaten einschlagen werden.\n\nLockt Heth'Jatar in unser Mörserfeuer und prügelt solange auf ihn ein, bis er aufgibt.", sourceObjective = "Blast in der Nähe eines Banners der Heth'Jatari in das Muschelhorn. Tötet Tiefenlord Heth'Jatar. Es wird einfacher, wenn Ihr ihn in das Mörserfeuer lockt.", completion = "Kabumm!\n\nWas? Ihr habt den Tiefenlord schon erschlagen?\n\nNun, dann brauchen wir wohl nicht weiter auf seine Leiche schießen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27607] = { id = 27607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die südliche Flanke", description = "Unsere neue Vereinbarung mit der Horde stürzt mein Volk in einen direkten Konflikt mit der Allianz.\n\nDann sollen sie mal kommen!\n\nIn diesem Augenblick rückt die Allianz auf der Halbinsel vor, um den Hafen des Drachenmals zu bedrängen.\n\nSucht im Süden nach Rok'tar und stellt sicher, dass das Zwielichtufer in unserer Hand bleibt. Ich glaube, Rok'tar hat einen Gefechtsstand auf einem der Schiffswracks errichtet.", sourceObjective = "Sprecht mit Rok'tar am Zwielichtufer im Schattenhochland.", completion = "Ihr kommt genau rechtzeitig, {class}. Wir sind gerade dabei, einen Gegenangriff zu starten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27608] = { id = 27608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vier Köpfe sind besser als keiner", description = "Wir werden gleich den Angriff auf die Tore der Zitadelle starten, doch es gibt noch eine Sache, um die Ihr Euch kümmern müsst: Za'brox und Beeble'phod, die Jünger Cho'galls.\n\nLaut den Geheiminformationen halten sie sich im Schlupfwinkel der Jünger auf, einer kleinen Ogerhöhle am südwestlichen Ende des Schattentors.\n\nWürdet Ihr nochmals losziehen und sie töten?", sourceObjective = "Sammelt die vier Köpfe von Za'brox und Beeble'phod.", sourceObjectiveStatus = "unverified-source-field" }
quests[27609] = { id = 27609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vier Köpfe sind besser als keiner", description = "Wir werden gleich den Angriff auf die Tore der Zitadelle starten, doch es gibt noch eine Sache, um die Ihr Euch kümmern müsst: Za'brox und Beeble'phod, die Jünger Cho'galls.\n\nLaut den Geheiminformationen halten sie sich im Schlupfwinkel der Jünger auf, einer kleinen Ogerhöhle am südwestlichen Ende des Schattentors.\n\nGeht bitte zurück und tötet sie.", sourceObjective = "Sammelt die vier Köpfe von Za'brox und Beeble'phod.", sourceObjectiveStatus = "unverified-source-field" }
quests[27610] = { id = 27610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späht den Strand aus", description = "Wenn die Allianz die Kontrolle über diese Halbinsel erlangt, gerät der Hafen des Drachenmals in Gefahr. Das lasse ich nicht zu.\n\nSüdlich von hier findet Ihr einen kleinen Hügel, von dem aus man einen beeindruckenden Ausblick auf die Küstenlinie hat. Wer diesen Hügel kontrolliert, hat auch die Oberhand über die gesamte Küste.\n\nEilt schnell dorthin und späht den Brückenkopfkontrollpunkt aus. Er ist mit einer riesigen Flagge markiert. Kehrt dann zu mir zurück.\n\nIhr müsst ihn nicht einnehmen, es sei denn, Ihr seid auf einem Kampf mit der Allianz aus.", sourceObjective = "Späht den Brückenkopfkontrollpunkt am Zwielichtufer aus. Ihr müsst ihn nicht einnehmen, doch wenn Ihr dies tut, erhält Eure Fraktion einen Vorteil im Kampf und Ihr werdet für den PvP-Kampf markiert.", completion = "Gute Arbeit, {class}. Jetzt kennt Ihr die Lage des Landes.\n\nWenn Ihr je Probleme im Kampf hier am Zwielichtufer habt, dann vergesst nicht, dass alle Streitkräfte der Horde einen Kampfvorteil erhalten, wenn der Brückenkopf unter unserer Kontrolle steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27611] = { id = 27611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutgetränkter Sand", description = "Unser Ziel im Schattenhochland ist, die Bastion des Zwielichts zu stürmen, aber die Allianz hat sich entschlossen, einen Krieg anzuzetteln.\n\nAlso sollen sie ihren Krieg haben!\n\nTötet ihre Marinesoldaten, bis sie ihre Lektion gelernt haben.", sourceObjective = "Tötet 12 Marinesoldaten am Zwielichtufer im Schattenhochland.", completion = "Gut, gut. Wer Wind sät, soll Sturm ernten!", sourceObjectiveStatus = "unverified-source-field" }
quests[27612] = { id = 27612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg im Inneren", description = "Ein paar unserer Männer haben es nicht durch die Portale geschafft, die sich in dieser Abtei hätten öffnen sollen. Ihr habt bereits bewiesen, dass Ihr ebenso gut ausweichen wie kämpfen könnt... das müsst Ihr noch einmal zeigen.\n\nDie Abtei hat zwei Flügel: eine Bibliothek und eine Halle der Waffen. In beiden Flügeln sollte es ein Portal geben.\n\nSetzt den Schlüsselstein bei diesen Portalen ein. Der Stein sollte ihre Öffnung erzwingen. Dann können unsere restlichen Stoßtruppsoldaten die Abtei einnehmen.", sourceObjective = "Öffnet die Argentumportale im Bibliotheksflügel und der Halle der Waffen in der Abtei in Tyrs Hand.", progress = "Einhundert Soldaten sind schon recht wenig. Solche Rückschläge reduzieren unsere Siegeschancen.", completion = "Die Abtei wird in Kürze fallen. Wir können bald tiefer in Tyrs Hand eindringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27613] = { id = 27613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Assassine", description = "Das Schicksal des Scharlachroten Kreuzzugs ist tragisch, aber nicht ohne Ironie. Einst waren sie die Speerspitze der Menschheit im Kampf gegen die Untoten. Jetzt sehen sie aus wie die Leichen, die sie früher jagten. Es ist unklar, was sie in den Untod getrieben hat, aber das macht sie nicht weniger gefährlich.\n\nEiner ihrer tödlichsten Kämpfer war ein Assassine, der sich Rohan nannte. Laut unseren Informationen hält er sich genau in dieser Abtei ganz oben im Glockenturm auf. Findet und tötet ihn, {name}. Und versucht, dabei nicht zu sterben.", sourceObjective = "Tötet Rohan den Assassinen im Glockenturm der Abtei in Tyrs Hand.", completion = "Rohans Tod erleichtert mich ein wenig.\n\nWisst Ihr, dass ich früher mit ihm gekämpft habe? Vor vielen Jahren war er ein Abgesandter des Scharlachroten Kreuzzugs, einer der wenigen, die uns in der Schlacht gegen Kel'Thuzad zur Seite standen. Wie schnell sich alles ändert.", sourceObjectiveStatus = "unverified-source-field" }
quests[27614] = { id = 27614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharlachrote Bergung", description = "Diese Schlacht war schon gewonnen, bevor sie begann. Jetzt verbessern wir nur noch unsere B-Note.\n\nDie wimmernden Scharlachroten Kreuzfahrer klammern sich in ihren Kasernen an ihre unbezahlbaren Artefakte, obwohl manche so heilig sind, dass ihre jetzt untoten Hände sie nicht mehr berühren können. Also werden sie in Truhen aufbewahrt und vor der Welt versteckt.\n\nFindet diese Artefakte und bringt sie mir zurück. Ihr Platz ist beim Argentumkreuzzug. Sie gehören in die Hände der Rechtschaffenen.", sourceObjective = "Erbeutet den Purpureber, Lihannas Strang, das Tuch des Uther und Gavinrads Siegel.", progress = "Ich hoffe, es war ein guter Kampf.", completion = "Hervorragend, {name}. Ich werde sie nach unserer Rückkehr Tyrosus übergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27615] = { id = 27615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zornwirker", description = "Im Kerker der Kaserne lauert ein äußerst übler Zeitgenosse des Scharlachroten Kreuzzugs, Mataus der Zornwirker. Der Untod passt zu seinem düsteren Gehabe.\n\nWäre ich noch jünger und an der Front, würde ich ihn selbst aufspießen. Doch leider muss ich unsere Streitkräfte von hinten anführen. Deshalb überlasse ich Euch dieses Vergnügen.", sourceObjective = "Tötet Mataus den Zornwirker.", completion = "Ihr seid auf dem besten Weg, ein wahrer Champion des Lichts zu werden, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27616] = { id = 27616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Jäger", description = "Die Kugeln und Pfeile, die uns oben aus dieser Festung entgegenschießen, haben schon ein halbes Dutzend Männer das Leben gekostet. Ich kenne das Gesicht des Feindes, der auf uns schießt nicht, doch das ist auch nicht nötig. Ich kenne den Namen des Mannes, der dort oben hockt.\n\nLeopold.\n\nEs ist wirklich nur ein einziger Mann, der von dort oben meine Männer nacheinander umbringt. Und so wie ich das sehe, gibt es auch nur <einen/eine> von Euch.\n\nKlingt nach einem fairen Kampf.", sourceObjective = "Tötet Jäger Leopold.", completion = "Eine Sorge weniger. Gute Arbeit da oben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27617] = { id = 27617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entdorben", description = "Spürt Ihr es? Die Verderbnis löst sich bereits von diesem Gebäude.\n\nEin heiliges Gebäude will heilig sein. Übeltäter wie Rohan und seine Scharlachroten Kumpane hindern es jedoch daran.\n\nDie Abtei ist gesichert. Die Eroberung von Tyrs Hand ist einen Schritt näher gerückt. Meldet Angela das Ergebnis unseres Schlags. Sie führt den Angriff auf die Kathedrale irgendwo aus der Stadtmitte an.", sourceObjective = "Meldet Euch bei Erzmagierin Angela Dosantos in Tyrs Hand in den Östlichen Pestländern.", completion = "Gut, die Abtei ist unser. Ich habe keinen Moment lang an Eligors Fähigkeiten gezweifelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27618] = { id = 27618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argentumaufstand", description = "Wir haben dieser Kaserne so viel Schaden zugefügt, dass man von einem Sieg sprechen kann. Eine Kommandantin, ein Jäger und ein Hexenmeister getötet... Und die ganzen Relikte, die wir geborgen haben. Oder sollte ich sagen... Die IHR geborgen habt.\n\nDie Kathedrale wird als Nächstes fallen. Sprecht mit Erzmagierin Angela Dosantos im Hauptinnenhof. Das Schicksal der Kathedrale von Tyrs Hand liegt in ihren fähigen Händen.", sourceObjective = "Meldet Euch bei Erzmagierin Angela Dosantos in Tyrs Hand in den Östlichen Pestländern.", completion = "Korfax hat wohl in der Kaserne richtig aufgeräumt. So eine Angeberei passt zu ihm.", sourceObjectiveStatus = "unverified-source-field" }
quests[27619] = { id = 27619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kommandantin", description = "Die Scharlachrote Kommandantin Marjhan ist listig, gewieft und bereit, alles für einen Sieg zu tun. Doch das Wichtigste ist ihre unerschütterliche Loyalität.\n\nIhr werdet sie zweifellos in der Hauptkammer der Kaserne finden. Dort wird sie unter einem scharlachroten Banner kämpfen, bis sie entweder siegt oder stirbt.\n\nSorgt dafür, dass Letzteres eintritt.", sourceObjective = "Tötet die Scharlachrote Kommandantin Marjhan.", completion = "Gut, gut. Die Kaserne ist so gut wie erobert.", sourceObjectiveStatus = "unverified-source-field" }
quests[27620] = { id = 27620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie Ratten", description = "Es freut mich, dass Eligor und Korfax mir ein wenig Spaß übrig gelassen haben. Es war nicht leicht, sie davon abzuhalten, Hals über Kopf in diese Kathedrale zu stürmen.\n\nAber das ist schließlich EURE Aufgabe.\n\nDie Kathedrale liegt vor uns. Sie ist die letzte Bastion der Scharlachroten Macht. Kreuzfahrerlord Valdelmar hockt darin auf dem klapprigen Lügengerüst von Tyrs Hand.\n\nEs darf keine Flucht geben und keine Gnade. Der erbärmliche Rest des Scharlachroten Kreuzzugs wird hier sein Ende finden. Tötet ihn.", sourceObjective = "Tötet Kreuzfahrerlord Valdelmar.", completion = "Obwohl ich mit ihren Methoden nicht einverstanden bin, sprechen ihre Resultate für sich. Der Scharlachrote Kreuzzug meinte es eigentlich gut, aber ihr Eifer wurde zu groß und ihr Hass raubte ihnen den Verstand.\n\nIch hoffe inständig, dass dies unserer Bruderschaft des Lichts nie zustoßen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[27621] = { id = 27621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerbarts Patrouille", description = "Ich war auf dem Weg, um mich Feuerbarts Patrouille anzuschließen, als mein Vogel abgeschossen wurde.\n\nDer Schattenhammer hat überall im Hochland Überraschungsangriffe durchgeführt. Manchmal erschienen ihre Gebäude einfach so aus dem Nichts aus dem Boden, mitten in unseren Dörfern. Es war ein echter Alptraum!\n\nIn dem Chaos war Feuerbart einer der wenigen, die einen kühlen Kopf bewahrten. Er versucht, ein vollständiges Greifenreitergeschwader aus den Überlebenden zusammenzustellen.\n\nWenn Ihr wollt, dass die Wildhämmer sich der Allianz anschließen, solltet Ihr zunächst Feuerbart im Westen helfen.", sourceObjective = "Sucht nach Keegan Feuerbart bei Feuerbarts Patrouille im Schattenhochland.", completion = "Seid Ihr hier, um Euch der Patrouille anzuschließen, Bursche? Ich nehme Euch mit Freuden auf.\n\nIch brauche ein paar fähige Recken, um unsere Verteidigung hier unter Kontrolle zu kriegen. Helft mir und ich werde zusehen, dass ich eine etwas glanzvollere Arbeit für Euch finde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27622] = { id = 27622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netter Schredder", description = "{name}, ich habe Pläne für einen verbesserten Schredder, aber meine Ingenieure können nicht einfach so alleine in ein Kampfgebiet spazieren.\n\nGeht und findet einen bergungsfähigen Schredder am Zwielichtufer und benutzt ihn, um einen meiner Bergungsexperten herbeizurufen. Verteidigt den Schredder, bis wir ein paar \"Aktualisierungen\" daran vorgenommen haben.\n\nDie Allianz wird gar nicht wissen, wie ihr geschieht! Zumindest nicht, bis meine Marketingkampagne angelaufen ist!", sourceObjective = "Findet einen bergungsfähigen Schredder am Zwielichtufer und benutzt ihn, um einen Bergungsexperten aus Bilgewasser herbeizurufen. Verteidigt den Schredder, bis er wieder funktionstüchtig ist.", completion = "So mag ich das! Genau so! Kalter Stahl und heißer Tod!\n\nWelchen Namen sollten wir unserer neuen Schöpfung geben? Der Gnugatron? Nein, viel besser: der {name}-o-Matik! Das hat einen guten Klang.", sourceObjectiveStatus = "unverified-source-field" }
quests[27623] = { id = 27623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kolossale Wächter", description = "Die Kiste, die das Zepter enthält, scheint magisch versiegelt zu sein und ist nicht zum Nachgeben zu bewegen.\n\nDie Plakette darüber zeigt zwei riesige Statuen, in deren Mitte sich Vertiefungen befinden, in die jeweils ein mond- und ein sternförmiger Stein passen.\n\nDie Abbildung der Statuen zeigt, wie sie Pyramiden bewachen, die so wie diejenigen aussehen, die sich draußen befinden.\n\nVielleicht würde es sich lohnen, diese zu untersuchen.", sourceObjective = "Beschafft Euch den Stein des Mondes und den Stein der Sonne von den kolossalen Wächtern.", progress = "Ihr wischt den Sand von den Hieroglyphen, aber sie werden sofort von einer neuen Schicht überzogen. Ihr solltet Euch lieber beeilen.", completion = "Ihr platziert die beiden Edelsteine in die Vertiefungen an der Wand.", sourceObjectiveStatus = "unverified-source-field" }
quests[27624] = { id = 27624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach dem Fall", description = "Och, das war nichts weiter.\n\nDiese Statuen waren ohnehin wackelig - sie brauchten nur einen kleinen Schubs.\n\nWie wäre es, wenn Ihr geht und die Trümmer durchsucht?\n\nIch habe das Gefühl, als ob wir kurz davor stehen, das Rätsel zu lösen.", sourceObjective = "Sammelt die Kugel des Morgensterns, die Kugel des Abendsterns, die Kugel des Nordsterns und die Kugel der Sternschnuppe ein.", progress = "Habt Ihr etwas Interessantes gefunden, {name}?", completion = "Gute Arbeit, {name}.\n\n\n\nSieht so aus, als ob unsere Arbeit hier fast erledigt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27625] = { id = 27625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Verteidigung von Quel'Danil", description = "Die Untoten sind hier! Die Verlassenen! Sie kamen immer näher und näher, aber aufs Ganze gehen und uns angreifen... Diese entsetzlichen Monstrositäten!\n\nDie jungen Draenei, die man mir anvertraut hat, haben mit den Hochtalelfen im Kampf trainiert. Sie sind nicht schutzlos, aber sie brauchen Hilfe!\n\nBitte, {name}, helft ihnen! Drängt die Verlassenen zurück!", sourceObjective = "Tötet 16 Eindringlinge der Todespirscher an der Jagdhütte Quel'Danil.", completion = "Derartige Verirrung im Angesicht des Lichts... Ihr seid mutig, Euch ihnen entgegenzustellen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27626] = { id = 27626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hochtalaufzeichnungen", description = "Die Hochtalelfen haben seit Jahren hier detaillierte Aufzeichnungen aufbewahrt. Todesfälle, Geburten, Jahreszeiten... aber auch wichtige Informationen von Spähern und Methoden, wie man mit dem Rest der Allianz Verbindung aufnehmen kann.\n\nDiese Aufzeichnungen werden in dem Chaos verstreut werden. Wenn sie in die Hände der Verlassenen fallen, könnten noch mehr Leben auf dem Spiel stehen! Bitte, Ihr müsst die Aufzeichnungen finden, bevor sie der Horde in die Hände fallen.", sourceObjective = "Findet den Hochtalbericht, die Hochtalaufzeichnungen und die Hochtalnotizen.", progress = "Sind sie in Sicherheit?", completion = "Dem Licht sei Dank! Wir werden den Verlassenen nichts überlassen, das gegen uns verwendet werden kann, egal, wie wenig es sein mag.", sourceObjectiveStatus = "unverified-source-field" }
quests[27627] = { id = 27627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur eine aufgetakelte Kakerlake", description = "Offensichtlich beherbergten die uralten Statuen verschiedene Arten von Skarabäen.\n\nIhr seid entschlossen, diesen Ort in dem bestmöglichen Zustand zu verlassen und beschließt, die Kammer von dieser Plage zu befreien.", sourceObjective = "Tötet 5 Amethystskarabäen, 5 Saphirskarabäen, 5 Türkisskarabäen und 5 Smaragdskarabäen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27628] = { id = 27628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Benachrichtigt Phaoris", description = "Beeilt Euch, {name}. Wir müssen mit meinem Bruder, dem König, sprechen.\n\nEr will unbedingt einen Krieg mit Al'Akir und Neferset verhindern. Er hat die törichte Hoffnung, dass es für dieses Problem eine diplomatische Lösung gibt.\n\nVielleicht kommt er zur Vernunft, wenn er hört, was hier geschehen ist.", sourceObjective = "Sprecht mit König Phaoris in Ramkahen in Uldum.", completion = "Das ist erst der Anfang, {name}. Wenn die Gehilfen von Todesschwinge ganze Städte begraben können, haben wir kaum eine Chance, sie mit normalen Mitteln zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27629] = { id = 27629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Votum des Wesirs", description = "Wesir Tanotep dazu zu bewegen, sich gegen die Wünsche meines Bruders zu stellen, wird äußerst schwierig sein. Seine Stellung beruht darauf, den Willen von Phaoris durchzusetzen.\n\nIch hatte kein Glück damit, für einen offenen Krieg gegen Neferset zu plädieren.\n\nDennoch müsst Ihr mit ihm sprechen. Vielleicht hört er auf die Ansichten eines Außenstehenden.\n\nIhr findet den Wesir auf den Feldern von Akhenet in offizieller Mission.", sourceObjective = "Sprecht mit Wesir Tanotep auf den Feldern von Akhenet in Uldum.", completion = "Was für eine Kreatur seid Ihr? Ihr werdet das Land des Königs verlassen, bevor...\n\nWartet! Ihr seid dieser {name}, über den ich so viel gehört habe.\n\nIhr müsst meine mangelnde Gastfreundschaft entschuldigen. Wir haben hier zu viele feindliche Eindringlinge zu Gesicht bekommen, seit die Barriere um Uldum gefallen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27630] = { id = 27630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Votum des Hohepriesters", description = "Das Votum von Hohepriester Amet ist das Einzige, das sich unserer Kontrolle entzieht.\n\nEr wird so abstimmen, wie seine Weissagungen es ihm vorschreiben und wir können ihn nicht davon abbringen.\n\nIch denke, dadurch sind die Chancen in beide Richtungen ausgeglichen.\n\nDas einzige Problem ist, dass seine Hellseherei ihn, seitdem die Barrieren um Uldum gefallen sind, im Stich lässt.\n\nEr wird nicht abstimmen, solange er nicht wieder die Kontrolle über seine Weissagungen hat.\n\nSteigt eine der Treppen an den Seiten des Vir'naaldamms hinab, sprecht mit ihm und seht, was Ihr tun könnt, um ihm zu helfen.", sourceObjective = "Sprecht mit Hohepriester Amet im Vir'naaldamm in Uldum.", completion = "Krieg, sagt Ihr.\n\nWeissagungen für einen Krieg sind immer schwierig. Einige Kriege dürfen nie ausgetragen werden, auch, wenn der Sieg sicher wäre. Einige Kriege müssen geführt werden, auch wenn die Niederlage sicher ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27631] = { id = 27631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Votum des Hochkommandanten", description = "Wenn wir eine Resolution für Krieg verabschieden sollen, muss der Hohe Rat einstimmig dafür sein.\n\nIch bin sicher, dass Hochkommandant Kamses uns seine Stimme geben wird, wenn er hört, was in Orsis geschehen ist.\n\nBitte sprecht mit ihm in Ramkahen und stellt sicher, dass er Bescheid weiß. Ich muss Vorbereitungen treffen, falls unser Plan erfolglos ist.", sourceObjective = "Sprecht mit Hochkommandant Kamses am Außenposten der Legion von Ramkahen in Uldum.", completion = "Es ist nicht nötig, mich in die Geschehnisse in Orsis einzuweihen, {name}.\n\nIch habe bereits davon gehört. Und von Euch. Jeder Feind von Al'Akir ist mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[27632] = { id = 27632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanoteps Sohn", description = "Ich habe mein Leben in die Dienste des Königs gestellt. Nichts ist so wichtig, wie ihm zu dienen - mit einer Ausnahme: mein Sohn.\n\nTahet wurde von Wachposten von Neferset gefangen genommen.\n\nSie behaupten, dass mein Sohn unbefugt ihr Gebiet betreten hat. Phaoris versucht, seine Freilassung zu verhandeln... doch ich befürchte das Schlimmste.\n\nWenn Ihr Tahet findet, würde ich Euch meine Stimme geben.\n\nIch weiß nicht, wohin sie ihre Gefangenen bringen, aber ich habe gesehen, wie die Wachen auf Karten geschaut haben, die sie durch die dichte Vegetation führen sollten.", sourceObjective = "Besorgt die Karte des Vir'Naaldeltas von einer Wache von Neferset.", progress = "Dies könnte die Karte sein, die Ihr sucht.", completion = "Ihr habt eine Karte des Vir'naaldeltas bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27633] = { id = 27633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blutgott Hakkar", description = "Hakkar... die Bloße Erwähnung des Namens des Seelenschinders schlägt viele in die Flucht. Im Sanktum des Gefallenen Gottes haben die Atal'ai einen großen Teil seines Skeletts geborgen und möchten ihn wieder ins Leben rufen. Seine Kinder haben schon begonnen, im Umkreis aufzutauchen.\n\nLegt dieses Ei im Sanktum ab. Es wird seine Beschwörung früher als geplant erzwingen. {name}, Ihr dürft nicht zögern. Schlagt zu, sobald sein Avatar erscheint!", sourceObjective = "Tötet den Avatar von Hakkar.", progress = "Konntet Ihr Hakkars Avatar zerstören?", completion = "Hier habt Ihr Hakkar erfolgreich aufgehalten, aber ich befürchte, wir sind noch lange nicht fertig. Die Atal'ai haben den Großteil des von ihnen produzierten Blutes nach Zul'Gurub abtransportiert, wo die Hakkari daran arbeiten, den Blutgott dort zu beschwören.\n\nIch glaube nicht, das dies hier jemals der Ort für Hakkars Ankunft sein sollte - es war lediglich ein Test, um zu sehen, ob das Blut stark genug ist! Hakkar kann nur in Zul'Gurub beschworen werden... und ich befürchte, wir kommen zu spät, um die Hakkari aufzuhalten, nun da sie das Blut besitzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27635] = { id = 27635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekontamination", description = "Ihr seid schon sehr lange hier unten in Gnomeregan, {name}, und es ist bemerkenswert, dass Ihr überlebt habt und noch bei Verstand seid! Wir müssen Euch rausholen.\n\nBevor wir Euch zu den anderen Gnomen an die Oberfläche schicken können, müsst Ihr dekontaminiert werden. Begebt Euch in den nächsten Raum und besteigt den Sanitron 500. Er wird den Rest erledigen! Es wird nicht weh tun... nicht sehr.\n\nMeldet Euch bei Techniker Braggel, wenn Ihr fertig seid. Er wird Euch geeignete Ausrüstung besorgen.", sourceObjective = "Besteigt den Sanitron 500 und lasst Euch dekontaminieren.", completion = "So, jetzt könnt Ihr Euch an die Oberfläche begeben und ein neues Leben beginnen. Der Hochtüftler wird begeistert sein, wenn er von Eurer Ankunft erfährt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27636] = { id = 27636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur Ihr und Mathias", description = "Alle Agenten des SI:7 sind tot. Ihr müsst Meister Mathias Shaw finden.\n\nZum Glück hat der Truppenkommandant Euch erzählt, wo er sich aufhält.", sourceObjective = "Findet Meister Mathias Shaw bei der Schattenzitadelle im Schattenhochland.", completion = "Wo ist der Rest meiner Leute?", sourceObjectiveStatus = "unverified-source-field" }
quests[27637] = { id = 27637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur Ihr und Mathias", description = "Das ist ein schwerer Schlag für unsere Bemühungen. Verdammt sei Cho'gall!\n\nZum Glück hat der Truppenkommandant Euch erzählt, wo Meister Mathias Shaw sich aufhält.", sourceObjective = "Findet Meister Mathias Shaw bei der Schattenzitadelle im Schattenhochland.", sourceObjectiveStatus = "unverified-source-field" }
quests[27638] = { id = 27638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur Ihr und Garona", description = "Alle Kor'kron sind tot. Ihr müsst Garona die Halborcin finden.\n\nZum Glück hat der Truppenkommandant Euch erzählt, wo sie sich aufhält.", sourceObjective = "Findet Garona die Halborcin bei der Schattenzitadelle im Schattenhochland.", completion = "Wo sind die Kor'kron?", sourceObjectiveStatus = "unverified-source-field" }
quests[27639] = { id = 27639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur Ihr und Garona", description = "Das ist ein schwerer Schlag für unsere Bemühungen. Verdammt sei Cho'gall!\n\nZum Glück hat der Truppenkommandant Euch erzählt, wo Garona sich aufhält.", sourceObjective = "Findet Garona die Halborcin bei der Schattenzitadelle im Schattenhochland.", sourceObjectiveStatus = "unverified-source-field" }
quests[27640] = { id = 27640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen Dunwalds ist kein Kraut gewachsen", description = "Man hat Euch also beauftragt, die Wildhammerklans für den Krieg zu vereinen. Ein edles Unterfangen, keine Frage, aber ich glaube nicht, dass Ihr wisst, worauf Ihr Euch da eingelassen habt.\n\nDennoch, wenn Ihr Euch auf eine Schlacht vorbereitet, darf eine Familie unter keinen Umständen an Eurer Seite fehlen. Geht nach Südwesten, gegenüber des Schmelztiegels des Gemetzels. Dort findet Ihr die Ruinen des Dunwaldklans. Sie sind zwar ganz schön ramponiert, aber das hält jemanden wie die Dunwalds nicht auf. Der schwierigste Teil dabei wird, sie zu finden.", sourceObjective = "Haltet nach Überlebenden der Familie Dunwald in den Ruinen von Dunwald Ausschau.", completion = "Wenn Ihr nach den Dunwalds sucht, dann habt Ihr sie gefunden. Zumindest einen Teil davon. Meine anderen Brüder kann ich leider nicht finden, so sehr ich es auch versucht habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27641] = { id = 27641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beim Familientreffen", description = "He da, <Bursche/meine Dame>! Sicher hat Keely Euch in Sorge um unsere Brüder gestürzt, aber sie können ganz gut auf sich selbst aufpassen. Sie werden schon irgendwie hierher zurückfinden.\n\nVielleicht könnt Ihr mir einen Gefallen tun, wenn Ihr ohnehin schon zum Familientreffen da draußen seid... Das Gebiet der Dunwalds ist immer noch voll von den Kultisten des Schattenhammers und ihren Dienern. Ich würde es sehr zu schätzen wissen, wenn Ihr sie daran erinnert, dass sie hier nicht willkommen sind.", sourceObjective = "Tötet 20 Mitglieder des Schattenhammers im Gebiet der Dunwalds.", completion = "Ja, genau so habe ich mir das vorgestellt, Bursche. Ein {race} ganz nach meinem Geschmack.", sourceObjectiveStatus = "unverified-source-field" }
quests[27642] = { id = 27642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchsuchung der Trümmer", description = "Als der Schattenhammer unser Dorf gebrandschatzt hat, waren sie ganz schön gründlich. Meine Brüder und ich waren vielleicht die Einzigen, die sie zurückgehalten haben. Ich muss jedoch Gewissheit haben.\n\nWährend Ihr die Ruinen durchsucht, haltet Ausschau nach Leichen meiner Gefolgsleute. Ich muss wissen, ob es Überlebende gibt... oder Anzeichen dafür, dass jemand entkommen konnte.", sourceObjective = "Durchsucht die Leichen von 12 Opfern der Dunwalds.", completion = "So viele Tote also? Dann ist es nicht sehr wahrscheinlich, dass jemand außer meinen Brüdern den Kampf überlebt hat. Das habe ich befürchtet.\n\nVielen Dank, dass Ihr Euch die Zeit genommen habt, für mich zu suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27643] = { id = 27643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnelly Dunwald", description = "Ihr sucht nach uns, und ich suche nach meinen Brüdern. Offensichtlich haben wir also schonmal eine Sache gemeinsam.\n\nDonnelly ist unser ältester Bruder. Bei seiner Körpergröße wird das deutlich, bei seinem Verstand jedoch eher weniger. Normalerweise hält er sich in den Ruinen im Norden auf, in der Hütte. Könntet Ihr vielleicht für mich nach ihm suchen? Es würde mich beruhigen, wenn ich wüsste, dass es ihm gut geht.", sourceObjective = "Findet Donnelly Dunwald.", completion = "Hallo, Freund! Ich glaube nicht, dass ich Euch kenne… Ich bin Donnelly Dunwald.\n\nUnd wie heißt Ihr? Ich glaube nicht, dass ich Euch kenne… Kenne ich Euch?", sourceObjectiveStatus = "unverified-source-field" }
